    { name = 'A Knight\'s Test', group = 'San d\'Oria', desc = 'Paladin unlock: solve Balasiel\'s task-book riddle, ending at a well in Davoi. From Balasiel, Watchdog Alley, Southern San d\'Oria.', steps = { { title = 'Requirements', note = '• Level 30, any job.\n• A Squire\'s Test II done.' }, { title = 'Steps', note = '• Accept Balasiel\'s test to receive the Book of Tasks (talk again if you declined).\n• Get the Book of the West from Baunise.\n• Get the Book of the East from Cahaurme (either order).\n• Holding both books, examine the Disused Well in Davoi to get the Knight\'s Soul.\n• Return it to Balasiel to unlock Paladin.' }, { title = 'Tips', note = '• Davoi is reached via Jugner Forest; its Orcs are aggressive and often outlevel you, so bring help or stay hidden.' }, { title = 'Reward', note = '• Kite Shield, key item 1744, San d\'Oria fame +20, title Tried and Tested Knight.' } } },
