    { name = 'Sharpening the Sword', group = 'San d\'Oria', desc = 'Find a whetstone in Ordelle\'s Caves for the boy\'s old blade. From Ailbeche, Parade Grounds, Northern San d\'Oria.', steps = { { title = 'Details', note = '• Needs: Level 40+; Job: PLD.\n• Key items to obtain: Ordelle Whetstone.\n• Fight: Polevik.\n• NPCs: Sobane (Southern San d\'Oria); Stalagmite (Ordelle\'s Caves).' }, { title = 'Reward', note = '• Honor Sword\n• San d\'Oria fame +20' } } },
    { name = 'A Boy\'s Dream', group = 'San d\'Oria', desc = 'Catch the big fish and take the treasure from its belly. From Ailbeche, Parade Grounds, Northern San d\'Oria. Only the NPCs are scripted here, so it may not be completable.', steps = {  } },
    { name = 'The Holy Crest', group = 'San d\'Oria', desc = 'Dragoon unlock: dig up a wyvern egg in the Maze of Shakhrami and guard it. From Oiheaurese, Cathedral, Northern San d\'Oria. Only the NPCs are scripted here, so it may not be completable.', steps = { { title = 'Requirements', note = '• Level 30, any job.\n• Quest enters your log only after you meet Morjean (step 3).' }, { title = 'Steps', note = '• Talk to Ceraulian (or Arminibit beside him) in Port San d\'Oria.\n• Talk to Novalmauge, who patrols a corridor in Bostaunieux Oubliette near map position 30, 20.\n• Speak with Morjean (Northern San d\'Oria).\n• Trade a Pickaxe to an Excavation Point in the Maze of Shakhrami to get a Wyvern Egg.\n• Return to Morjean and talk to him.\n• Trade the Wyvern Egg to the ??? in Meriphataud Mountains.\n• Get the Dragon Curse Remedy from Rahal in Chateau d\'Oraguille.\n• Enter the Hut Door at Ghelsba Outpost (via West Ronfaure) and defeat Cyranuce M Cutauleon.\n• Name your wyvern in the post-fight cutscene; Dragoon unlocks.' }, { title = 'Tips', note = '• Pickaxes are sold in city shops.\n• Digging yields an egg only while the quest needs one; you can hold just one.\n• Cyranuce M Cutauleon is level 32.\n• Fight cap: 6 players, 15 minutes; entry requires the Dragon Curse Remedy or prior completion.' } } },
    { name = 'A Craftsman\'s Work', group = 'San d\'Oria', desc = 'Find an Altepa polishing stone so Ranchuriome can repair a breastplate. From Miaux, near the Blacksmiths\' Guild, Northern San d\'Oria. Only the NPCs are scripted here, so it may not be completable.', steps = {  } },
    { name = 'Chasing Quotas', group = 'San d\'Oria', desc = 'Help Ceraulian of the Brugaire Consortium make his quota. From Ceraulian, Cargo Room A, Port San d\'Oria.', steps = { { title = 'Details', note = '• Needs: Prior quest: A Craftsman\'s Work.\n• Trade: Gold Hairpin.\n• Key items to obtain: Ranchuriomes Legacy.\n• Key items received: Shiny Earring.\n• Fight: Sturmtiger.\n• NPCs: Miaux (Northern San d\'Oria); Ardea (Bastok Markets); Esca (West Ronfaure); ??? (Batallia Downs).' }, { title = 'Reward', note = '• Drachen Brais\n• San d\'Oria fame +20' } } },
    { name = 'Knight Stalker', group = 'San d\'Oria', desc = 'Investigate attacks on the Royal Knights. From Rahal, Royal Knights\' Quarters, Chateau d\'Oraguille. Only the NPCs are scripted here, so it may not be completable.', steps = {  } },
    { name = 'Eco-Warrior', group = 'San d\'Oria', desc = 'Kill a pest in Ordelle\'s Caves per Rojaireaut and bring proof. From Norejaie, Lion Springs Tavern, Southern San d\'Oria.', steps = { { title = 'Details', note = '• Needs: San d\'Oria fame level 1.\n• Key items to obtain: Indigested Stalagmite.\n• Fight: Necroplasm.\n• NPCs: Rojaireaut (Ordelle\'s Caves); ??? (Ordelle\'s Caves).' }, { title = 'Reward', note = '• Dragon Chronicles\n• 5000 gil\n• San d\'Oria fame +20\n• Title: Vermillion Venturer' } } },
    { name = 'Methods Create Madness', group = 'San d\'Oria', desc = 'Polearm weapon-skill trial. From Balasiel, Watchdog Alley, Southern San d\'Oria.', steps = { { title = 'Details', note = '• Trade: Spear of Trials.\n• Key items to obtain: Annals of Truth.\n• Key items received: Weapon Training Guide; Map to the Annals of Truth.\n• Fight: Water Leaper.' }, { title = 'Reward', note = '• San d\'Oria fame +20' } } },
    { name = 'Souls in Shadow', group = 'San d\'Oria', desc = 'Scythe weapon-skill trial: lift the curse on the scythe. From Novalmauge, Bostaunieux Oubliette.', steps = { { title = 'Details', note = '• Trade: Scythe of Trials.\n• Key items to obtain: Annals of Truth.\n• Key items received: Weapon Training Guide; Map to the Annals of Truth.\n• Fight: Mokumokuren.' }, { title = 'Reward', note = '• San d\'Oria fame +20' } } },
    { name = 'A Taste for Meat', group = 'San d\'Oria', desc = 'Deliver five Hare Meat. From Thierride, Rusty Anchor Pub, Port San d\'Oria.', steps = { { title = 'Details', note = '• Trade: 5 × Hare Meat.\n• NPCs: Antreneau (Port San d\'Oria).' }, { title = 'Reward', note = '• 150 gil\n• San d\'Oria fame +20\n• Title: Rabbiter' } } },
    { name = 'Exit the Gambler', group = 'San d\'Oria', desc = 'Find runaway carpenter Varchet and send him back to work. From Aurege and Guilberdrier, Carpenters\' Guild, Northern San d\'Oria.', steps = { { title = 'Details', note = '• NPCs: Varchet (Southern San d\'Oria).' }, { title = 'Reward', note = '• 6000 EXP\n• Key item: key item 391\n• San d\'Oria fame +20\n• Title: Daybreak Gambler' } } },
    { name = 'Old Wounds', group = 'San d\'Oria', desc = 'Sword weapon-skill trial with Curilla. From Curilla, Temple Knights\' Quarters, Chateau d\'Oraguille.', steps = { { title = 'Details', note = '• Trade: Sapara of Trials.\n• Key items to obtain: Annals of Truth.\n• Key items received: Weapon Training Guide; Map to the Annals of Truth.\n• Fight: Girtablulu.' }, { title = 'Reward', note = '• San d\'Oria fame +20' } } },
    { name = 'A Timely Visit', group = 'San d\'Oria', desc = 'Help capture a suspect on La Theine Plateau. From Elmemague, Watchdog Alley, Southern San d\'Oria.', steps = { { title = 'Details', note = '• Needs: San d\'Oria fame level 4.\n• Fight: Giollemitte B Feroun; Skeleton Esquire NM.' }, { title = 'Reward', note = '• Medieval Collar\n• San d\'Oria fame +40\n• Title: Obsidian Storm' } } },
    { name = 'Trial-Size Trial by Ice', group = 'San d\'Oria', desc = 'Summoner only: ring the mini ice tuning fork at the Fei\'Yin protocrystal for a solo fight. From Castilchat, Watchtower, Northern San d\'Oria. Only the NPCs are scripted here, so it may not be completable.', steps = {  } },
    { name = 'Signed in Blood', group = 'San d\'Oria', desc = 'Bring a cathedral tapestry to prove your integrity to Sobane. From Sobane, House on Pikeman\'s Way, Southern San d\'Oria.', steps = { { title = 'Details', note = '• Needs: San d\'Oria fame level 3.\n• Trade: Ctdl. Tapestry.\n• Key items to obtain: Torn Out Pages.' }, { title = 'Reward', note = '• Cunning Earring\n• 3500 gil\n• San d\'Oria fame +30' } } },
    { name = 'Tea with a Tonberry?', group = 'San d\'Oria', desc = 'Talk with the Carpenters\' Landing Tonberries to learn who threatens the count. From Sobane, House on Pikeman\'s Way, Southern San d\'Oria.', steps = { { title = 'Details', note = '• Needs: San d\'Oria fame level 4; Prior quest: Signed in Blood.\n• Trade: Attohwa Ginseng; Treasury Gold.\n• Key items received: Tonberry Blackboard.\n• Fight: Hematic Cyst.' }, { title = 'Reward', note = '• Willpower Torque\n• San d\'Oria fame +40\n• Title: Talks with Tonberries' } } },
    { name = 'Spice Gals', group = 'San d\'Oria', desc = 'Find a sprig of Rivernewort for Rouva\'s cooking. From Rouva, Victory Square, Southern San d\'Oria.', steps = { { title = 'Details', note = '• Needs: Prior mission: Ancient Vows.\n• Key items to obtain: Rivernewort.' }, { title = 'Reward', note = '• Miratete\'s Mem.' } } },
    { name = 'Over the Hills and Far Away', group = 'San d\'Oria', desc = 'Follow Uncle Louverance across the Uleguerand Range via a cave on Thousandfall Ridge. From Antreneau, Rusty Anchor Pub, Port San d\'Oria. Only the NPCs are scripted here, so it may not be completable.', steps = {  } },
    { name = 'Lure of the Wildcat (San d\'Oria)', group = 'San d\'Oria', desc = 'Recruit for the mercenary company Salaheem\'s Sentinels. From Amutiyaal, Lion Square, Southern San d\'Oria.', steps = { { title = 'Details', note = '• Key items received: Red Sentinel Badge.' }, { title = 'Reward', note = '• Key item: key item 753\n• San d\'Oria fame +30' } } },
    { name = 'Atelloune\'s Lament', group = 'San d\'Oria', desc = 'Bring Atelloune a Ladybug Wing to set an Elvaan boy straight. Atelloune is in Southern San d\'Oria.', steps = { { title = 'Details', note = '• Needs: San d\'Oria fame level 2.\n• Trade: Ladybug Wing.' }, { title = 'Reward', note = '• Trainee Gloves\n• San d\'Oria fame +20' } } },
    { name = 'Thick Shells', group = 'San d\'Oria', desc = 'Deliver five beetle shells for medicine. From Vounebariont, Auction House, Port San d\'Oria. Only the NPCs are scripted here, so it may not be completable.', steps = {  } },
    { name = 'Trust: San d\'Oria', group = 'San d\'Oria', desc = 'Trust intro: Gondebaud sends you to Excenmille in Northern San d\'Oria. From Gondebaud, Lion Square, Southern San d\'Oria. Only the NPCs are scripted here, so it may not be completable.', steps = {  } },
    { name = 'The Siren\'s Tear', group = 'Bastok', desc = 'Find the Siren\'s Tear gem on the Gustaberg River shore; hear the bard\'s story in the Port Bastok restaurant first. From Wahid, South Auction House, Bastok Mines.', steps = { { title = 'Details', note = '• Trade: Siren\'s Tear.\n• NPCs: Otto (Port Bastok); Carmelo (Port Bastok); Echo Hawk (Bastok Mines); ??? that moves (North Gustaberg).' }, { title = 'Reward', note = '• 150 gil\n• Bastok fame +10\n• Title: Tearjerker' } } },
    { name = 'Beauty and the Galka', group = 'Bastok', desc = 'Take Zinc Ore (dropped by Gustaberg monsters) to Talib for Parraggoh. From Cornelia & Parraggoh, House, Bastok Mines.', steps = { { title = 'Details', note = '• Trade: Zinc Ore.\n• Key items received: Palborough Mines Logs.\n• NPCs: Talib (Port Bastok).' }, { title = 'Reward', note = '• Bronze Knife\n• Norg fame +30' } } },
    { name = 'Welcome to Bastok', group = 'Bastok', desc = 'Meet Powhatan\'s guest at the air travel agency wearing a shell shield. From Powhatan, Steaming Sheep Restaurant, Port Bastok.', steps = { { title = 'Details', note = '• NPCs: Bartolomeo (Port Bastok).' }, { title = 'Reward', note = '• Spatha\n• Bastok fame +20\n• Title: Bastok Welcoming Committee' } } },
    { name = 'Guest of Hauteur', group = 'Bastok', desc = 'Meet Powhatan\'s guest at the air travel agency with a maul equipped. From Powhatan, Steaming Sheep Restaurant, Port Bastok.', steps = { { title = 'Details', note = '• Needs: Level 31+; Bastok fame level 3; Prior quest: Welcome to Bastok.\n• Key items received: Letter from Domien.\n• NPCs: Steel Bones (Port Bastok).' }, { title = 'Reward', note = '• Targe\n• Bastok fame +30' } } },
    { name = 'The Quadav\'s Curse', group = 'Bastok', desc = 'Find Corann something big enough to hide in. From Corann, House, Port Bastok.', steps = { { title = 'Details', note = '• Trade: Quadav Backplate.' }, { title = 'Reward', note = '• Bronze Subligar\n• Bastok fame +20' } } },
    { name = 'Out of One\'s Shell', group = 'Bastok', desc = 'Help Ronan coax his son Corann out of his shell. From Ronan, House, Port Bastok.', steps = { { title = 'Details', note = '• Needs: Bastok fame level 2; Prior quest: The Quadav\'s Curse.\n• Trade: 3 × Shell Bug.' }, { title = 'Reward', note = '• Monk\'s Headgear\n• Bastok fame +20\n• Title: Shell Outer' } } },
    { name = 'Hearts of Mythril', group = 'Bastok', desc = 'Lay Elki\'s bouquet at the Palborough Pioneers monument in North Gustaberg. From Elki, Bat\'s Lair Inn, Bastok Mines.', steps = { { title = 'Details', note = '• Key items received: Bouquet for the Pioneers.\n• NPCs: Monument (North Gustaberg).' }, { title = 'Reward', note = '• Sitabaki\n• Bastok fame +20\n• Title: Pursuer of the Past' } } },
    { name = 'The Eleventh\'s Hour', group = 'Bastok', desc = 'Identify the eleventh Palborough Pioneer; look for clues in the mines. From Elki, Bat\'s Lair Inn, Bastok Mines.', steps = { { title = 'Details', note = '• Needs: Bastok fame level 3; Prior quest: Hearts of Mythril.\n• Key items to obtain: Old Toolbox.\n• NPCs: Babenn (Bastok Mines); Old Toolbox (Palborough Mines).' }, { title = 'Reward', note = '• Small Sword\n• Bastok fame +30\n• Title: Pursuer of the Truth' } } },
    { name = 'Shady Business', group = 'Bastok', desc = 'Sell Talib four Zinc Ore for gil. From Talib, Tenshodo Warehouse, Port Bastok.', steps = { { title = 'Details', note = '• Needs: Prior quest: Beauty and the Galka.\n• Trade: 4 × Zinc Ore.' }, { title = 'Reward', note = '• 350 gil' } } },
    { name = 'A Foreman\'s Best Friend', group = 'Bastok', desc = 'Track down the missing foreman of Gudav\'s crew. From Gudav, Construction Site, Port Bastok.', steps = { { title = 'Details', note = '• Trade: Dog Collar.\n• Key items received: Map of the Gusgen Mines.' }, { title = 'Reward', note = '• Bastok fame +20' } } },
    { name = 'Breaking Stones', group = 'Bastok', desc = 'Horatius asks for a rare stone that only turns up in Dangruf Wadi (J-5) during the day.', steps = { { title = 'Start', note = '• Horatius, Trader\'s Home, Bastok Markets.\n• Needs Bastok fame 2.' }, { title = 'Trade', note = '• Dangruf Stone, from the ??? in Dangruf Wadi.' }, { title = 'Reward', note = '• 400 gil, Bastok fame +30.' } } },
    { name = 'The Cold Light of Day', group = 'Bastok', desc = 'A beast near the South Gustaberg lighthouse took a parcel meant for Malene; Dalzakk knows how to draw it out so you can get the parcel back.', steps = { { title = 'Start', note = '• Malene, House, Bastok Markets.' }, { title = 'Trade', note = '• Steam Clock.' }, { title = 'Reward', note = '• 500 gil, Bastok fame +10, title Crab Crusher.' } } },
    { name = 'Gourmet', group = 'Bastok', desc = 'Salimah needs a special ingredient for a dish she is cooking.', steps = { { title = 'Start', note = '• Salimah, Trader\'s Home, Bastok Markets.' }, { title = 'Reward', note = '• Title: Mommy\'s Helper.' } } },
    { name = 'The Elvaan Goldsmith', group = 'Bastok', desc = 'Michea, an independent goldsmith, needs a copper ingot to finish an order.', steps = { { title = 'Start', note = '• Michea, House, Bastok Markets.' }, { title = 'Trade', note = '• Copper Ingot.' }, { title = 'Reward', note = '• 180 gil, Bastok fame +10.' } } },
    { name = 'A Flash in the Pan', group = 'Bastok', desc = 'Aquillina buys four flint stones to light her oven.', steps = { { title = 'Start', note = '• Aquillina, House, Bastok Markets.' }, { title = 'Trade', note = '• 4 × Flint Stone.' }, { title = 'Reward', note = '• 100 gil, Bastok fame +10.' } } },
    { name = 'Smoke on the Mountain', group = 'Bastok', desc = 'Hungry Wolf wants a Galkan sausage after hearing Offa praise it.', steps = { { title = 'Start', note = '• Hungry Wolf, Craftsmen\'s Eatery, Metalworks.' }, { title = 'Trade', note = '• Galkan Sausage.\n• Offa is in Bastok Markets.' }, { title = 'Reward', note = '• 300 gil, Bastok fame +10, title Hot Dog.' } } },
    { name = 'Stamp Hunt', group = 'Bastok', desc = 'Collect a stamp from each guard on Arawn\'s list across Bastok to fill the Stamp Sheet.', steps = { { title = 'Start', note = '• Arawn, Gold Street, Bastok Markets; you receive the Stamp Sheet key item.' }, { title = 'Stamps', note = '• Pavel (Bastok Markets)\n• Deadly Spider, Tall Mountain (Bastok Mines)\n• Elayne, Romualdo (Metalworks)\n• Ehrhard, Latifah (Port Bastok)' }, { title = 'Reward', note = '• Leather Gorget, Bastok fame +20, title Stampeder.' } } },
    { name = 'Forever to Hold', group = 'Bastok', desc = 'Qiji wants a brass hairpin as a gift for his wife Romilda.', steps = { { title = 'Start', note = '• Qiji, Docks, Port Bastok.\n• Needs Bastok fame 2.' }, { title = 'Trade', note = '• Brass Hairpin.' }, { title = 'Reward', note = '• 300 gil, Bastok fame +20, title Qiji\'s Friend.' } } },
    { name = 'Till Death Do Us Part', group = 'Bastok', desc = 'Romilda wants cotton gloves to give her husband Qiji.', steps = { { title = 'Start', note = '• Romilda, Docks, Port Bastok.\n• Needs Bastok fame 3 and Forever to Hold complete.' }, { title = 'Trade', note = '• Cotton Gloves.' }, { title = 'Reward', note = '• 2000 gil, Bastok fame +30, title Qiji\'s Rival.' } } },
    { name = 'Fallen Comrades', group = 'Bastok', desc = 'Pavvke wants the name tags of Galka who died in Palborough Mines twenty years ago.', steps = { { title = 'Start', note = '• Pavvke, House, Bastok Mines.\n• Needs Bastok fame 2.' }, { title = 'Trade', note = '• Silver Name Tag.' }, { title = 'Reward', note = '• 550 gil, Bastok fame +10.' } } },
    { name = 'Rivals', group = 'Bastok', desc = 'Detzo borrows a mythril sallet to beat his rival in a contest.', steps = { { title = 'Start', note = '• Detzo, Ore Street, Bastok Mines.\n• Needs Bastok fame 3.' }, { title = 'Trade', note = '• Mythril Sallet.' }, { title = 'Reward', note = '• Wolf Gorget, Bastok fame +30, title Contest Rigger.' } } },
    { name = 'Mom, the Adventurer?', group = 'Bastok', desc = 'Deliver a copper ring from Nbu Latteh to her daughter.', steps = { { title = 'Start', note = '• Nbu Latteh, Gold Street, Bastok Markets.' }, { title = 'Steps', note = '• Trade a Copper Ring.\n• Roh Latteh (Bastok Mines) is the daughter; you get the Letter from Roh Latteh key item.' }, { title = 'Reward', note = '• Bastok fame +10, title Ringbearer.' } } },
    { name = 'The Signpost Marks the Spot', group = 'Bastok', desc = 'Dig up the key item hidden beneath a Konschtat Highlands signpost and take it to Nbu Latteh\'s home.', steps = { { title = 'Start', note = '• Nbu Latteh, Gold Street, Bastok Markets.\n• Needs Bastok fame 2 and Mom, the Adventurer? complete.' }, { title = 'Steps', note = '• Check the Signpost in Konschtat Highlands for the Painting of a Windmill key item.\n• Roh Latteh (Bastok Mines) is also involved.' }, { title = 'Reward', note = '• Linen Robe, Bastok fame +20, title Treasure Scavenger.' } } },
    { name = 'Past Perfect', group = 'Bastok', desc = 'Evi\'s old mission orders are buried by a windmill in Konschtat Highlands; fetch them.', steps = { { title = 'Start', note = '• Evi, Harbor Way, Port Bastok.\n• Needs Bastok fame 2.' }, { title = 'Steps', note = '• Check the ??? in Konschtat Highlands for the Tattered Mission Orders key item.' }, { title = 'Reward', note = '• Scale Mail, Bastok fame +20.' } } },
    { name = 'Stardust', group = 'Bastok', desc = 'Baldric needs Valkurm sunsand, which only shows up in dust storms.', steps = { { title = 'Start', note = '• Baldric, Darksteel Forge, Metalworks.\n• Needs Bastok fame 2.' }, { title = 'Trade', note = '• Sunsand, from the ??? in Valkurm Dunes.' }, { title = 'Reward', note = '• 300 gil, Bastok fame +10.' } } },
    { name = 'Mean Machine', group = 'Bastok', desc = 'Unlucky Rat has no machine oil left and needs a substitute for a factory machine.', steps = { { title = 'Start', note = '• Unlucky Rat, Cermet Refinery, Metalworks.\n• Needs Bastok fame 2.' }, { title = 'Trade', note = '• Slime Oil.' }, { title = 'Reward', note = '• Warp, Bastok fame +20.' } } },
    { name = 'Cid\'s Secret', group = 'Bastok', desc = 'As a personal favour, Cid asks you to help the manager of the Steaming Sheep Restaurant.', steps = { { title = 'Start', note = '• Cid, Cid\'s Lab, Metalworks.\n• Needs Bastok fame 4.' }, { title = 'Steps', note = '• Hilda (Port Bastok) is the manager.\n• Trade Rolanberry 874; you get the Unfinished Letter key item.' }, { title = 'Reward', note = '• Ram Mantle, Bastok fame +40.' } } },
    { name = 'The Usual', group = 'Bastok', desc = 'Hilda needs a king truffle to serve a longtime Steaming Sheep customer.', steps = { { title = 'Start', note = '• Hilda, Steaming Sheep Restaurant, Port Bastok.\n• Needs Bastok fame 5 and Cid\'s Secret complete.' }, { title = 'Steps', note = '• Trade a King Truffle; you get the Steaming Sheep Invitation key item.\n• Raibaht (Metalworks) is also involved.' }, { title = 'Reward', note = '• Speed Bow, Bastok fame +50, title "Steaming Sheep" Regular.' } } },
    { name = 'Blade of Darkness', group = 'Bastok', desc = 'Zeid, the dark knight, was spotted in Palborough Mines; finding him earns the great sword Chaosbringer, and 100 kills with it unlock Dark Knight. Requires level 30; only WAR (and DRK) can equip Chaosbringer, so kill as Warrior.', steps = { { title = 'Step 1', note = '• Speak with Gumbah in Bastok Mines.' }, { title = 'Step 2', note = '• In Palborough Mines (via North Gustaberg), pull the Dock Lever to ride into Zeruhn Mines; a cutscene gives Chaosbringer.' }, { title = 'Step 3', note = '• Equip Chaosbringer and defeat 100 monsters.' }, { title = 'Step 4', note = '• Enter Beadeaux from Pashhow Marshlands; the cutscene unlocks Dark Knight.' }, { title = 'Tips', note = '• Only a regular melee hit landing the killing blow counts; weapon skills, spells and pets do not.\n• Any monster counts, including ones that give no EXP; the sword deals little damage.\n• Dropping Chaosbringer may reset the count; ride to Zeruhn Mines again to replace it.\n• Keep a free inventory slot before the ride or no sword is given and the scene repeats.\n• Keep the sword: Blade of Death needs it and kills there continue the count toward 200.' }, { title = 'Reward', note = '• Key item 1745, Bastok fame +20, title Dark Sider.' } } },
    { name = 'Father Figure', group = 'Bastok', desc = 'Michea needs a silver ingot to make a gift for Dalzakk, who raised her.', steps = { { title = 'Start', note = '• Michea, House, Bastok Markets.\n• Needs Bastok fame 2 and The Elvaan Goldsmith complete.' }, { title = 'Trade', note = '• Silver Ingot.' }, { title = 'Reward', note = '• 2200 gil, Bastok fame +20.' } } },
    { name = 'The Return of the Adventurer', group = 'Bastok', desc = 'Gwill needs cinnamon to finish a present for Dalzakk.', steps = { { title = 'Start', note = '• Gwill, House, Bastok Markets.\n• Needs Bastok fame 3 and Father Figure complete.' }, { title = 'Trade', note = '• Cinnamon.' }, { title = 'Reward', note = '• Cotton Headband, Bastok fame +30, title Kulatz Bridge Companion.' } } },
    { name = 'Drachenfall', group = 'Bastok', desc = 'Black Mud wants water from Drachenfall in North Gustaberg.', steps = { { title = 'Start', note = '• Black Mud, Ore Street, Bastok Mines.\n• Needs Bastok fame 2.' }, { title = 'Steps', note = '• Fill a Brass Canteen at the Waterfall Base in North Gustaberg.\n• Trade the Drachenfall Water to Black Mud.' }, { title = 'Reward', note = '• 2000 gil, Bastok fame +20, title Drachenfall Ascetic.' } } },
    { name = 'Vengeful Wrath', group = 'Bastok', desc = 'Hunt Quadav for Goraow and return with a Quadav helm as proof.', steps = { { title = 'Start', note = '• Goraow, Ore Street Stairs, Bastok Mines.\n• Needs Bastok fame 3.' }, { title = 'Trade', note = '• Quadav Helm.' }, { title = 'Reward', note = '• 900 gil, Bastok fame +16, title Avenger.' } } },
    { name = 'Beadeaux Smog', group = 'Bastok', desc = 'High Bear wants a polluted soil sample from a heavily smoking spot in Beadeaux.', steps = { { title = 'Start', note = '• High Bear, Watermill Square, Metalworks.\n• Needs Bastok fame 4.' }, { title = 'Steps', note = '• Get the key item from the ??? in Beadeaux and return.' }, { title = 'Reward', note = '• Bastok fame +40, title Beadeaux Surveyor.' } } },
    { name = 'The Curse Collector', group = 'Bastok', desc = 'Let the Afflictor and Mute statues in Beadeaux curse you so Zon-Fobun\'s cursepaper records their spells.', steps = { { title = 'Start', note = '• Zon-Fobun, near Sororo\'s, Bastok Markets.\n• Needs Bastok fame 4; you get the Cursepaper key item.' }, { title = 'Steps', note = '• Get cursed by the statues (The Mute, Afflictors) in Beadeaux, then return.' }, { title = 'Reward', note = '• Poison Cesti, Bastok fame +40.' } } },
    { name = 'Fear of Flying', group = 'Bastok', desc = 'Kurando says a beast appears in Rolanberry Fields when airships fly over; bring its drop as proof.', steps = { { title = 'Start', note = '• Kurando, Docks, Port Bastok.\n• Needs Bastok fame 3.' }, { title = 'Trade', note = '• Silkworm Egg.' }, { title = 'Reward', note = '• Black Neckerchief, Bastok fame +30, title Airship Denouncer.' } } },
    { name = 'The Wisdom of Elders', group = 'Bastok', desc = 'Benita\'s chimney is clogged; her mother-in-law, out with Benita\'s daughter, knows what clears it.', steps = { { title = 'Start', note = '• Benita, House, Port Bastok.' }, { title = 'Steps', note = '• Ask Tete (Port Bastok).\n• Trade Bomb Ash to Benita.' }, { title = 'Reward', note = '• Traveler\'s Hat, Bastok fame +20.' } } },
    { name = 'Groceries', group = 'Bastok', desc = 'Take Tami\'s note to her husband Zelman, who works in Zeruhn Mines.', steps = { { title = 'Start', note = '• Tami, near Residential Area, Bastok Mines; you get the Tamis Note key item.' }, { title = 'Steps', note = '• Deliver the note to Zelman (Zeruhn Mines).\n• Trade Meat Jerky.' }, { title = 'Reward', note = '• Rabbit Mantle, 10 gil, Bastok fame +10.' } } },
    { name = 'The Bare Bones', group = 'Bastok', desc = 'Degenhard wants the item he relies on to stay young.', steps = { { title = 'Start', note = '• Degenhard, near Galkan Bridge, Bastok Markets.' }, { title = 'Trade', note = '• Bone Chip.\n• Biggorf (Bastok Markets) is also involved.' }, { title = 'Reward', note = '• 6000 EXP, key item 392, Bastok fame +20.' } } },
    { name = 'Minesweeper', group = 'Bastok', desc = 'Thin out the monsters in Zeruhn Mines and bring Gerbaum three pinches of Zeruhn soot.', steps = { { title = 'Start', note = '• Gerbaum, Work Area, Bastok Mines.' }, { title = 'Trade', note = '• 3 × Zeruhn Soot.' }, { title = 'Reward', note = '• 150 gil, Bastok fame +10, title Zeruhn Sweeper.' } } },
    { name = 'The Darksmith', group = 'Bastok', desc = 'Mighty Fist needs two chunks of darksteel ore; Gusgen Mines yields it, and some report finding it in Zeruhn Mines.', steps = { { title = 'Start', note = '• Mighty Fist, Darksteel Forge, Metalworks.\n• Needs Bastok fame 3.' }, { title = 'Trade', note = '• 2 × Darksteel Ore.' }, { title = 'Reward', note = '• 8000 gil, Bastok fame +16.' } } },
    { name = 'Buckets of Gold', group = 'Bastok', desc = 'Foss buys rusty buckets once you have fished up five.', steps = { { title = 'Start', note = '• Foss, Firewater Circle, Bastok Markets.' }, { title = 'Trade', note = '• 5 × Rusty Bucket.' }, { title = 'Reward', note = '• 300 gil, Bastok fame +10, title Bucket Fisher.' } } },
    { name = 'The Stars of Ifrit', group = 'Bastok', desc = 'Agapito wants a riddle about a bird bringing a letter to the sky ship under a full moon solved, and the letter brought back.', steps = { { title = 'Start', note = '• Agapito, near Air Travel Agency, Port Bastok.\n• Needs Bastok fame 3 and the Airship Pass key item.' }, { title = 'Steps', note = '• Check the ??? on the San d\'Oria-Jeuno Airship, then return.' }, { title = 'Reward', note = '• 2100 gil, Bastok fame +30, title Star of Ifrit.' } } },
    { name = 'Love and Ice', group = 'Bastok', desc = 'Throw Carmelo\'s song sheet for his old love into Mirror Lake on Beaucedine Glacier.', steps = { { title = 'Start', note = '• Carmelo, Steaming Sheep Restaurant, Port Bastok.\n• Needs Bastok fame 5 and The Siren\'s Tear complete; you get Carmelos Song Sheet.' }, { title = 'Steps', note = '• Use the Mirror Pond at J-8, Beaucedine Glacier, then return.' }, { title = 'Reward', note = '• Lamia Harp, Bastok fame +50, title Sorrow Drowner.' } } },
    { name = 'Brygid the Stylist', group = 'Bastok', desc = 'Return to Brygid wearing a robe and a bronze subligar.', steps = { { title = 'Start', note = '• Brygid, Gold Street, Bastok Markets.' }, { title = 'Reward', note = '• Gloves, Bastok fame +20, title Brygid-approved.' } } },
    { name = 'The Gustaberg Tour', group = 'Bastok', desc = 'Test Izabele\'s tour idea: a party of at least three, all level 15 or lower, must reach Hunting Bear at Drachenfall in North Gustaberg.', steps = { { title = 'Start', note = '• Izabele, near Cid\'s Lab, Metalworks.' }, { title = 'Steps', note = '• Travel as the party to Hunting Bear, North Gustaberg.' }, { title = 'Reward', note = '• 500 gil, Bastok fame +20, title Gustaberg Tourist.' } } },
    { name = 'Bite the Dust', group = 'Bastok', desc = 'Sand bats threaten Yazan\'s Selbina–Bastok trade route; bring a sand bat fang.', steps = { { title = 'Start', note = '• Yazan, Harbor Way, Port Bastok.\n• Needs Bastok fame 2.' }, { title = 'Trade', note = '• Sand Bat Fang.' }, { title = 'Reward', note = '• 350 gil, Bastok fame +10, title Sand Blaster.' } } },
    { name = 'Blade of Death', group = 'Bastok', desc = 'A letter from Zeid sets a new trial for you and Chaosbringer.', steps = { { title = 'Requirements', note = '• Bastok fame 3 and Blade of Darkness complete; you get the Letter from Zeid key item.' }, { title = 'Steps', note = '• Gumbah (Bastok Mines) and a ??? in Gusgen Mines are involved.\n• Trade Chaosbringer.' }, { title = 'Reward', note = '• Deathbringer, Bastok fame +30, title Black Death.' } } },
    { name = 'Silence of the Rams', group = 'Bastok', desc = 'A Tenshodo test: kill two giant rams and bring Paujean their horns.', steps = { { title = 'Start', note = '• Paujean, Tenshodo Warehouse, Port Bastok.\n• Needs Norg fame 2.' }, { title = 'Trade', note = '• Lumbering Horn and Rampaging Horn.' }, { title = 'Reward', note = '• Purple Belt, Norg fame +20, title Purple Belt.' } } },
    { name = 'Altana\'s Sorrow', group = 'Bastok', desc = 'Virnage needs divine paint to restore Altana\'s statue; look in the citadel on Sauromugue Champaign.', steps = { { title = 'Start', note = '• Virnage, Bat\'s Lair Inn, Bastok Mines.\n• Level 10+, Bastok fame 4.' }, { title = 'Steps', note = '• Get the Bucket of Divine Paint key item from the ??? in Garlaige Citadel.\n• You receive the Letter from Virnage key item; Eperdur (Northern San d\'Oria) is involved.' }, { title = 'Reward', note = '• Teleport-Dem, Bastok fame +40, title Pilgrim to Dem.' } } },
    { name = 'A Lady\'s Heart', group = 'Bastok', desc = 'Win over Valah Molkot with a gift; she hints at something red.', steps = { { title = 'Start', note = '• Valah Molkot, near Residential Area, Port Bastok.' }, { title = 'Trade', note = '• Amaryllis.' }, { title = 'Reward', note = '• Bastok fame +30.' } } },
    { name = 'Ghosts of the Past', group = 'Bastok', desc = 'Repeat Cornelia\'s trial in Gusgen Mines: use a pickaxe on a hole to draw out the Wandering Ghost, defeat it and bring back its miner\'s pendant.', steps = { { title = 'Start', note = '• Oggbi, Steaming Sheep Restaurant, Port Bastok.\n• MNK level 40+.' }, { title = 'Trade', note = '• Miner\'s Pendant (from the ??? fight in Gusgen Mines).' }, { title = 'Reward', note = '• Beat Cesti, Bastok fame +20.' } } },
    { name = 'The First Meeting', group = 'Bastok', desc = 'Oggbi sends you to Fei\'Yin to aid his student Dalzakk.', steps = { { title = 'Start', note = '• Oggbi, Steaming Sheep Restaurant, Port Bastok.\n• MNK level 50+, Ghosts of the Past complete.' }, { title = 'Steps', note = '• At Hide Flap (2) in Davoi, defeat Bilopdop and Deloknok.\n• Key items: San Dorian Martial Arts Scroll, Letter from Dalzakk.' }, { title = 'Reward', note = '• Temple Gaiters, Bastok fame +20.' } } },
    { name = 'True Strength', group = 'Bastok', desc = 'Defeat a strong Yagudo in Castle Oztroja, lured with Yagudo drink.', steps = { { title = 'Start', note = '• Ayame, Cannonry, Metalworks.\n• MNK level 50+, The First Meeting complete.' }, { title = 'Steps', note = '• Trade Yagudo Drink at the ??? in Castle Oztroja and defeat Huu Xalmo the Savage.\n• Trade the Xalmo Feather to Ayame.' }, { title = 'Reward', note = '• Temple Hose, Bastok fame +20, title Paragon of Monk Excellence.' } } },
    { name = 'The Doorman', group = 'Bastok', desc = 'Phara needs sword grip material from a Davoi tent to fix her son\'s sword for her grandson.', steps = { { title = 'Start', note = '• Phara, near Residential Area, Bastok Mines.\n• WAR level 40+.' }, { title = 'Steps', note = '• At Hide Flap (1) in Davoi, defeat Barakbok and Gavotvut for Sword Grip Material.\n• Naji (Metalworks) is involved; you get Yasins Sword key item.' }, { title = 'Reward', note = '• Razor Axe, Bastok fame +20.' } } },
    { name = 'The Talekeeper\'s Truth', group = 'Bastok', desc = 'Deidogg wants to discredit Raogrimm: kill the Quadav nest guardian in Palborough Mines and take the mottled Quadav egg.', steps = { { title = 'Start', note = '• Deidogg, Ore Street, Bastok Mines.\n• WAR level 50+, The Doorman complete.' }, { title = 'Steps', note = '• Trade Parasite Skin at the ??? in Palborough Mines and defeat Ni Ghu Nestfender.\n• Trade the Mottled Qdv. Egg; Phara is also involved.' }, { title = 'Reward', note = '• Fighter\'s Calligae, Bastok fame +20.' } } },
    { name = 'The Talekeeper\'s Gift', group = 'Bastok', desc = 'Goblin thieves in Behemoth\'s Dominion stole Raogrimm\'s gift to San d\'Oria; Deidogg wants you to claim it before the Musketeers do.', steps = { { title = 'Start', note = '• Deidogg, Ore Street, Bastok Mines.\n• WAR level 50+, The Talekeeper\'s Truth complete.' }, { title = 'Steps', note = '• Detzo (Bastok Mines) is involved.\n• Trade a Ginger Cookie at the ??? in Behemoth\'s Dominion; defeat Doglix Muttsnout, Moxnix Nightgoggle and Picklix Longindex.' }, { title = 'Reward', note = '• Fighter\'s Lorica, Bastok fame +20, title Paragon of Warrior Excellence.' } } },
    { name = 'Dark Legacy', group = 'Bastok', desc = 'Recover a book about the Galka darksteel formula.', steps = { { title = 'Start', note = '• Raibaht, Cid\'s Lab, Metalworks.\n• DRK level 40+.' }, { title = 'Steps', note = '• NPCs: Mighty Fist (Metalworks), Cochal-Monchal (Windurst Waters), Quu Bokye (Giddeus).\n• Trade a Yagudo Cherry at the ??? in Giddeus; defeat Vaa Huja the Erudite for the Darksteel Formula.\n• You get the Letter from the Darksteel Forge key item.' }, { title = 'Reward', note = '• Raven Scythe, Bastok fame +20.' } } },
    { name = 'Dark Puppet', group = 'Bastok', desc = 'Zeid has found a corrupted weapon made by darksteel smith Gerwitz; join him to deal with it.', steps = { { title = 'Start', note = '• Cid, Cid\'s Lab, Metalworks.\n• DRK level 50+, Dark Legacy complete.' }, { title = 'Steps', note = '• In Ordelle\'s Caves use the ???, ??? (Sword) and ??? (Soul).\n• Fights: Dark Puppet Offset, Gerwitzs Soul.\n• Items: Darksteel Ingot, Gerwitz\'s Axe, Gerwitz\'s Sword.' }, { title = 'Reward', note = '• Chaos Sollerets, Bastok fame +20.' } } },
    { name = 'Blade of Evil', group = 'Bastok', desc = 'Lure out a rampaging Gerwitz weapon where the Crystal Lines meet using strong Quadav blood, then destroy it.', steps = { { title = 'Start', note = '• Zeid.\n• DRK level 50+, Dark Puppet complete.' }, { title = 'Steps', note = '• Trade Qdv. Mage Blood at the ??? in Middle Delkfutt\'s Tower; defeat Gerwitzs Scythe.' }, { title = 'Reward', note = '• Chaos Burgeonet, Bastok fame +20, title Paragon of Dark Knight Excellence.' } } },
    { name = 'Ayame and Kaede', group = 'Bastok', desc = 'Ensetsu wants back an item he sold to the Tenshodo, who will only swap it for a strangely shaped coral from Korroloka Tunnel; finishing unlocks Ninja. Level 30, any job.', steps = { { title = 'Step 1', note = '• Speak with Kaede in Port Bastok.' }, { title = 'Step 2', note = '• Speak with Kagetora.' }, { title = 'Step 3', note = '• Speak with Ensetsu, close to Kaede.' }, { title = 'Step 4', note = '• In Korroloka Tunnel (via Zeruhn Mines) examine the ???, then kill the three Korroloka Leeches.' }, { title = 'Step 5', note = '• Examine the ??? again for the Strangely Shaped Coral.' }, { title = 'Step 6', note = '• Give the coral to Ensetsu.' }, { title = 'Step 7', note = '• Speak with Ryoma in Norg; he trades it for a Sealed Dagger.' }, { title = 'Step 8', note = '• Bring the dagger to Ensetsu to unlock Ninja.' }, { title = 'Tips', note = '• All three Leeches attack at once, each level 32 on this server.\n• Re-examine the ??? immediately after the fight, before zoning.\n• Party members on the same step must examine the ??? before the spawner does, since it then vanishes for a time.\n• Reach Norg through Sea Serpent Grotto.' }, { title = 'Reward', note = '• Key item 1750, Norg fame +20, title Shadow Walker.' } } },
    { name = 'Trial by Earth', group = 'Bastok', desc = 'Strike the tuning fork of earth on the Quicksand Caves protocrystal to reach the trial.', steps = { { title = 'Start', note = '• Juroro, near drawbridge, Port Bastok.\n• Needs Bastok fame 6; you get the Tuning Fork of Earth.' }, { title = 'Steps', note = '• Win the Trial By Earth battlefield; you get Whisper of Tremors.' }, { title = 'Reward', note = '• 10000 gil, Bastok fame +60.' } } },
    { name = 'A Test of True Love', group = 'Bastok', desc = 'To cure Dariah, collect the scattered pages of the Chanson de Liberte: "Un Moment," "L\'Ephemere" and "L\'Ancienne."', steps = { { title = 'Start', note = '• Carmelo, Steaming Sheep Restaurant, Port Bastok.\n• Needs Bastok fame 6 and Love and Ice complete.' }, { title = 'Reward', note = '• 10000 gil, Bastok fame +70.' } } },
    { name = 'Lovers in the Dusk', group = 'Bastok', desc = 'Bury the finished Chanson de Liberte at dusk at the spring ringed by white-flowered trees in the Sanctuary of Zi\'Tah.', steps = { { title = 'Start', note = '• Carmelo, Steaming Sheep Restaurant, Port Bastok.\n• Needs Bastok fame 6 and A Test of True Love complete; you get Chanson De Liberte.' }, { title = 'Reward', note = '• Siren Flute, Bastok fame +70.' } } },
    { name = 'Wish Upon a Star', group = 'Bastok', desc = 'Enu wants a fallen star from a southern jungle, possibly inside a tree.', steps = { { title = 'Start', note = '• Enu, Firewater Circle, Bastok Markets.\n• Needs Bastok fame 5.' }, { title = 'Steps', note = '• Zacc and Malene (Bastok Markets) are involved.\n• Items: Hatchet, Fallen Star.' }, { title = 'Reward', note = '• 4 × Cactus Stems, Bastok fame +50.' } } },
    { name = 'Eco-Warrior', group = 'Bastok', desc = 'Eliminate an ecological threat in Gusgen Mines as Degga wants, and bring proof to Raifa.', steps = { { title = 'Start', note = '• Raifa, Steaming Sheep Restaurant, Port Bastok.\n• Needs Bastok fame 1.' }, { title = 'Steps', note = '• Speak with Degga, then at the ??? in Gusgen Mines defeat Pudding.\n• Get the Indigested Ore key item and return.' }, { title = 'Reward', note = '• Dragon Chronicles, 5000 gil, Bastok fame +20, title Cerulean Soldier.' } } },
    { name = 'The Weight of Your Limits', group = 'Bastok', desc = 'Train with Iron Eater\'s axe and return it to the President\'s Office once you hit your limit.', steps = { { title = 'Start', note = '• Iron Eater, in front of the President\'s Office, Metalworks.' }, { title = 'Steps', note = '• Use the Axe of Trials; you get the Weapon Training Guide and Map to the Annals of Truth.\n• Defeat Greenman for the Annals of Truth, then return.' }, { title = 'Reward', note = '• Bastok fame +20.' } } },
    { name = 'Shoot First, Ask Questions Later', group = 'Bastok', desc = 'Help Cid try out a new firearm, then go back to his lab after the gun stops working right.', steps = { { title = 'Start', note = '• Speak with Cid in Cid\'s Lab, Metalworks.' }, { title = 'Items to trade', note = '• Gun of Trials' }, { title = 'Key items needed', note = '• Annals of Truth' }, { title = 'Key items you get', note = '• Weapon Training Guide\n• Map to the Annals of Truth' }, { title = 'Fights', note = '• Beet Leafhopper' }, { title = 'Reward', note = '• Bastok fame +20.' } } },
    { name = 'Inheritance', group = 'Bastok', desc = 'Zeid\'s letter asks you to train with a sword left by the warrior Werei so his technique is not lost.', steps = { { title = 'Start', note = '• Gumbah, House, Bastok Mines.' }, { title = 'Steps', note = '• Use the Sword of Trials; you get the Weapon Training Guide and Map to the Annals of Truth.\n• Defeat Maharaja for the Annals of Truth, then return.' }, { title = 'Reward', note = '• Bastok fame +20.' } } },
    { name = 'The Walls of Your Mind', group = 'Bastok', desc = 'Train with Oggbi\'s cesti and return to him when they can teach you no more.', steps = { { title = 'Start', note = '• Oggbi, Steaming Sheep Restaurant, Port Bastok.' }, { title = 'Steps', note = '• Use the Knuckles of Trials; you get the Weapon Training Guide and Map to the Annals of Truth.\n• Defeat Bodach for the Annals of Truth, then return.' }, { title = 'Reward', note = '• Bastok fame +20.' } } },
    { name = 'Trial-Size Trial by Earth', group = 'Bastok', desc = 'A mini tuning fork of earth opens a solo fight at the Quicksand Caves protocrystal; summoners only.', steps = { { title = 'Start', note = '• Ferrol, near drawbridge, Port Bastok.\n• SMN level 20+, Bastok fame 2.' }, { title = 'Steps', note = '• Win the Trial Size Trial By Earth battlefield.' }, { title = 'Reward', note = '• Instant Warp, Bastok fame +20.' } } },
    { name = 'Faded Promises', group = 'Bastok', desc = 'Track down whoever is threatening Senator Alois; first find a diary in Palborough Mines and give it to Kagetora.', steps = { { title = 'Start', note = '• Ayame, Cannonry, Metalworks.\n• NIN level 20+, Bastok fame 4.' }, { title = 'Steps', note = '• Find the Diary of Mukunda key item in Palborough Mines.\n• NPCs: Kagetora (Port Bastok), Romualdo and Alois (Metalworks).' }, { title = 'Reward', note = '• Fukuro, Norg fame +20, title Assassin Reject.' } } },
    { name = 'Brygid the Stylist Returns', group = 'Bastok', desc = 'Brygid has a new outfit request for you to shop for.', steps = { { title = 'Start', note = '• Brygid, Gold Street, Bastok Markets.\n• Brygid the Stylist complete.' }, { title = 'Reward', note = '• Bastok fame +10, title Bastok\'s Second Best Dressed.' } } },
    { name = 'Out of the Depths', group = 'Bastok', desc = 'Investigate the Goblin lair Movalpolos, newly appeared in North Gustaberg, with a visiting scholar in Port Bastok.', steps = { { title = 'Start', note = '• Ayame, Cannonry, Metalworks.\n• Needs Bastok fame 3.' }, { title = 'Steps', note = '• Trade Hoary Bomb Ash.\n• Key items: Dusty Tome, Pointed Jug, Cracked Club, Peeling Hairpin, Old Nametag.' }, { title = 'Reward', note = '• 1200 gil, Bastok fame +80, title Trash Collector.' } } },
    { name = 'A Question of Faith', group = 'Bastok', desc = 'The friar Virnage wants help looking into a holy tome recovered from Movalpolos.', steps = { { title = 'Start', note = '• Ayame, Cannonry, Metalworks.\n• Needs Bastok fame 4 and Out of the Depths complete.' }, { title = 'Steps', note = '• Defeat Bugallug; you get the Dawn Talisman key item.' }, { title = 'Reward', note = '• 3000 gil, Bastok fame +40.' } } },
    { name = 'Return to the Depths', group = 'Bastok', desc = 'Find someone who speaks both common and Moblin tongues to learn about Movalpolos.', steps = { { title = 'Start', note = '• Ayame, Cannonry, Metalworks.\n• Needs Bastok fame 5 and A Question of Faith complete.' }, { title = 'Steps', note = '• Trade Ahriman Tears and Misareaux Garlic.\n• Key items: Letter from Muckvix, Pungent Providence Pot, Providence Pot, Letter from Magriffon.\n• Win the Return to the Depths battlefield.' }, { title = 'Reward', note = '• Bowyer Ring, 10000 gil, Bastok fame +50, title Goblin in Disguise.' } } },
    { name = 'Teak Me to the Stars', group = 'Bastok', desc = 'Cid\'s secret airship needs more Garhada teak for its interior.', steps = { { title = 'Start', note = '• Raibaht, Cid\'s Lab, Metalworks.\n• Bastok fame 3 and mission The Call of the Wyrmking complete.' }, { title = 'Trade', note = '• Gar. Teak Lumber.' }, { title = 'Reward', note = '• 2100 gil, Bastok fame +30.' } } },
    { name = 'Chips', group = 'Bastok', desc = 'Cid collects rare coloured chips from Pso\'Xja; bring one carmine, one gray and one cyan.', steps = { { title = 'Start', note = '• Cid, Cid\'s Lab, Metalworks.\n• Mission One to Be Feared complete.' }, { title = 'Trade', note = '• Carmine Chip, Cyan Chip, Gray Chip.' }, { title = 'Reward', note = '• CCB Polymer.' } } },
    { name = 'Lure of the Wildcat (Bastok)', group = 'Bastok', desc = 'Help Salaheem\'s Sentinels recruit new members.', steps = { { title = 'Start', note = '• Alib-Mufalib, Beligen Square, Port Bastok; you get the Blue Sentinel Badge.' }, { title = 'Reward', note = '• Key item 754, Bastok fame +30.' } } },
    { name = 'Achieving True Power', group = 'Bastok', desc = 'Obtain a puppetmaster\'s testimony and give it to Shamarhaan to grow stronger.', steps = { { title = 'Start', note = '• Shamarhaan, Firewater Circle, Bastok Markets.\n• PUP level 66+, Puppetmaster Blues complete.' }, { title = 'Steps', note = '• Win the Achieving True Power battlefield.' }, { title = 'Reward', note = '• Title: Master of Manipulation.' } } },
    { name = 'Too Many Chefs', group = 'Bastok', desc = 'The eatery\'s new apprentice cook keeps getting blamed for every mishap. Not fully scripted on this server (impl=npc): NPCs exist but the quest may not complete.', steps = { { title = 'Start', note = '• Ferghus, Craftsmen\'s Eatery, Metalworks.' } } },
    { name = 'Trust: Bastok', group = 'Bastok', desc = 'Clarion Star introduces the Trust initiative and sends you to Naji in Metalworks.', steps = { { title = 'Start', note = '• Clarion Star, Beligen Square, Port Bastok.\n• Level 5+; you get the Blue Institute Card.' }, { title = 'Steps', note = '• Speak with Naji (Metalworks).' }, { title = 'Reward', note = '• Key item 2499.' } } },
    { name = 'Hat in Hand', group = 'Windurst', desc = 'Promote Baren-Moren\'s new hat by talking to Windurst Waters residents; pay depends on how many you reach, and you must not leave Windurst Waters first. Not fully scripted on this server (impl=npc): NPCs exist but the quest may not complete.', steps = { { title = 'Start', note = '• Baren-Moren, Hat Shop, Windurst Waters.' } } },
    { name = 'A Feather in One\'s Cap', group = 'Windurst', desc = 'Gather giant bird feathers for a luxury hat Baren-Moren is making for a client. Not fully scripted on this server (impl=npc): NPCs exist but the quest may not complete.', steps = { { title = 'Start', note = '• Baren-Moren, Hat Shop, Windurst Waters.' } } },
    { name = 'A Crisis in the Making', group = 'Windurst', desc = 'Ranpi-Monpi spiked the Giddeus food offering with a liquid Yagudo hate; retrieve it from the Giddeus altar before they notice. Not fully scripted on this server (impl=npc): NPCs exist but the quest may not complete.', steps = { { title = 'Start', note = '• Ranpi-Monpi, Culinarians\' Guild, Windurst Waters.' } } },
    { name = 'Making Amends', group = 'Windurst', desc = 'Hakkuru-Rinkuru broke Minister Ajido-Marujido\'s wand and needs animal glue to patch it for now.', steps = { { title = 'Start', note = '• Hakkuru-Rinkuru, Orastery, Port Windurst.\n• Needs Windurst fame 2.' }, { title = 'Trade', note = '• Animal Glue.' }, { title = 'Reward', note = '• Windurst fame +30, title Quick Fixer.' } } },
    { name = 'Making the Grade', group = 'Windurst', desc = 'Recover the stolen exam answer sheets for the School of Magic. Starts with Fuepepe (Aurastery, Windurst Waters).', steps = { { title = 'Start', note = '• Speak with Fuepepe (Aurastery, Windurst Waters).' }, { title = 'Requirements', note = '• Level 10+.\n• Windurst fame 3.\n• Finish Teacher\'s Pet first.' }, { title = 'Items to trade', note = '• Test Answers' }, { title = 'Key items you get', note = '• Tattered Test Sheet' }, { title = 'NPCs involved', note = '• Fuepepe (Windurst Waters)\n• Koru-Moru (Windurst Walls)\n• Chomoro-Kyotoro (Windurst Waters)' }, { title = 'Reward', note = '• Aspir\n• Windurst fame +30' } } },
    { name = 'In a Pickle', group = 'Windurst', desc = 'Chamama (Rarab Tail Hostelry, Windurst Waters) needs a new weighting stone of the right size, shape and weight for her Rarab Tail Pickles. Partly scripted here (impl=npc): NPCs exist, but the quest may not finish.', steps = { { title = 'Start', note = '• Speak with Chamama (Rarab Tail Hostelry, Windurst Waters).' } } },
    { name = 'Wondering Minstrel', group = 'Windurst', desc = 'Help tavern flutist Jatan-Paratan recover his playing after a visiting Hume bard. Starts with Jatan-Paratan (Timbre Timbers, Windurst Waters).', steps = { { title = 'Start', note = '• Speak with Jatan-Paratan (Timbre Timbers, Windurst Waters).' }, { title = 'Requirements', note = '• Windurst fame 5.' }, { title = 'Items to trade', note = '• Rosewood Lbr.' }, { title = 'NPCs involved', note = '• Jatan-Paratan, Yuli Yaam, Yung Yaam, Aramu-Paramu (Windurst Waters)\n• Ruslan (Lower Jeuno)' }, { title = 'Reward', note = '• Faerie Piccolo\n• Windurst fame +50\n• Title: Down Piper Pipe-upperer' } } },
    { name = 'A Pose by Any Other Name', group = 'Windurst', desc = 'Model for Angelica\'s painting by returning in the outfit she currently wants. Starts with Angelica (Hostelry Room, Windurst Waters).', steps = { { title = 'Start', note = '• Speak with Angelica (Hostelry Room, Windurst Waters).' }, { title = 'Reward', note = '• Ancient Blood\n• Key item: key item 116\n• Windurst fame +20\n• Title: Super Model' } } },
    { name = 'Making Amens!', group = 'Windurst', desc = 'Retrieve Ajido-Marujido\'s original wand from the furnace in Garlaige Citadel after Hakkuru-Rinkuru swapped it. Starts with Kuroido-Moido (Orastery, Port Windurst). Partly scripted here (impl=npc): NPCs exist, but the quest may not finish.', steps = { { title = 'Start', note = '• Speak with Kuroido-Moido (Orastery, Port Windurst).' } } },
    { name = 'The Moonlit Path', group = 'Windurst', desc = 'Collect Carbuncle\'s six whispers, then go to the Full Moon Fountain. Starts with Leepe-Hoppe (Rhinostery, Windurst Waters).', steps = { { title = 'Start', note = '• Speak with Leepe-Hoppe (Rhinostery, Windurst Waters).' }, { title = 'Requirements', note = '• Windurst fame 6.' }, { title = 'Key items you get', note = '• Fenrir Whistle\n• Dark Mana Orb\n• Whisper of the Moon\n• Moon Bauble' }, { title = 'Fights', note = '• Battlefield: Moonlit Path' }, { title = 'Reward', note = '• 15000 gil\n• Windurst fame +60\n• Title: Heir of the New Moon' } } },
    { name = 'Star Struck', group = 'Windurst', desc = 'Bring Koru-Moru a rough black stone. Starts with Koru-Moru (Manor, Windurst Walls).', steps = { { title = 'Start', note = '• Speak with Koru-Moru (Manor, Windurst Walls).' }, { title = 'Items to trade', note = '• Torn Epistle\n• Meteorite' }, { title = 'Reward', note = '• Cmp. Eye Circlet\n• 50 gil\n• Windurst fame +20' } } },
    { name = 'Blast from the Past', group = 'Windurst', desc = 'Bring Koru-Moru a Burnite Shell. Starts with Koru-Moru (Manor, Windurst Walls).', steps = { { title = 'Start', note = '• Speak with Koru-Moru (Manor, Windurst Walls).' }, { title = 'Requirements', note = '• Windurst fame 3.\n• Finish Star Struck first.' }, { title = 'Items to trade', note = '• Burnite Shell' }, { title = 'Reward', note = '• Great Club\n• Windurst fame +30\n• Title: Fossilized Sea Farer' } } },
