    { name = 'The Fanged One', group = 'Windurst', desc = 'Ranger unlock: obtain the Old Tiger\'s Fang in Sauromugue Champaign for Perih Vashai (Vashai\'s residence, Windurst Woods). Level 30, any job.', steps = { { title = 'Step 1', note = '• Speak with Perih Vashai (Vashai\'s residence, Windurst Woods).' }, { title = 'Step 2', note = '• In Sauromugue Champaign, examine the Tiger Bones to spawn Old Sabertooth.' }, { title = 'Step 3', note = '• Do not attack it; it roams and dies by itself after a few minutes. Stay within about 30 yalms when it dies.' }, { title = 'Step 4', note = '• Examine the Tiger Bones again within 3 minutes of its death to get the Old Tiger\'s Fang.' }, { title = 'Step 5', note = '• Return the fang to Perih Vashai to unlock Ranger.' }, { title = 'Tips', note = '• If anyone damages Old Sabertooth it fights back, the kill doesn\'t count, and the bones need about 5 minutes before it can be called again.\n• Missed the 3-minute window: examine the bones again and repeat.\n• Trading a Blk. Tiger Fang to Perih does nothing for this quest.\n• Kapeh Myohrye and Muhk Johldy beside Perih have extra dialogue during the quest.' }, { title = 'Reward', note = '• Ranger job\n• Ranger\'s Necklace\n• Windurst fame +20\n• Title: The Fanged One' } } },
