    { name = 'As Thick as Thieves', group = 'Windurst', desc = 'Use the gang whereabouts note to find Atarefaunet\'s last two thieves and get each to sign a counterfeit envelope. Starts with Nanaa Mihgo (Cat Burglar\'s lair, Windurst Woods).', steps = { { title = 'Start', note = '• Speak with Nanaa Mihgo (Cat Burglar\'s lair, Windurst Woods).' }, { title = 'Requirements', note = '• Level 50+.\n• Job: THF.\n• Finish The Tenshodo Showdown first.' }, { title = 'Items to trade', note = '• Grapnel\n• Rock Salt\n• Gausebit Grass\n• Lizard Egg\n• Regal Die' }, { title = 'Key items needed', note = '• First Forged Envelope\n• Second Forged Envelope\n• Gang Whereabouts Note' }, { title = 'Key items you get', note = '• First Signed Forged Envelope\n• Second Signed Forged Envelope' }, { title = 'Fights', note = '• Climbpix Highrise\n• Gambilox Wanderling' }, { title = 'NPCs involved', note = '• Nanaa Mihgo (Windurst Woods)\n• ??? (Tower) ×6 (Sauromugue Champaign)\n• Sniggnix (Lower Jeuno)\n• ??? (Saltvix), ??? (Grasswix), ??? (Eggblix) (Dangruf Wadi)\n• ??? (North Gustaberg)' }, { title = 'Reward', note = '• Rogue\'s Bonnet\n• Windurst fame +20' } } },
    { name = 'Hitting the Marquisate', group = 'Windurst', desc = 'Visit two of the eight Tenshodo-recruited thieves and verify the original signatures from the letter from the Tenshodo. Starts with Nanaa Mihgo (Cat Burglar\'s lair, Windurst Woods).', steps = { { title = 'Start', note = '• Speak with Nanaa Mihgo (Cat Burglar\'s lair, Windurst Woods).' }, { title = 'Requirements', note = '• Level 50+.\n• Job: THF.\n• Finish As Thick as Thieves first.' }, { title = 'Items to trade', note = '• Pickaxe\n• 4 × Quake Grenade\n• Chandelier Coal' }, { title = 'Key items you get', note = '• Cat Burglars Note\n• Bomb Incense' }, { title = 'Fights', note = '• Chandelier' }, { title = 'NPCs involved', note = '• Nanaa Mihgo (Windurst Woods)\n• Yatniel (Lower Jeuno)\n• Hagain (Mhaura)\n• ??? ×7 (Garlaige Citadel)\n• ??? (La Theine) (La Theine Plateau)' }, { title = 'Reward', note = '• Rogue\'s Poulaines\n• Title: Paragon of Thief Excellence' } } },
    { name = 'Sin Hunting', group = 'Windurst', desc = 'Find Semih Lafihna at Ranguemont Pass and give her a twinstone earring. Starts with Perih Vashai (Vashai\'s residence, Windurst Woods).', steps = { { title = 'Start', note = '• Speak with Perih Vashai (Vashai\'s residence, Windurst Woods).' }, { title = 'Requirements', note = '• Level 40+.\n• Job: RNG.' }, { title = 'Items to trade', note = '• Glittersand' }, { title = 'Key items you get', note = '• Chieftainnesss Twinstone Earring\n• Perchonds Envelope' }, { title = 'NPCs involved', note = '• Perih Vashai (Windurst Woods)\n• Perchond (Ranguemont Pass)\n• Alexius (Jugner Forest)\n• ??? (Jugner Forest)' }, { title = 'Reward', note = '• Sniping Bow\n• Windurst fame +20' } } },
    { name = 'Fire and Brimstone', group = 'Windurst', desc = 'Meet Koh Lenbalalako in Mhaura, who knows where the sinner\'s daughter is. Starts with Perih Vashai (Vashai\'s residence, Windurst Woods). Partly scripted here (impl=npc): NPCs exist, but the quest may not finish.', steps = { { title = 'Start', note = '• Speak with Perih Vashai (Vashai\'s residence, Windurst Woods).' } } },
    { name = 'Unbridled Passion', group = 'Windurst', desc = 'Track down Semih Lafihna and assist her search for the truth. Starts with Perih Vashai (Vashai\'s residence, Windurst Woods). Partly scripted here (impl=npc): NPCs exist, but the quest may not finish.', steps = { { title = 'Start', note = '• Speak with Perih Vashai (Vashai\'s residence, Windurst Woods).' } } },
    { name = 'I Can Hear a Rainbow', group = 'Windurst', desc = 'Summoner unlock: collect seven colors of light from field weather with a Carbuncle\'s Ruby, starting at ??? (House of the Hero, Windurst Walls). Level 30, any job; the ruby must be in inventory to start.', steps = { { title = 'Step 1', note = '• Obtain a Carbuncle\'s Ruby (leech drop; Thread Leeches in Valkurm Dunes, Poison Leeches in Buburimu Peninsula and Rolanberry Fields).' }, { title = 'Step 2', note = '• With the ruby in main inventory, click the House of the Hero door in Windurst Walls to start.' }, { title = 'Step 3', note = '• Zone into a listed outdoor area during each needed weather; a cutscene marks each color collected.' }, { title = 'Weather and where', note = '• Clear (none/sunshine): West or East Sarutabaruta.\n• Fire (hot spell/heat wave, rare): Eastern or Western Altepa Desert; sometimes Yuhtunga, Yhoator, Cape Teriggan.\n• Water (rain/squall): Pashhow Marshlands; also La Theine, Rolanberry, both jungles.\n• Earth (dust/sand storm): Batallia Downs, Altepa deserts; sometimes Valkurm, Tahrongi, Konschtat.\n• Wind (wind/gales): Buburimu, Tahrongi, La Theine; sometimes Cape Teriggan.\n• Ice (snow/blizzard): Beaucedine Glacier, Xarcabard.\n• Thunder: Zi\'Tah, Konschtat, Jugner; sometimes Pashhow.' }, { title = 'Step 4', note = '• With all seven, trade the ruby to the ??? on La Theine Plateau to unlock Summoner and Carbuncle.' }, { title = 'Tips', note = '• Ruby in satchel or Mog House doesn\'t count.\n• Weather is checked only on zone-in; re-zone if it changes.\n• Clouds, fog, light/dark weather don\'t count; fog is common around 2:00–7:00 game time.\n• Valid zones: West/East Ronfaure, North/South Gustaberg, West/East Sarutabaruta, La Theine, Konschtat, Tahrongi, Valkurm, Buburimu, Jugner, Batallia, Pashhow, Rolanberry, Meriphataud, Sauromugue, Beaucedine, Xarcabard, Yuhtunga, Yhoator, Zi\'Tah, both Altepa deserts, Cape Teriggan.\n• Ruby is Rare (one held) and is consumed at the end.' }, { title = 'Reward', note = '• Summoner job, Carbuncle\n• Key item: key item 1752\n• Windurst fame +20\n• Title: Rainbow Weaver' } } },
    { name = 'Crying Over Onions', group = 'Windurst', desc = 'Honoi-Gomoi demands the Mana Orb back; help the Star Onion Brigade avoid being branded thieves. Starts with Kohlo-Lakolo (Warehouses, Port Windurst).', steps = { { title = 'Start', note = '• Speak with Kohlo-Lakolo (Warehouses, Port Windurst).' }, { title = 'Requirements', note = '• Level 5+.\n• Windurst fame 5.\n• Finish Onion Rings first.' }, { title = 'Items to trade', note = '• Star Spinel' }, { title = 'Reward', note = '• Windurst fame +50' } } },
