    { name = 'Path of the Beastmaster', group = 'Jeuno', desc = 'Beastmaster unlock: heal Brutus\' chocobo, help Dietmund\'s sick son, then report back to Brutus.', steps = { { title = 'Requirements', note = '• Level 30; any job; first finish Chocobo\'s Wounds (level 20) then Save My Son.' }, { title = 'Steps', note = '• Talk to Brutus (Chocobo Stables, Upper Jeuno) and accept; if you decline, talk again.\n• Trade Gausebit Grass to the injured Chocobo (-61, 93) once per Vana\'diel day; the sixth feeding completes it and gives a chocobo license.\n• At level 30, click the Merchant\'s House door in Lower Jeuno and agree to find the night flower.\n• On Qufim Island, examine the Nightflowers between 21:30 and 5:40 game time.\n• Return to the Merchant\'s House door; you receive a Beast Whistle plus 2,100 gil.\n• Report to Brutus to unlock Beastmaster.' }, { title = 'Tips', note = '• One feeding per game day (resets at midnight); it eats four clumps across six feedings; carry four or more and hand over one per trade.\n• Gausebit Grass only, not Gysahl Greens.\n• Nightflowers do nothing in daytime.\n• Gausebit Grass drops from Crane Flies (Meriphataud Mountains) and Wadi Hares (Dangruf Wadi).' }, { title = 'Reward', note = '• Key item: key item 1746\n• Title: Animal Trainer' } } },
    { name = 'Path of the Bard', group = 'Jeuno', desc = 'Bard unlock: copy lyrics from the Buburimu monument for Mertaire, then visit the Valkurm Dunes monument.', steps = { { title = 'Requirements', note = '• Level 30; any job; preceded by The Old Monument and A Minstrel in Despair.' }, { title = 'Steps', note = '• Talk to Mertaire (Merry Minstrel Meadhouse, Lower Jeuno).\n• Examine the Song Runes in Buburimu Peninsula.\n• Trade them a Parchment; you receive a Poetic Parchment.\n• Hand that Poetic Parchment to Mertaire for 2,100 gil.\n• Examine the Song Runes in Valkurm Dunes to unlock Bard (+3,000 gil).' }, { title = 'Tips', note = '• Trading before examining the Buburimu runes does nothing.\n• Bki Tbujhja and Mataligeat are optional.\n• Lost the Poetic Parchment? Trade another Parchment to the Buburimu runes.\n• Parchment is crafted; Kueh Igunahmori (Southern San d\'Oria) sells it during guild hours.' }, { title = 'Reward', note = '• 3000 gil\n• Key item: key item 1747\n• Title: Wandering Minstrel' } } },
