    { name = 'For the Birds', group = 'Other Areas', desc = 'Zeelozok asks for an arnica root delivered to Castle Oztroja; Koblakiq sends you. Starts with Koblakiq (Oldton Movalpolos).', steps = { { title = 'Start', note = '• NPC: Koblakiq, Oldton Movalpolos.\n• Prior quest: Missionary Moblin.' }, { title = 'Trade', note = '• Arnica Root.\n• Key item: Glittering Fragment.' }, { title = 'Fights', note = '• Magnes Quadav NM, Nickel Quadav NM.' }, { title = 'Reward', note = '• Jaguar Mantle.' } } },
    { name = 'Better the Demon You Know', group = 'Other Areas', desc = 'With Zeelozok off to fight the Kindred, Koblakiq wants a Demon pen to study demons. Starts with Koblakiq (Oldton Movalpolos).', steps = { { title = 'Start', note = '• NPC: Koblakiq, Oldton Movalpolos.\n• Prior quest: For the Birds.\n• Key item needed: Zeelozoks Earplug.' }, { title = 'Fight', note = '• Marquis Andrealphus.' }, { title = 'Trade', note = '• Demon Pen.' }, { title = 'Reward', note = '• Goblin Grenade.\n• Title: Apostate for Hire.' } } },
    { name = 'A Question of Taste', group = 'Outlands', desc = 'Begins with a letter from the Windurstian painter Angelica to Kazham\'s chieftainess. Starts with Jakoh Wahcondalo (Wahcondalo\'s Residence, Kazham).', steps = { { title = 'Start', note = '• NPC: Jakoh Wahcondalo, Wahcondalo\'s Residence, Kazham.\n• Windurst fame 6.' }, { title = 'Key items', note = '• Letter to Angelica, Ripped Final Fantasy Painting, Final Fantasy, Angelicas Letter, Final Fantasy Part Ii.' }, { title = 'Fight', note = '• Trompe LOeil.' }, { title = 'Reward', note = '• 3000 gil.' } } },
    { name = 'Everyone\'s Grudging', group = 'Outlands', desc = 'Cursed by Tonberry rancor flames, you are expelled from Kazham by the chieftainess. Starts with Jakoh Wahcondalo (Wahcondalo\'s Residence, Kazham).', steps = { { title = 'Start', note = '• NPC: Jakoh Wahcondalo, Wahcondalo\'s Residence, Kazham.\n• Windurst fame 7; prior quest: A Question of Taste.' }, { title = 'Fight', note = '• Rancor Torch.' }, { title = 'Reward', note = '• 11000 gil, Windurst fame +60.' } } },
    { name = 'You Call That a Knife?', group = 'Outlands', desc = 'Mhebi will release her Tonberry once his rusty knife is dealt with. Starts with Mhebi Juhbily (Near Mihgo\'s Residence, Kazham).', steps = { { title = 'Start', note = '• NPC: Mhebi Juhbily, near Mihgo\'s Residence, Kazham.\n• Windurst fame 6.\n• Other NPCs: Vah Keshura, Pula Rhatti (Kazham); Chef Nonberry (Temple of Uggalepih).' }, { title = 'Trade', note = '• Sandfish, Tonberry Board.\n• Key item: Nonberrys Knife.' }, { title = 'Reward', note = '• 7200 gil, Windurst fame +60.\n• Title: Ya Done Good.' } } },
    { name = 'Missionary Man', group = 'Outlands', desc = 'Step one: get a slab of Elshimo marble from Yuhtunga Jungle for the young missionary. Starts with Rauteinot (Near the village gate, Kazham). NPCs exist on this server but the quest is only partly scripted and may not finish.', steps = { { title = 'Start', note = '• NPC: Rauteinot, near the village gate, Kazham.' } } },
    { name = 'Gullible\'s Travels', group = 'Outlands', desc = 'Magriffon spent everything feeding Opo-opos and now needs help staying at the bed & breakfast to finish his secret mission. Starts with Magriffon (Celodehki\'s Bed & Breakfast, Kazham). NPCs exist on this server but the quest is only partly scripted and may not finish.', steps = { { title = 'Start', note = '• NPC: Magriffon, Celodehki\'s Bed & Breakfast, Kazham.' } } },
    { name = 'Even More Gullible\'s Travels', group = 'Outlands', desc = 'Magriffon is broke again after helping a maiden and once more risks eviction from the bed & breakfast. Starts with Magriffon (Celodehki\'s Bed & Breakfast, Kazham). NPCs exist on this server but the quest is only partly scripted and may not finish.', steps = { { title = 'Start', note = '• NPC: Magriffon, Celodehki\'s Bed & Breakfast, Kazham.' } } },
    { name = 'Personal Hygiene', group = 'Outlands', desc = 'Blue Rafflesia pollen left you smelling foul; soak in an undersea hot spring to clean off. Starts with Gatih Mijurabi (M & P\'s Market, Kazham). NPCs exist on this server but the quest is only partly scripted and may not finish.', steps = { { title = 'Start', note = '• NPC: Gatih Mijurabi, M & P\'s Market, Kazham.' } } },
    { name = 'The Opo-opo and I', group = 'Outlands', desc = 'Kazham\'s Opo-opos like your new scent; give them what they want in the right order to become their king. Starts with Vuih Stecoppah (Docks, Kazham). NPCs exist on this server but the quest is only partly scripted and may not finish.', steps = { { title = 'Start', note = '• NPC: Vuih Stecoppah, Docks, Kazham.' } } },
    { name = 'Trial by Fire', group = 'Outlands', desc = 'Strike the fire tuning fork on the protocrystal in Ifrit\'s Cauldron to reach the trial. Starts with Ronta-Onta (Near Wahcondalo\'s Residence, Kazham).', steps = { { title = 'Start', note = '• NPC: Ronta-Onta, near Wahcondalo\'s Residence, Kazham.\n• Windurst fame 6.\n• Other NPC: Dodmos (Kazham).' }, { title = 'Key items', note = '• Tuning Fork of Fire, Whisper of Flames.' }, { title = 'Fight', note = '• Battlefield: Trial By Fire.' }, { title = 'Reward', note = '• 10000 gil, Windurst fame +60.' } } },
    { name = 'Cloak and Dagger', group = 'Outlands', desc = 'The chieftainess wants help countering her new dagger move, after you finish your training. Starts with Jakoh Wahcondalo (Wahcondalo\'s Residence, Kazham).', steps = { { title = 'Start', note = '• NPC: Jakoh Wahcondalo, Wahcondalo\'s Residence, Kazham.' }, { title = 'Key items', note = '• Received: Weapon Training Guide, Map to the Annals of Truth.\n• Needed: Annals of Truth.' }, { title = 'Fight', note = '• Baronial Bat.' }, { title = 'Trade', note = '• Dagger of Trials.' }, { title = 'Reward', note = '• Windurst fame +20.' } } },
    { name = 'Trial-Size Trial by Fire', group = 'Outlands', desc = 'Summoner-only: ring the Rhinostery\'s mini fire tuning fork at the Ifrit\'s Cauldron protocrystal for a solo avatar fight. Starts with Dodmos (Near Wahcondalo\'s Residence, Kazham). NPCs exist on this server but the quest is only partly scripted and may not finish.', steps = { { title = 'Start', note = '• NPC: Dodmos, near Wahcondalo\'s Residence, Kazham.' } } },
    { name = 'Forge Your Destiny', group = 'Outlands', desc = 'Jaucribaix needs bomb steel and a sacred branch for a new katana; his pupils explain how to get them, and the blade unlocks Samurai. Starts with Jaucribaix (Near the Captain\'s Quarters, Norg).', steps = { { title = 'Overview', note = '• Level 30 on any job.\n• Overview says both monsters are level 20; Tips say level 32 on this server.' }, { title = 'Step 1', note = 'Talk to Jaucribaix in Norg and accept; he asks for Bomb Steel and a Sacred Branch.' }, { title = 'Step 2', note = 'Talk to Aeka to get an Oriental Steel.' }, { title = 'Step 3', note = 'Talk to Ranemaud to get a Sacred Sprig.' }, { title = 'Step 4', note = 'Buy a Hatchet at a general goods shop (e.g. Kahah Hobichai, Al Zahbi).' }, { title = 'Step 5', note = 'In Konschtat Highlands, stand on the blackened ??? at map position -709, 102 and trade it the Oriental Steel.' }, { title = 'Step 6', note = 'Defeat the bomb Forger to get Bomb Steel.' }, { title = 'Step 7', note = 'In The Sanctuary of Zi\'Tah, trade the Hatchet to the sturdy-branch ??? at map position 642, -150 while carrying the Sacred Sprig.' }, { title = 'Step 8', note = 'Defeat Guardian Treant.' }, { title = 'Step 9', note = 'Trade the Sacred Sprig to the same ??? to get a Sacred Branch.' }, { title = 'Step 10', note = 'In Norg, trade Bomb Steel and Sacred Branch to Jaucribaix in one trade.' }, { title = 'Step 11', note = 'Wait three Vana\'diel days (just under 3 hours), then talk to Jaucribaix to get the Mumeito and unlock Samurai.' }, { title = 'Tips', note = '• Bring help if well under level 32.\n• If a ??? won\'t react, its monster is up or was just killed; retry later.\n• Replace Oriental Steel: trade Aeka a Darksteel Ore.\n• Replace Sacred Sprig: trade Ranemaud 2 Gold Ore + 1 Platinum Ore.' }, { title = 'Reward', note = '• Mumeito, key item 1749, Norg fame +20.\n• Title: Bushido Blade.' } } },
    { name = 'Stop Your Whining', group = 'Outlands', desc = 'Fill an empty barrel with Opo-opo brew fermenting in Yhoator Jungle trees and hurry it back to Norg. Starts with Washu (Buccaneer\'s Quarters, Norg).', steps = { { title = 'Start', note = '• NPC: Washu, Buccaneer\'s Quarters, Norg.\n• Level 10+; Norg fame 4.\n• Key item: Empty Barrel.' }, { title = 'Yhoator Jungle', note = '• Use the ??? to get key item Barrel of Opo Opo Brew, then return to Washu.' }, { title = 'Reward', note = '• Hojo: Ichi, Norg fame +40.\n• Title: Apprentice Sommelier.' } } },
    { name = 'Everyone\'s Grudge', group = 'Outlands', desc = 'Bring three gold beastcoins to learn how to lift the Tonberry rancor. Starts with Magephaud (Next to the central staircase, Norg). NPCs exist on this server but the quest is only partly scripted and may not finish.', steps = { { title = 'Start', note = '• NPC: Magephaud, by the central staircase, Norg.' } } },
    { name = 'Secret of the Damp Scroll', group = 'Outlands', desc = 'Soak your damp scroll in the Horlais Peak hot springs so it becomes readable. Starts with Shivivi (Near the Captain\'s Quarters, Norg).', steps = { { title = 'Start', note = '• NPC: Shivivi, near the Captain\'s Quarters, Norg.\n• Level 10+; Norg fame 3.' }, { title = 'Trade', note = '• Damp Scroll to the Hot Springs in Horlais Peak.' }, { title = 'Reward', note = '• Jubaku: Ichi, Norg fame +30.\n• Title: Cracker of the Secret Code.' } } },
    { name = 'The Sahagin\'s Stash', group = 'Outlands', desc = 'Take any item from the Sahagin storeroom in Sea Serpent Grotto. Starts with Laisrean (Storage area, Norg).', steps = { { title = 'Start', note = '• NPC: Laisrean, storage area, Norg.\n• Level 5+; Norg fame 4.' }, { title = 'Sea Serpent Grotto', note = '• Check the ??? for key item Sea Serpent Statue.' }, { title = 'Reward', note = '• Utsusemi: Ichi, Norg fame +40.\n• Title: Treasure-house Ransacker.' } } },
    { name = 'It\'s Not Your Vault', group = 'Outlands', desc = 'Retrieve a sealed iron box from the Sahagin-held Norg vault. Starts with Keal (Quay, Norg). NPCs exist on this server but the quest is only partly scripted and may not finish.', steps = { { title = 'Start', note = '• NPC: Keal, Quay, Norg.' } } },
    { name = 'Like a Shining Subligar', group = 'Outlands', desc = 'Turn in ten rusty subligars, one per trade, for ninja trainees. Starts with Heiji (2nd floor, Norg).', steps = { { title = 'Start', note = '• NPC: Heiji, 2nd floor, Norg.\n• Norg fame 3.' }, { title = 'Reward', note = '• Kurayami: Ichi, Norg fame +30.\n• Title: Looks Sublime in a Subligar.' } } },
    { name = 'Like Shining Leggings', group = 'Outlands', desc = 'Turn in ten pairs of rusty leggings, one per trade, for ninja trainees. Starts with Heizo (2nd floor, Norg).', steps = { { title = 'Start', note = '• NPC: Heizo, 2nd floor, Norg.\n• Norg fame 3.' }, { title = 'Reward', note = '• Dokumori: Ichi, Norg fame +30.\n• Title: Looks Good in Leggings.' } } },
    { name = 'The Sacred Katana', group = 'Outlands', desc = 'Forge a ritual katana in Norg from your mumeito and crystal scales. Starts with Jaucribaix (Near the Captain\'s Quarters, Norg).', steps = { { title = 'Start', note = '• NPC: Jaucribaix, near the Captain\'s Quarters, Norg.\n• Level 40+, SAM; prior quest: Forge Your Destiny.\n• Other NPCs: Ranemaud (Norg); ??? in The Sanctuary of Zi\'Tah.' }, { title = 'Trade', note = '• Sack of Fish Bait, Mumeito, 30000 gil.' }, { title = 'Fight', note = '• Isonade.\n• Key item: Handful of Crystal Scales.' }, { title = 'Reward', note = '• Magoroku, Norg fame +20.' } } },
    { name = 'Yomi Okuri', group = 'Outlands', desc = 'Help hold a ritual to lay to rest souls lost when a small nation fell in war twenty years ago. Starts with Gilgamesh (Captain\'s Quarters, Norg).', steps = { { title = 'Start', note = '• NPC: Gilgamesh, Captain\'s Quarters, Norg.\n• Level 50+, SAM; prior quest: The Sacred Katana.\n• Other NPCs: Jaucribaix, Washu (Norg); ??? in Labyrinth of Onzozo and Valkurm Dunes.' }, { title = 'Trade', note = '• Hecteyes Eye, Bastore Sardine, G. Sheep Meat, Frost Turnip.' }, { title = 'Key items', note = '• Yomotsu Feather, Washus Tasty Wurst, Yomotsu Hirasaka, Faded Yomotsu Hirasaka.' }, { title = 'Fights', note = '• Ubume, Doman, Onryo.' }, { title = 'Reward', note = '• Myochin Sune-Ate, Norg fame +20.' } } },
    { name = 'A Thief in Norg!?', group = 'Outlands', desc = 'The helm holding a spirit sealed by Gilgamesh\'s father was stolen; track the thief down. Starts with Gilgamesh (Captain\'s Quarters, Norg).', steps = { { title = 'Start', note = '• NPC: Gilgamesh, Captain\'s Quarters, Norg.\n• Level 50+, SAM; prior quest: Yomi Okuri.\n• Other NPCs: Jaucribaix (Norg), Sanosuke (Port Jeuno), Phoochuchu (Mhaura), Door (Bastok Mines).' }, { title = 'Trade', note = '• Gold Thread.' }, { title = 'Fight', note = '• Battlefield: Thief in Norg.\n• Key item: Charred Helm.' }, { title = 'Reward', note = '• Myochin Kabuto, Norg fame +20.\n• Title: Paragon of Samurai Excellence.' } } },
    { name = '20 in Pirate Years', group = 'Outlands', desc = 'Norg is studying a recently recovered ancient scroll; ask Tenshodo member Kagetora in Bastok. Starts with Ryoma (Quay, Norg). NPCs exist on this server but the quest is only partly scripted and may not finish.', steps = { { title = 'Start', note = '• NPC: Ryoma, Quay, Norg.' } } },
    { name = 'I\'ll Take the Big Box', group = 'Outlands', desc = 'The trick box you returned was a fake; locate the real one, beginning with Ensetsu in Bastok. Starts with Ryoma (Quay, Norg).', steps = { { title = 'Start', note = '• NPC: Ryoma, Quay, Norg.\n• Prior quest: 20 in Pirate Years.\n• Other NPCs: Ensetsu (Port Bastok), Leodarion (Rabao).' }, { title = 'Trade', note = '• Oak Pole.\n• Key item: Seance Staff.' }, { title = 'Fight', note = '• Enagakure.' }, { title = 'Reward', note = '• Ninja Hakama, Norg fame +20.' } } },
    { name = 'True Will', group = 'Outlands', desc = 'Recover Mitsunari\'s treasure, which the Sahagin hid in the Elshimo jungle; start with Ryoma on the Quay in Norg. Only NPC-scripted on this server, so it may not complete.', steps = { { title = 'Start', note = '• Talk to Ryoma (Quay, Norg).' } } },
    { name = 'The Potential Within', group = 'Outlands', desc = 'Jaucribaix in Norg hands you a trial katana; use it until its power is spent to prove yourself.', steps = { { title = 'Start', note = '• Talk to Jaucribaix (Near the Captain\'s Quarters, Norg).' }, { title = 'Items to trade', note = '• Tachi of Trials' }, { title = 'Key items', note = '• Needed: Annals of Truth\n• Received: Weapon Training Guide, Map to the Annals of Truth' }, { title = 'Fights', note = '• Kettenkaefer' }, { title = 'Reward', note = '• Norg fame +20' } } },
    { name = 'Bugi Soden', group = 'Outlands', desc = 'Ryoma in Norg gives you a trial kodachi; drain its power through use to earn the old ninja masters\' teachings.', steps = { { title = 'Start', note = '• Talk to Ryoma (Quay, Norg).' }, { title = 'Items to trade', note = '• Kodachi of Trials' }, { title = 'Key items', note = '• Needed: Annals of Truth\n• Received: Weapon Training Guide, Map to the Annals of Truth' }, { title = 'Fights', note = '• Megapod Megalops' }, { title = 'Reward', note = '• Norg fame +20' } } },
    { name = 'Trial-Size Trial by Water', group = 'Outlands', desc = 'Summoner-only solo fight: ring the Rhinostery\'s mini water fork on the Den of Rancor protocrystal. Only NPC-scripted on this server, so it may not complete.', steps = { { title = 'Start', note = '• Talk to Verctissa (Near the Quay, Norg).' } } },
    { name = 'Wrath of the Opo-opos', group = 'Outlands', desc = 'Appease the Opo-opos, angry over their missing red treasure, with a stone of matching colour.', steps = { { title = 'Do', note = '• Trade a Garnet to the Cermet Headstone in Yuhtunga Jungle.' }, { title = 'Reward', note = '• Opo-opo Necklace\n• Title: Friend of the Opo-opos' } } },
    { name = 'Wandering Souls', group = 'Outlands', desc = 'Calm the restless spirits of Cape Teriggan with a flower offering.', steps = { { title = 'Do', note = '• Trade a Rain Lily to the Cermet Headstone in Cape Teriggan.' }, { title = 'Reward', note = '• Flagellant\'s Rope\n• Title: Bearer of Bonds Beyond Time' } } },
    { name = 'Soul Searching', group = 'Outlands', desc = 'Lay to rest the souls of pilgrims who died on their journey.', steps = { { title = 'Do', note = '• With the Prismatic Fragment key item, visit the Cermet Headstone in The Sanctuary of Zi\'Tah.' }, { title = 'Reward', note = '• Bat Earring\n• Title: Guider of Souls to the Sanctuary' } } },
    { name = 'Divine Might', group = 'Outlands', desc = 'Fight all five Crystal Warriors at once in La\'Loff Amphitheater using the Ark Pentasphere; Yve\'noile in The Shrine of Ru\'Avitau starts it.', steps = { { title = 'Start', note = '• Talk to Yve\'noile (Entry Hall, The Shrine of Ru\'Avitau).' }, { title = 'Items to trade', note = '• Illuminink\n• Parchment' }, { title = 'Fight', note = '• Battlefield: Divine Might\n• Involved: Qu\'Hau Spring (Ro\'Maeve)' }, { title = 'Reward', note = '• Title: Pentacide Perpetrator' } } },
    { name = 'Divine Might', group = 'Outlands', desc = 'Repeat version: the Crystal Warriors have re-formed and must be fought again. Requires the first Divine Might.', steps = { { title = 'Start', note = '• Talk to Yve\'noile (Entry Hall, The Shrine of Ru\'Avitau).' }, { title = 'Requirements', note = '• Quest done first: Divine Might.' }, { title = 'Items to trade', note = '• Illuminink\n• Parchment\n• Light Ore' }, { title = 'Key items you get', note = '• Moonlight Ore' }, { title = 'Fight', note = '• Battlefield: Divine Might\n• Involved: Qu\'Hau Spring (Ro\'Maeve)' }, { title = 'Reward', note = '• Title: Pentacide Perpetrator' } } },
    { name = 'Open Sesame', group = 'Outlands', desc = 'Lokpix in Eastern Altepa Desert teaches you to open the Quicksand Caves door alone in exchange for a tremorstone plus a meteorite (or one soil gem, or twelve soil geodes, instead of the meteorite).', steps = { { title = 'Start', note = '• Talk to Lokpix (Eastern Altepa Desert).' }, { title = 'Bring', note = '• Tremorstone\n• Meteorite, or Soil Gem, or 12 × Soil Geode' }, { title = 'Reward', note = '• Key item: key item 2051' } } },
    { name = 'Don\'t Forget the Antidote', group = 'Outlands', desc = 'Edigey in Rabao needs sand scorpion poison to brew antidotes for desert caravans. Only NPC-scripted on this server, so it may not complete.', steps = { { title = 'Start', note = '• Talk to Edigey (Sand dune, Rabao).' } } },
    { name = 'The Missing Piece', group = 'Outlands', desc = 'Friar Alfesar in Rabao wants the rest of a stone tablet found in the Quicksand Caves under the Altepa Desert.', steps = { { title = 'Start', note = '• Talk to Alfesar (Near the oasis, Rabao).' }, { title = 'Requirements', note = '• Level 10+.\n• Selbina and Rabao fame level 4.' }, { title = 'Key items needed', note = '• Ancient Tablet Fragment\n• Tablet of Ancient Magic\n• Letter from Alfesar' }, { title = 'Reward', note = '• Teleport-Altep' } } },
    { name = 'The Kuftal Tour', group = 'Outlands', desc = 'Join Datta\'s tour: bring a party of at least two, all level 40 or under, to the cliff just inside Kuftal Tunnel and meet Hawk Nose.', steps = { { title = 'Start', note = '• Talk to Datta (Near the oasis, Rabao).' }, { title = 'Requirements', note = '• Selbina and Rabao fame level 3.\n• Quest done first: The Gustaberg Tour.' }, { title = 'Do', note = '• With the party, go to the ??? at the cliff inside the Kuftal Tunnel entrance and meet Hawk Nose.' }, { title = 'Reward', note = '• 8000 gil\n• Title: Kuftal Tourist' } } },
    { name = 'The Immortal Lu Shang', group = 'Outlands', desc = 'Irmilant will fix your broken Lu Shang\'s fishing rod if you also bring one ancient lumber and two light crystals. Only partly scripted here (impl=npc), so it may not finish.', steps = { { title = 'Start', note = '• Talk to Irmilant (Near the oasis, Rabao).' } } },
    { name = 'Trial-Size Trial by Wind', group = 'Outlands', desc = 'Summoner-only solo fight: ring the Rhinostery\'s mini wind tuning fork at the Cape Teriggan protocrystal to face the avatar alone. Only partly scripted here (impl=npc), so it may not finish.', steps = { { title = 'Start', note = '• Talk to Rahi Fohlatti (Near the oasis, Rabao).' } } },
    { name = 'Chasing Dreams', group = 'Outlands', desc = 'Zoriboh asks you to track down the cargo hauler Sanctia, who left Rabao and likely went to Norg to sail for the Tavnazian Marquisate.', steps = { { title = 'Start', note = '• Talk to Zoriboh (Near the oasis, Rabao).' }, { title = 'Items to trade', note = '• 5 × Eastern Gem' }, { title = 'Key items you get', note = '• Flask of Clam Water\n• Washus Flask\n• Storeroom Key' }, { title = 'Reward', note = '• Venerer Ring\n• 4000 gil' } } },
    { name = 'Indomitable Spirit', group = 'Outlands', desc = 'Irmilant needs the two base materials for a legendary fishing rod; both are inside hard-to-catch sea creatures. Only partly scripted here (impl=npc), so it may not finish.', steps = { { title = 'Start', note = '• Talk to Irmilant (Near the oasis, Rabao).' } } },
    { name = 'Keeping Notes', group = 'Aht Urhgan', desc = 'Bring Ahkk Jharcham parchment and black ink so she can record her secret.', steps = { { title = 'Start', note = '• Talk to Ahkk Jharcham (Port Al Zahbi, Aht Urhgan Whitegate).' }, { title = 'Items to trade', note = '• Parchment\n• Black Ink' } } },
    { name = 'Arts and Crafts', group = 'Aht Urhgan', desc = 'Collect lettered paper pieces for Hadahda: one each of M, U and T, plus two each of A and D.', steps = { { title = 'Start', note = '• Talk to Hadahda (Stoneserpent Square, Aht Urhgan Whitegate).' }, { title = 'Items to trade', note = '• Sutlac' }, { title = 'Reward', note = '• Imp. Brz. Piece' } } },
    { name = 'Olduum', group = 'Aht Urhgan', desc = 'Dkhaaya wants an Olduum relic brought to him.', steps = { { title = 'Start', note = '• Talk to Dkhaaya (Balrahn Way, Aht Urhgan Whitegate).' }, { title = 'Items to trade', note = '• Pickaxe\n• Lightning Band' }, { title = 'Key items you get', note = '• Dkhaayas Research Journal' }, { title = 'Reward', note = '• Lightning Band' } } },
    { name = 'Got It All', group = 'Aht Urhgan', desc = 'Fetch a vial of luminous water from Ekhu Pesshyadha for Tehf Kimasnahya.', steps = { { title = 'Start', note = '• Talk to Tehf Kimasnahya (Balrahn Way, Aht Urhgan Whitegate).' }, { title = 'Key items you get', note = '• Vial of Luminous Water' }, { title = 'Reward', note = '• Bibiki Seashell' } } },
    { name = 'An Empty Vessel', group = 'Aht Urhgan', desc = 'Blue Mage unlock: pass Waoud\'s ten-question reading, bring him a rare Middle Lands item, then meet Yasfel in Aydeewa Subterrane.', steps = { { title = 'Start', note = '• Talk to Waoud (Heretic\'s Alley, Aht Urhgan Whitegate).' }, { title = 'Requirements', note = '• Any job at level 30.\n• Carry 1,000 gil; a failed reading costs that much, and only one reading per Vana\'diel day.' }, { title = 'Step 1', note = 'Ask Waoud for a divination and give the answers listed under Tips.' }, { title = 'Step 2', note = 'Once he asks for a treasure, zone and wait until the next Vana\'diel day.' }, { title = 'Step 3', note = 'Speak to Waoud twice to learn which of the three items he wants.' }, { title = 'Step 4', note = 'Obtain that item and trade it to Waoud; he returns it and sends you to a colleague in Aydeewa Subterrane.' }, { title = 'Step 5', note = 'Holding the item, enter Aydeewa Subterrane from Bhaflau Thickets and go to Yasfel (map position 380, 340).' }, { title = 'Step 6', note = 'Accept Yasfel\'s offer to receive the Mark of Zahak and return to Whitegate; Blue Mage is unlocked.' }, { title = 'Tips', note = '• Answers in order: One forges for oneself / Absolutely / Burn the scroll / Without hesitation / A chaotic life / Embrace life as a beast / Cut him down / Grant the request / End his pain / Follow your sense of justice.\n• One wrong answer = plain fortune for 1,000 gil; zone and retry next Vana\'diel day.\n• Refusing Yasfel resets the quest to Waoud.\n• Bhaflau Thickets and Aydeewa Subterrane mobs are level 58+; use Sneak/Invisible or bring help.' }, { title = 'Item sources', note = '• Bluish jewel by a river = Siren\'s Tear: in the North Gustaberg stream (map position 318, 210); moves along the bank after each attempt. Unequip main and sub weapons and keep a free slot.\n• Golden sand = Sunsand: ??? in Valkurm Dunes, appears only in dust storms.\n• Blood-red stone = Dangruf Stone: ??? in Dangruf Wadi, appears only in clear or sunny weather.' }, { title = 'Reward', note = '• Title: Bearer of the Mark of Zahak' } } },
    { name = 'Luck of the Draw', group = 'Aht Urhgan', desc = 'Corsair unlock: Ratihb asks you to follow his son Wasuhd\'s trail; talking and examining only, no fights or trades.', steps = { { title = 'Requirements', note = '• Any job at level 30.\n• Arrapago Reef and Talacca Cove are reached via Caedarva Mire.' }, { title = 'Step 1', note = 'Speak to Ratihb at the Shararat Teahouse in Whitegate.' }, { title = 'Step 2', note = 'Ask Mafwahb about Wasuhd.' }, { title = 'Step 3', note = 'Examine the ??? on the boat in Arrapago Reef.' }, { title = 'Step 4', note = 'Examine the ??? in Talacca Cove to get the Forgotten Hexagun.' }, { title = 'Step 5', note = 'Examine the nearby Rock Slab to get a Corsair Die; Corsair is unlocked.' }, { title = 'Step 6', note = 'Speak to Ratihb once more; this is needed later for Equipped for All Occasions.' }, { title = 'Tips', note = '• Caedarva Mire, Arrapago Reef and Talacca Cove mobs are level 60+; use Sneak/Invisible or bring help.\n• The Hexagun is consumed at the Rock Slab.' }, { title = 'Reward', note = '• Corsair Die\n• Key item: key item 1754\n• Title: Seagull Phratrie Crew Member' } } },
    { name = 'No Strings Attached', group = 'Aht Urhgan', desc = 'Puppetmaster unlock: Shamarhaan in Bastok Markets refers you to Iruki-Waraki, who wants an automaton brought to him.', steps = { { title = 'Requirements', note = '• Any job at level 30.\n• Iruki-Waraki only offers the quest after you speak to Shamarhaan.' }, { title = 'Step 1', note = 'Speak to Shamarhaan in Bastok Markets.' }, { title = 'Step 2', note = 'Speak to Iruki-Waraki (Way of the Devout, Whitegate).' }, { title = 'Step 3', note = 'Speak to Ghatsad, who points you to Arrapago Reef.' }, { title = 'Step 4', note = 'Examine the ??? in Arrapago Reef to get an Antique Automaton.' }, { title = 'Step 5', note = 'Return it to Ghatsad.' }, { title = 'Step 6', note = 'Wait one Vana\'diel day and speak to Ghatsad again.' }, { title = 'Step 7', note = 'Speak to Iruki-Waraki and name your automaton to get the Animator; Puppetmaster is unlocked.' }, { title = 'Tips', note = '• Arrapago Reef is via Caedarva Mire; both have level 60+ mobs, so use Sneak/Invisible or bring help.\n• The automaton starts with Harlequin head and frame.\n• Replacement Animator: trade Iruki-Waraki 10,000 gil.' }, { title = 'Reward', note = '• Animator\n• Key item: key item 1755\n• Title: Proud Automaton Owner' } } },
