    { name = 'Promotion: Private First Class', group = 'Aht Urhgan', desc = 'First Salaheem\'s Sentinels promotion: bring Naja an imp wing.', steps = { { title = 'Start', note = '• Talk to Naja Salaheem (Salaheem\'s Sentinels, Aht Urhgan Whitegate).' }, { title = 'Items to trade', note = '• Imp Wing' }, { title = 'Key items needed', note = '• Psc Wildcat Badge' }, { title = 'Reward', note = '• Key item: key item 783\n• Title: Private First Class' } } },
    { name = 'Promotion: Superior Private', group = 'Aht Urhgan', desc = 'Find proof that the legendary Dark Rider is really roaming the Empire.', steps = { { title = 'Start', note = '• Talk to Naja Salaheem (Salaheem\'s Sentinels, Aht Urhgan Whitegate).' }, { title = 'Requirements', note = '• Quest done first: Promotion: Private First Class.' }, { title = 'Key items needed', note = '• Pfc Wildcat Badge\n• Dark Rider Hoofprint' }, { title = 'Reward', note = '• Key item: key item 784\n• Title: Superior Private' } } },
    { name = 'Promotion: Lance Corporal', group = 'Aht Urhgan', desc = 'Show fellow mercenary Falzum how to do his job of making mythralline liquid.', steps = { { title = 'Start', note = '• Talk to Naja Salaheem (Salaheem\'s Sentinels, Aht Urhgan Whitegate).' }, { title = 'Requirements', note = '• Quest done first: Promotion: Superior Private.' }, { title = 'Key items needed', note = '• Sp Wildcat Badge' }, { title = 'NPCs involved', note = '• Abquhbah and Nafiwaa (Aht Urhgan Whitegate)\n• Mythralline Wellsprings 1-4 (Wajaom Woodlands)\n• Mythralline Wellspring 5 (Bhaflau Thickets)' }, { title = 'Reward', note = '• Key item: key item 794\n• Title: Lance Corporal' } } },
    { name = 'Promotion: Corporal', group = 'Aht Urhgan', desc = 'Plant a quartz transmitter in the Dark Rider\'s horse\'s hoofprints to track him.', steps = { { title = 'Start', note = '• Talk to Naja Salaheem (Salaheem\'s Sentinels, Aht Urhgan Whitegate).' }, { title = 'Requirements', note = '• Quest done first: Promotion: Lance Corporal.' }, { title = 'Key items', note = '• Needed: Lc Wildcat Badge\n• Received: Quartz Transmitter' }, { title = 'Reward', note = '• Key item: key item 795\n• Title: Corporal' } } },
    { name = 'Promotion: Sergeant', group = 'Aht Urhgan', desc = 'Perfumier Liliroon mistakes the Sentinels for a detective agency; help Naja earn her reward.', steps = { { title = 'Start', note = '• Talk to Naja Salaheem (Salaheem\'s Sentinels).' }, { title = 'Requirements', note = '• Quest done first: Promotion: Corporal.' }, { title = 'NPCs involved', note = '• Totoroon (Nashmau)\n• ??? (Caedarva Mire)' }, { title = 'Items to trade', note = '• Sutlac' }, { title = 'Key items needed', note = '• C Wildcat Badge' }, { title = 'Reward', note = '• Key item: key item 825\n• Title: Sergeant' } } },
    { name = 'Promotion: Sergeant Major', group = 'Aht Urhgan', desc = 'As a sergeant, train your subordinates into proper mercenaries.', steps = { { title = 'Start', note = '• Talk to Naja Salaheem (Salaheem\'s Sentinels).' }, { title = 'Requirements', note = '• Quest done first: Promotion: Sergeant.' }, { title = 'Key items needed', note = '• S Wildcat Badge' }, { title = 'Reward', note = '• Key item: key item 826\n• Title: Sergeant Major' } } },
    { name = 'Promotion: Chief Sergeant', group = 'Aht Urhgan', desc = 'Abquhbah asks you to go to the weapon shop for him.', steps = { { title = 'Start', note = '• Talk to Abquhbah (Salaheem\'s Sentinels).' }, { title = 'Requirements', note = '• Quest done first: Promotion: Sergeant Major.' }, { title = 'NPCs involved', note = '• Hagakoff (Aht Urhgan Whitegate)' }, { title = 'Key items needed', note = '• Scourshroom' }, { title = 'Reward', note = '• Imp. Mtl. Piece\n• Key item: key item 827\n• Title: Chief Sergeant' } } },
    { name = 'Promotion: Second Lieutenant', group = 'Aht Urhgan', desc = 'Enroll in the Salaheem Officer Academy to reach the officer ranks.', steps = { { title = 'Start', note = '• Talk to Naja Salaheem (Salaheem\'s Sentinels).' }, { title = 'Requirements', note = '• Quest done first: Promotion: Chief Sergeant.' }, { title = 'Items to trade', note = '• 3 × Imp. Gold Piece\n• 2 × Imp. Mtl. Piece' }, { title = 'Key items', note = '• Needed: Cs Wildcat Badge\n• Received: Officer Academy Manual' }, { title = 'NPCs involved', note = '• Abquhbah (Aht Urhgan Whitegate)' }, { title = 'Reward', note = '• Key item: key item 894\n• Title: Second Lieutenant' } } },
    { name = 'Promotion: First Lieutenant', group = 'Aht Urhgan', desc = 'Complete the last term at the Salaheem Officer Academy.', steps = { { title = 'Start', note = '• Talk to Naja Salaheem (Salaheem\'s Sentinels).' }, { title = 'Requirements', note = '• Quest done first: Promotion: Second Lieutenant.' }, { title = 'Items to trade', note = '• 5 × Imp. Gold Piece' }, { title = 'Key items needed', note = '• Sl Wildcat Badge' }, { title = 'NPCs involved', note = '• Abquhbah (Aht Urhgan Whitegate)' }, { title = 'Reward', note = '• Key item: key item 900\n• Title: First Lieutenant' } } },
    { name = 'San d\'Oria M1-1: Smash the Orcish Scouts', group = 'San d\'Oria Missions', desc = 'First San d\'Oria mission: kill Orcs outside the city and hand in an Orcish Axe. San d\'Oria citizens with no active mission; repeatable for rank points.', steps = { { title = 'Step 1', note = 'Accept the mission from a gate guard: Ambrotien or Endracion (Southern San d\'Oria) or Grilau (Northern San d\'Oria).' }, { title = 'Step 2', note = 'Kill Orcish Fodders in West or East Ronfaure until an Orcish Axe drops.' }, { title = 'Step 3', note = 'Trade the Orcish Axe to any of those three guards.' }, { title = 'Tips', note = '• Any of the three guards works for accepting and turning in.\n• Orcish Fodders are low level; also found in La Theine Plateau and Ghelsba Outpost.' }, { title = 'Reward', note = '• 150 rank points' } } },
    { name = 'San d\'Oria M1-2: Bat Hunt', group = 'San d\'Oria Missions', desc = 'Clear bats from King Ranperre\'s Tomb and return with proof. San d\'Oria citizens with no active mission; M1-1 not required; repeatable for rank points.', steps = { { title = 'Step 1', note = 'Accept the mission from a gate guard: Ambrotien or Endracion (Southern San d\'Oria) or Grilau (Northern San d\'Oria).' }, { title = 'Step 2', note = 'In King Ranperre\'s Tomb (via East Ronfaure), examine the Tombstone and watch the cutscene.' }, { title = 'Step 3', note = 'Kill Ding Bats in the tomb until Orcish Mail Scales drop.' }, { title = 'Step 4', note = 'Trade the Orcish Mail Scales to any of the three guards.' }, { title = 'Tips', note = '• Ding Bats (level 2-5) appear only at night, 20:00-6:00 Vana\'diel time.\n• Guards refuse the scales until you have seen the Tombstone cutscene.\n• On repeats, still examine the Tombstone, but hand in a Bat Fang (dropped by Mouse Bats in the tomb).' }, { title = 'Reward', note = '• 200 rank points' } } },
    { name = 'San d\'Oria M1-3: Save the Children', group = 'San d\'Oria Missions', desc = 'Free the children the Orcs hold at their Ghelsba Outpost camp.', steps = { { title = 'Requirements', note = '• San d\'Oria citizen, Bat Hunt done.\n• First clear grants Rank 2; repeatable afterwards for rank points.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• See Arnau in Northern San d\'Oria for a cutscene.\n• At Ghelsba Outpost (via West Ronfaure), check the Hut Door to start the battlefield.\n• Kill Fodderchief Vokdek, Sureshot Snatgat and Strongarm Zodvad; get the Orcish Hut Key.\n• Check the Hut Door once more for a cutscene.\n• Report to a gate guard.' }, { title = 'Tips', note = '• Battlefield: 6 players, 10 min, uncapped, Trusts OK.\n• All three Orcs (Lv 6-8) must die.\n• Arnau must be visited on every run, repeats too, or the battlefield stays shut.\n• Players who already cleared it may join you.\n• Arnau has an optional extra scene afterwards.' }, { title = 'Reward', note = '• 1000 gil\n• Rank 2' } } },
    { name = 'San d\'Oria M2-1: The Rescue Drill', group = 'San d\'Oria Missions', desc = 'Join a Temple Knight rescue exercise on La Theine Plateau.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 2 (after Save the Children) plus some rank points.\n• Not repeatable.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Speak with Galaihaurat on La Theine Plateau.\n• Speak with Ruillont inside Ordelle\'s Caves.\n• Get the Bronze Sword from whichever La Theine knight has it: Galaihaurat, Equesobillot or Deaufrain.\n• Trade the sword to Ruillont.\n• Get the Rescue Training Certificate from Vicorpasse in La Theine.\n• Report to a gate guard.' }, { title = 'Tips', note = '• The sword holder is random; ask all three.\n• Free an inventory slot first.\n• Optional extra scenes: after Galaihaurat, talk to Equesobillot, Deaufrain, Vicorpasse, Laurisse, Narvecaint in order.\n• Ordelle\'s Caves is entered from La Theine Plateau.' }, { title = 'Reward', note = '• 300 rank points' } } },
    { name = 'San d\'Oria M2-2: The Davoi Report', group = 'San d\'Oria Missions', desc = 'Fetch the hidden Temple Knight scout\'s report from Davoi.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 2, The Rescue Drill done, some rank points.\n• Repeatable for rank points.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Speak with Zantaviat in Davoi.\n• Check the "!" at map position 211, -104 to get the Lost Document.\n• Return it to Zantaviat for the Temple Knights\' Davoi Report.\n• Check the Papal Chambers door in Northern San d\'Oria.' }, { title = 'Tips', note = '• On repeats, hand the report to a gate guard instead.\n• Davoi Orcs are Lv 20+ and detect by sight and smell; use Invisible and Deodorize if low.' }, { title = 'Reward', note = '• 350 rank points' } } },
    { name = 'San d\'Oria M2-3 (Part 0): Journey Abroad', group = 'San d\'Oria Missions', desc = 'Visit Bastok and Windurst, assist San d\'Oria\'s consul in each, and earn recognition as an adventurer.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 2, The Rescue Drill done, many rank points.\n• Not repeatable.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Get the Letter to the Consuls from Halver, Chateau d\'Oraguille.\n• Show it to a consul: Savae E Paleade (Metalworks, Bastok) for Journey to Bastok (Part 1), or Mourices (Windurst Woods) for Journey to Windurst (Part 1).\n• Finish that task, then do the other nation\'s Part 2; its consul hands you the Kindred Report.\n• Give the Kindred Report to Halver.' }, { title = 'Tips', note = '• Order does not matter.\n• The second nation\'s battlefield is Lv 25 capped, 6 players.\n• Halver also gives Cipher: Halver if you lack it.' }, { title = 'Reward', note = '• 3000 gil\n• Rank 3\n• Key item: key item 35 (Adventurer\'s Certificate)\n• Title: Certified Adventurer' } } },
    { name = 'San d\'Oria M2-3 (Part 1): Journey to Bastok', group = 'San d\'Oria Missions', desc = 'Bring Mythril Sand out of Palborough Mines for San d\'Oria\'s Bastok consul; Pius gives further orders.', steps = { { title = 'Requirements', note = '• Bastok-first leg of Journey Abroad; carry the Letter to the Consuls.' }, { title = 'Walkthrough', note = '• Show the letter to Savae E Paleade in Metalworks.\n• Speak with Pius in Metalworks.\n• Speak with Grohm for three Pickaxes.\n• In Palborough Mines (via North Gustaberg), trade a Pickaxe to any Mythril Seam for a Chunk of Mine Gravel.\n• Trade the gravel to the Refiner Lid, pull its Refiner Lever, then pull the second nearby lever for Mythril Sand.\n• Trade the Mythril Sand to Savae E Paleade.' }, { title = 'Next', note = '• Go to Mourices in Windurst Woods for Journey to Windurst (Part 2).' }, { title = 'Tips', note = '• Pickaxes may break; buy more if all three do.\n• Keep inventory space for pickaxes and sand.\n• Quadav here reach about Lv 23 and track by sound and scent.' } } },
    { name = 'San d\'Oria M2-3 (Part 1): Journey to Windurst', group = 'San d\'Oria Missions', desc = 'Deliver a Heavens Tower offering to the Giddeus Yagudo and return with two of their shields.', steps = { { title = 'Requirements', note = '• Windurst-first leg of Journey Abroad; carry the Letter to the Consuls.' }, { title = 'Walkthrough', note = '• Show the letter to Mourices in Windurst Woods.\n• Enter Heavens Tower for a cutscene.\n• Get the Shield Offering from Kupipi.\n• Give it to Uu Zhoumo in Giddeus.\n• Obtain two Parana Shields from Zhuu Buxu the Silent (Lv 16 NM, Giddeus).\n• Trade both shields to Mourices at once.' }, { title = 'Next', note = '• Go to Savae E Paleade in Metalworks for Journey to Bastok (Part 2).' }, { title = 'Tips', note = '• Expect to kill Zhuu Buxu twice.\n• Kupipi also gives Cipher: Semih if you lack it.\n• Giddeus Yagudo reach about Lv 23 and detect by sight.\n• Catalia, Forine and Erpolant are optional.' } } },
    { name = 'San d\'Oria M2-3 (Part 2): Journey to Bastok', group = 'San d\'Oria Missions', desc = 'Investigate Quadav activity in the depths of Palborough Mines; Pius gives further orders.', steps = { { title = 'Requirements', note = '• Second leg of Journey Abroad, after Journey to Windurst (Part 1).' }, { title = 'Walkthrough', note = '• Speak with Savae E Paleade, then Pius, then Grohm in Metalworks.\n• Pass through Palborough Mines to Waughroon Shrine and check the Burning Circle.\n• Kill the Dark Dragon (Lv 25) and the Seeker (Lv 23); get the Kindred Crest.\n• Return to Savae E Paleade for the Kindred Report.' }, { title = 'Next', note = '• Deliver the Kindred Report to Halver, Chateau d\'Oraguille.' }, { title = 'Tips', note = '• Lv 25 cap, 6 players, 15 min, Trusts OK; no EXP loss.\n• Both enemies must die.\n• Players of any nation who cleared their Rank 2 journey may join.' } } },
    { name = 'San d\'Oria M2-3 (Part 2): Journey to Windurst', group = 'San d\'Oria Missions', desc = 'Drive out the large monster living deep in Giddeus.', steps = { { title = 'Requirements', note = '• Second leg of Journey Abroad, after Journey to Bastok (Part 1).' }, { title = 'Walkthrough', note = '• Speak with Mourices in Windurst Woods.\n• Get the Dark Key from Kupipi in Heavens Tower.\n• Pass through Giddeus to Balga\'s Dais and check the Burning Circle.\n• Kill the Black Dragon (Lv 25) and the Searcher (Lv 23); get the Kindred Crest.\n• Return to Mourices for the Kindred Report.' }, { title = 'Next', note = '• Deliver the Kindred Report to Halver, Chateau d\'Oraguille.' }, { title = 'Tips', note = '• The Dark Key is required to enter.\n• Lv 25 cap, 6 players, 15 min, Trusts OK; no EXP loss.\n• Both enemies must die.\n• Players of any nation who cleared their Rank 2 journey may join.' } } },
    { name = 'San d\'Oria M3-1: Infiltrate Davoi', group = 'San d\'Oria Missions', desc = 'Help San d\'Oria\'s scout in Davoi, on orders from the chateau.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 3 plus some rank points.\n• Repeatable for rank points.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Check the Prince Royal\'s door (map -38, 73) in Chateau d\'Oraguille.\n• Enter Davoi for a cutscene.\n• Get the Royal Knights\' Davoi Report from Quemaricond.\n• Check the Prince Royal\'s door again.' }, { title = 'Tips', note = '• Quemaricond paces a short path.\n• Davoi Orcs are Lv 20+ and detect by sight and smell.\n• Repeat route: Zantaviat, then the East (294, -28), South (336, -136) and North (163, -18) Block Code "!" marks, back to Zantaviat, then a gate guard.' }, { title = 'Reward', note = '• 300 rank points' } } },
    { name = 'San d\'Oria M3-2: The Crystal Spring', group = 'San d\'Oria Missions', desc = 'Fish a Crystal Bass from the spring at Jugner Forest\'s eastern edge.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 3, Infiltrate Davoi done, a fair amount of rank points.\n• Repeatable for rank points.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Catch a Crystal Bass at Crystalwater Spring, Jugner Forest.\n• Trade it to any gate guard.\n• Enter Chateau d\'Oraguille from Northern San d\'Oria for a cutscene.\n• Speak with Chalvatot.' }, { title = 'Tips', note = '• Minnow is the best bait; Little Worm and others also work.\n• The bass is tradeable.\n• Repeats end at the gate guard trade.' }, { title = 'Reward', note = '• 400 rank points' } } },
    { name = 'San d\'Oria M3-3: Appointment to Jeuno', group = 'San d\'Oria Missions', desc = 'Take up your post at San d\'Oria\'s embassy in Jeuno.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 3, Infiltrate Davoi done, many rank points.\n• Not repeatable.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Speak with Halver, Chateau d\'Oraguille.\n• Check the Great Hall door (map 0, 13); receive the Letter to the Ambassador.\n• Give it to Nelcabrit in Ru\'Lude Gardens.\n• Obtain a Delkfutt Key from Porphyrion (Lv 36 NM, Upper Delkfutt\'s Tower).\n• Trade the key to the Cermet Door in Lower Delkfutt\'s Tower (via Qufim Island); it becomes a key item.\n• Check the San d\'Oria embassy door (map -31, -65) in Ru\'Lude Gardens.' }, { title = 'Tips', note = '• Already own the key item? Just check the Cermet Door.\n• Arsha and Chupaile are optional.' }, { title = 'Reward', note = '• 5000 gil\n• Rank 4' } } },
    { name = 'San d\'Oria M4-1: Magicite', group = 'San d\'Oria Missions', desc = 'Recover magicite from the Yagudo, Orc and Quadav strongholds for the archduke in Jeuno.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 4, after Appointment to Jeuno; starts at the Jeuno embassy, not a gate guard.\n• Needs rank points; donate crystals to a San d\'Orian conquest guard such as Aravoge, T.K.' }, { title = 'Walkthrough', note = '• Speak with Nelcabrit in Ru\'Lude Gardens, then check the embassy door (map -31, -65).\n• Check the Audience Chamber door.\n• Speak with Aldo (Lower Jeuno).\n• Speak with Paya-Sabya (Upper Jeuno), then Muckvix (Lower Jeuno).\n• Castle Oztroja: light the torch stands (map -97, -109) using the Yagudo Torch, enter the Altar Room, check the Magicite.\n• Speak with Baudin (Upper Jeuno) to begin Crest of Davoi, then trade him Coeurl Meat.\n• Davoi: check the Wall of Dark Arts, enter Monastic Cavern, check the Magicite.\n• Speak with Sattal-Mansal (Lower Jeuno) and trade a Quadav Charm, then a Qdv. Augury Shell.\n• Beadeaux to Qulun Dome: open the sealed door (map 60, -7) with bell, rosary and necklace; check the Magicite.\n• Check the Audience Chamber door again.\n• Speak with Nelcabrit.' }, { title = 'Tips', note = '• After getting the Silver Bell, the three magicite can be done in any order.\n• Silver Bell, Yagudo Torch, Crest of Davoi, rosary and necklace are kept.\n• Owning an Airship Pass already gives 20,000 gil instead.\n• Coeurl Meat drops from coeurls; Quadav Charm and Augury Shell come from Beadeaux Quadav NMs.' }, { title = 'Reward', note = '• 10000 gil\n• Rank 5\n• Key item: key item 69' } } },
    { name = 'San d\'Oria M5-1: The Ruins of Fei\'Yin', group = 'San d\'Oria Missions', desc = 'Travel to Fei\'Yin on Beaucedine Glacier; details at Chateau d\'Oraguille.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 5, after Magicite.' }, { title = 'Walkthrough', note = '• Enter Chateau d\'Oraguille from Northern San d\'Oria for a cutscene.\n• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Speak with Halver.\n• Enter Fei\'Yin (via Beaucedine Glacier) for a cutscene.\n• In Qu\'Bia Arena, enter the Burning Circle and kill Archlich Taber\'quoan.\n• Give the Burnt Seal to Halver.' }, { title = 'Tips', note = '• Guards withhold missions until the chateau scene is seen.\n• 6 players, Lv 50 cap, 15 min; no EXP loss.\n• Only the Archlich must die; his skeletons respawn.\n• The arena needs the Fei\'Yin arrival scene first.' }, { title = 'Reward', note = '• 400 rank points' } } },
    { name = 'San d\'Oria M5-2: The Shadow Lord', group = 'San d\'Oria Missions', desc = 'Go to Castle Zvahl in Xarcabard; details at Chateau d\'Oraguille.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 5, after The Ruins of Fei\'Yin.\n• Needs rank points; donate crystals to a conquest guard such as Aravoge, T.K.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Speak with Halver, Chateau d\'Oraguille.\n• Check the Prince Royal\'s door.\n• Go Xarcabard, Castle Zvahl Baileys, Castle Zvahl Keep, Throne Room; check the door (map -116, 0).\n• Check it again to enter; defeat the Shadow Lord.\n• Give the Shadow Fragment to Halver.' }, { title = 'Tips', note = '• 6 players, 30 min, uncapped; no EXP loss.\n• Under 50% HP he alternates: immune to magic and Blinds attackers while casting; immune to physical while meleeing. Bring both damage types.\n• Second form spams Implosion; keep HP high.\n• Unlocks Rise of the Zilart (The New Frontier).' }, { title = 'Reward', note = '• 20000 gil\n• Rank 6' } } },
    { name = 'San d\'Oria M6-1: Leaute\'s Last Wishes', group = 'San d\'Oria Missions', desc = 'A task for Monarlais Halver concerning the late Queen Leaute.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 6, after The Shadow Lord.\n• Needs rank points; donate crystals to a conquest guard such as Aravoge, T.K.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Speak with Halver, Chateau d\'Oraguille.\n• Check the Great Hall door.\n• In Western Altepa Desert, check the Dreamrose and kill Sabotender Enamorado.\n• Check the Dreamrose again.\n• Speak with Halver.\n• Walk to the stairs of Chalvatot\'s garden (map -84, 58) for the final cutscene.' }, { title = 'Tips', note = '• Sabotender Enamorado is a Lv 63 NM.\n• Keep the Piece of Paper; the next mission uses it.' }, { title = 'Reward', note = '• Key item: key item 270\n• 600 rank points' } } },
    { name = 'San d\'Oria M6-2: Ranperre\'s Final Rest', group = 'San d\'Oria Missions', desc = 'Prince Trion wants an adventurer; find him in his chamber.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 6, after Leaute\'s Last Wishes, holding the Piece of Paper.\n• Needs rank points; donate crystals to a conquest guard such as Aravoge, T.K.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Check the Prince Royal\'s door, Chateau d\'Oraguille.\n• In King Ranperre\'s Tomb (via East Ronfaure), check the Heavy Stone Door; kill Corrupted Yorgos, Corrupted Soffeil and Corrupted Ulbrig.\n• Check the door again and go through.\n• Check the Tombstone beyond it.\n• Give the book to a gate guard.\n• Wait past 00:00 JST, zone once, and speak to a gate guard again.\n• Check the Prince Royal\'s door.\n• Check the Heavy Stone Door in the tomb again.\n• Report to a gate guard.' }, { title = 'Tips', note = '• The three NMs are Lv 63-64.\n• Before JST midnight the guards are still reading.' }, { title = 'Reward', note = '• 40000 gil\n• Rank 7' } } },
    { name = 'San d\'Oria M7-1: Prestige of the Papsque', group = 'San d\'Oria Missions', desc = 'The papsque wants a renowned adventurer; see him upstairs in the Northern San d\'Oria cathedral.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 7, after Ranperre\'s Final Rest.\n• Needs rank points; donate crystals to a conquest guard such as Aravoge, T.K.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Check the Papal Chambers door in the cathedral.\n• In West Ronfaure, check the ??? and kill Marauder Dvogzog.\n• Check the ??? again.\n• Check the Papal Chambers door with the tablet.' }, { title = 'Tips', note = '• Marauder Dvogzog is a Lv 67 NM.\n• Re-check the ??? before zoning, or you must refight him.' }, { title = 'Reward', note = '• 1000 rank points' } } },
    { name = 'San d\'Oria M7-2: The Secret Weapon', group = 'San d\'Oria Missions', desc = 'Secretly investigate Orc activity at Yughott Grotto.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 7, after Prestige of the Papsque.\n• Needs rank points; donate crystals to a conquest guard such as Aravoge, T.K.' }, { title = 'Walkthrough', note = '• Speak with a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria) for a cutscene.\n• Walk into the garden near Chalvatot (map -90, 80), Chateau d\'Oraguille.\n• Accept the mission from a gate guard.\n• Via Ghelsba Outpost and Yughott Grotto, enter the Horlais Peak Burning Circle; kill the Orcs and war machines.\n• Report to a gate guard.' }, { title = 'Tips', note = '• 6 players, 30 min, uncapped; no EXP loss.\n• Orcs are Lv 68 NMs fighting together.' }, { title = 'Reward', note = '• 60000 gil\n• Rank 8' } } },
    { name = 'San d\'Oria M8-1: Coming of Age', group = 'San d\'Oria Missions', desc = 'Assist Monarlais Halver with Princess Claidie\'s coming-of-age ceremony.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 8, after The Secret Weapon.\n• Needs rank points; donate crystals to a conquest guard such as Aravoge, T.K.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Enter Chateau d\'Oraguille for a cutscene.\n• Speak with Halver.\n• In Quicksand Caves, check the Fountain of Kings; kill Honor and Valor.\n• Check the fountain again.\n• Give the Drops of Amnio to Halver.' }, { title = 'Tips', note = '• Honor and Valor are paired Lv 70 NMs.\n• To unlock the next mission, enter Northern San d\'Oria after 00:00 JST for a cutscene.' }, { title = 'Reward', note = '• 800 rank points' } } },
    { name = 'San d\'Oria M8-2: Lightbringer', group = 'San d\'Oria Missions', desc = 'Royaulais Destin summons you; seek an audience at Chateau d\'Oraguille.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 8, after Coming of Age and its follow-up cutscene.\n• Needs rank points; donate crystals to a conquest guard such as Aravoge, T.K.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Check the Great Hall door, Chateau d\'Oraguille.\n• Speak with Rahal.\n• In the Temple of Uggalepih, check the three ??? near the Granite Door.\n• Check the Granite Door with all three pieces; kill Nio-A and Nio-Hum.\n• Check the Granite Door again.\n• Check the Great Hall door in the chateau.' }, { title = 'Tips', note = '• The ??? can be done in any order.\n• Nio-A and Nio-Hum are Lv 72 NMs.' }, { title = 'Reward', note = '• 80000 gil\n• Rank 9' } } },
    { name = 'San d\'Oria M9-1: Breaking Barriers', group = 'San d\'Oria Missions', desc = 'A threat to San d\'Oria; report to Chateau d\'Oraguille for details.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 9, after Lightbringer.\n• Needs rank points; donate crystals to a conquest guard such as Aravoge, T.K.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Check the Great Hall door, Chateau d\'Oraguille.\n• Check the ??? in the Valley of Sorrows (via Cape Teriggan).\n• Check the ??? in Xarcabard.\n• Check the ??? in Batallia Downs; kill Suparna and Suparna Fledgling.\n• Check that ??? again.\n• Check the Great Hall door.' }, { title = 'Tips', note = '• Figures must be obtained in order: Titan, Garuda, Leviathan.\n• Suparna Lv 72, Suparna Fledgling Lv 68 (NMs).' }, { title = 'Reward', note = '• 900 rank points' } } },
    { name = 'San d\'Oria M9-2: The Heir to the Light', group = 'San d\'Oria Missions', desc = 'Stand guard at the Rites of Succession in the Northern San d\'Oria cathedral.', steps = { { title = 'Requirements', note = '• San d\'Oria Rank 9, after Breaking Barriers.\n• Needs rank points; donate crystals to a conquest guard such as Aravoge, T.K.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Ambrotien/Endracion, Southern San d\'Oria; Grilau, Northern San d\'Oria).\n• Zone into Northern San d\'Oria for a cutscene.\n• Enter Chateau d\'Oraguille for a cutscene.\n• Enter Fei\'Yin (via Beaucedine Glacier) for a cutscene.\n• Win the Qu\'Bia Arena Burning Circle fight.\n• Zone into Northern San d\'Oria for a cutscene.\n• Check the Great Hall door in the chateau.\n• Check the Heavy Stone Door in King Ranperre\'s Tomb.\n• Speak with Halver.' }, { title = 'Tips', note = '• 6 players, 30 min, uncapped; no EXP loss.\n• Wave 1: Death Clan Orcs. Wave 2: Warlord Rojgnoj and two Hands, with Prince Trion helping; losing Trion fails the fight.\n• Full inventory? Get the flag from Halver later.' }, { title = 'Reward', note = '• 100000 gil\n• Rank 10\n• San d\'Orian Flag\n• Title: San d\'Orian Royal Heir' } } },
    { name = 'Bastok M1-1: The Zeruhn Report', group = 'Bastok Missions', desc = 'Carry Overseer Makarim\'s report from Zeruhn Mines to Naji outside the President\'s Office.', steps = { { title = 'Requirements', note = '• Bastok citizen; only mission offered until done. Not repeatable.' }, { title = 'Walkthrough', note = '• Accept from a gate guard: Rashid (Bastok Mines), Cleades (Bastok Markets), Argus (Port Bastok) or Malduc (Metalworks).\n• In Zeruhn Mines, get the Zeruhn Report from Makarim deep inside.\n• Give it to Naji at the President\'s Office, Metalworks.' }, { title = 'Tips', note = '• Rasmus is optional.\n• Next: A Geological Survey.' } } },
    { name = 'Bastok M1-2: A Geological Survey', group = 'Bastok Missions', desc = 'Test Dangruf Wadi\'s gas vents for Chief Engineer Cid.', steps = { { title = 'Requirements', note = '• Bastok citizen, The Zeruhn Report done. Not repeatable.' }, { title = 'Walkthrough', note = '• Accept from a gate guard: Rashid (Bastok Mines), Cleades (Bastok Markets), Argus (Port Bastok) or Malduc (Metalworks).\n• Get the Blue Acidity Tester from Cid, Metalworks.\n• Step on a Dangruf Wadi geyser: I-8 (-133, 133), H-8 (-213, 93) or J-3 (-67, 533); the tester turns red.\n• Return it to Cid.' }, { title = 'Tips', note = '• Any geyser works.\n• Next: Fetichism.' } } },
    { name = 'Bastok M1-3: Fetichism', group = 'Bastok Missions', desc = 'Collect all four parts of a Quadav fetich in Palborough Mines.', steps = { { title = 'Requirements', note = '• Bastok citizen, A Geological Survey done.\n• First clear grants Rank 2; repeatable for rank points.' }, { title = 'Walkthrough', note = '• Accept from a gate guard: Rashid (Bastok Mines), Cleades (Bastok Markets), Argus (Port Bastok) or Malduc (Metalworks).\n• Hunt Quadav in Palborough Mines (via North Gustaberg) for Fetich Head, Fetich Torso, Fetich Arms and Fetich Legs.\n• Trade all four together to a gate guard.' }, { title = 'Tips', note = '• Amber Quadav drop pieces too.\n• Each piece is Rare.\n• Rank points reset on promotion; repeating this earns them for Rank 2 missions.\n• Next: The Crystal Line.' }, { title = 'Reward', note = '• 1000 gil\n• Rank 2\n• 200 rank points' } } },
    { name = 'Bastok M2-1: The Crystal Line', group = 'Bastok Missions', desc = 'Get a Faded Crystal from the crystal-draining structure on Konschtat Highlands for Cid.', steps = { { title = 'Requirements', note = '• Bastok Rank 2, Fetichism done, some Rank 2 rank points.' }, { title = 'Walkthrough', note = '• Accept from a gate guard: Rashid (Bastok Mines), Cleades (Bastok Markets), Argus (Port Bastok) or Malduc (Metalworks).\n• Speak with Cid, Metalworks; keep a slot free for his crystal.\n• Trade a crystal to the Telepoint on Konschtat Highlands (via North Gustaberg) for a Faded Crystal.\n• Trade the Faded Crystal to Cid for his report.\n• Give the report to Ayame, Metalworks.' }, { title = 'Tips', note = '• Rank points: repeat Fetichism or give crystals to conquest guards Rabid Wolf, I.M. (Bastok Markets), Crying Wind, I.M. (Bastok Mines) or Flying Axe, I.M. (Port Bastok).\n• Any elemental crystal works at the Telepoint.\n• Talk to Cid before trading him the Faded Crystal.\n• Next: Wading Beasts or The Emissary.' }, { title = 'Reward', note = '• 200 rank points' } } },
    { name = 'Bastok M2-2: Wading Beasts', group = 'Bastok Missions', desc = 'Bring a Lizard Egg from Dangruf Wadi to Senator Alois in the President\'s Office.', steps = { { title = 'Requirements', note = '• Bastok Rank 2, The Crystal Line done, more rank points than it needed.\n• Optional; repeatable for rank points.' }, { title = 'Walkthrough', note = '• Accept from a gate guard: Rashid (Bastok Mines), Cleades (Bastok Markets), Argus (Port Bastok) or Malduc (Metalworks).\n• Get a Lizard Egg from Steam Lizards in Dangruf Wadi.\n• Trade it to Alois, President\'s Office, Metalworks.' }, { title = 'Tips', note = '• Lizard Eggs are not Rare/Ex; check the Auction House.\n• Not required for The Emissary, but adds rank points.\n• Next: The Emissary.' }, { title = 'Reward', note = '• 250 rank points' } } },
    { name = 'Bastok M2-3: The Emissary', group = 'Bastok Missions', desc = 'Bastok sends you to its consulates in San d\'Oria and Windurst; complete both errands, then report home.', steps = { { title = 'Requirements', note = '• Bastok citizen, Rank 2, The Crystal Line done, enough rank points.\n• Completing it grants Rank 3.' }, { title = 'Step 1', note = '• Accept from a gate guard: Rashid (Bastok Mines), Cleades (Bastok Markets), Argus (Port Bastok) or Malduc (Metalworks).' }, { title = 'Step 2', note = '• Get the consul letter from Naji outside the President\'s Office, Metalworks.' }, { title = 'Step 3', note = '• Start one nation: Baraka in Northern San d\'Oria or Melek in Port Windurst.' }, { title = 'Step 4', note = '• Finish that part, then do the other nation\'s Part 2; it yields the Kindred Report.' }, { title = 'Step 5', note = '• Hand the Kindred Report to Naji.' }, { title = 'Notes', note = '• Both Part 2 battlefields cap at level 25.\n• Rank points: repeat Wading Beasts or Fetichism, or trade crystals to an I.M. guard like Rabid Wolf, I.M. (Bastok Markets).\n• Next: The Four Musketeers.' }, { title = 'Reward', note = '• Rank 3, 3000 gil, Adventurer\'s Certificate (key item 35), title Certified Adventurer.' } } },
    { name = 'Bastok M2-3: The Emissary (San d\'Oria)', group = 'Bastok Missions', desc = 'San d\'Oria-first branch of The Emissary: kill Warchief Vatgit in Ghelsba Outpost. Needs Naji\'s letter.', steps = { { title = 'Step 1', note = '• Talk to Baraka at the Bastokan consulate, Northern San d\'Oria, then Helaku nearby.' }, { title = 'Step 2', note = '• Speak with Halver in Chateau d\'Oraguille.' }, { title = 'Step 3', note = '• Kill Warchief Vatgit (lv 16) in Ghelsba Outpost, via West Ronfaure; party members in zone share credit.' }, { title = 'Step 4', note = '• Report to Helaku.' }, { title = 'Notes', note = '• Halver also hands out Cipher: Halver if you lack it.\n• Next: Melek in Port Windurst for The Emissary (Windurst) Part 2.' } } },
    { name = 'Bastok M2-3 (Part 1): The Emissary (Windurst)', group = 'Bastok Missions', desc = 'Windurst-first branch of The Emissary: deliver an offering to the Yagudo in Giddeus. Needs Naji\'s letter.', steps = { { title = 'Step 1', note = '• Talk to Melek at the Bastokan consulate, Port Windurst.' }, { title = 'Step 2', note = '• Enter Heavens Tower (Windurst Walls) for a cutscene; Kupipi gives the Sword Offering.' }, { title = 'Step 3', note = '• Have Gold Skull at the consulate swap the sword.' }, { title = 'Step 4', note = '• In Giddeus (from West Sarutabaruta) speak to Uu Zhoumo; he wants an Aspir Knife.' }, { title = 'Step 5', note = '• Kill NM Eyy Mon the Ironbreaker (lv 16, Giddeus) for the Aspir Knife (Ex) and trade it to Uu Zhoumo.' }, { title = 'Step 6', note = '• Report to Melek.' }, { title = 'Notes', note = '• Kupipi also gives Cipher: Semih if you lack it.\n• Next: Helaku in Northern San d\'Oria for The Emissary (San d\'Oria) Part 2.' } } },
    { name = 'Bastok M2-3 (Part 2): The Emissary (San d\'Oria)', group = 'Bastok Missions', desc = 'After the Windurst part, fight at Horlais Peak via Yughott Grotto for the Kindred Report.', steps = { { title = 'Step 1', note = '• Accept from Helaku, Bastokan consulate, Northern San d\'Oria.' }, { title = 'Step 2', note = '• Speak with Halver in Chateau d\'Oraguille.' }, { title = 'Step 3', note = '• Go West Ronfaure > Ghelsba Outpost > Yughott Grotto > Horlais Peak and enter the Burning Circle.' }, { title = 'Step 4', note = '• Kill Dread Dragon and its Spotter to obtain the Kindred Crest.' }, { title = 'Step 5', note = '• Give the crest to Helaku for the Kindred Report.' }, { title = 'Notes', note = '• BCNM: 6 players, level 25 cap, 15 min, trusts OK, no XP loss on death.\n• Allies may join if they finished their nation\'s 2-3 or are on this step.\n• Halver gives Cipher: Halver if you lack it.\n• Next: Naji in Metalworks.' } } },
    { name = 'Bastok M2-3 (Part 2): The Emissary (Windurst)', group = 'Bastok Missions', desc = 'After the San d\'Oria part, slay the beast at Balga\'s Dais for the Kindred Report.', steps = { { title = 'Step 1', note = '• Talk to Melek, Bastokan consulate, Port Windurst.' }, { title = 'Step 2', note = '• Get the Dark Key from Kupipi in Heavens Tower, Windurst Walls.' }, { title = 'Step 3', note = '• Go West Sarutabaruta > Giddeus > Balga\'s Dais and enter the Burning Circle.' }, { title = 'Step 4', note = '• Kill Black Dragon and its Searcher to obtain the Kindred Crest.' }, { title = 'Step 5', note = '• Give the crest to Melek for the Kindred Report.' }, { title = 'Notes', note = '• BCNM: 6 players, level 25 cap, 15 min, trusts OK, no XP loss.\n• Allies may join if they finished their nation\'s 2-3 or are on this step.\n• Kupipi\'s post-fight talk is optional.\n• Next: Naji in Metalworks.' } } },
    { name = 'Bastok M3-1: The Four Musketeers', group = 'Bastok Missions', desc = 'Join Bastok\'s raid on the Quadav at Beadeaux, as briefed by Iron Eater.', steps = { { title = 'Requirements', note = '• Bastok Rank 3, The Emissary done, some Rank 3 rank points.' }, { title = 'Step 1', note = '• Accept from a gate guard: Rashid, Cleades, Argus or Malduc.' }, { title = 'Step 2', note = '• Agree to join when Iron Eater (President\'s Office, Metalworks) asks.' }, { title = 'Step 3', note = '• Enter Beadeaux from Pashhow Marshlands (cutscene).' }, { title = 'Step 4', note = '• Kill 20 Copper Quadav (lv 22-27, aggressive, link); party in zone shares credit; count persists if you leave.' }, { title = 'Step 5', note = '• Exit via the Pashhow Marshlands side (not Qulun Dome) for the final cutscene.' }, { title = 'Notes', note = '• Rank points: crystals to Rabid Wolf, I.M. (Bastok Markets) or other I.M. guards.\n• Next: To the Forsaken Mines or Jeuno.' }, { title = 'Reward', note = '• 350 rank points' } } },
    { name = 'Bastok M3-2: To the Forsaken Mines', group = 'Bastok Missions', desc = 'Optional, repeatable Rank 3 mission: bring back Glocolite from Gusgen Mines.', steps = { { title = 'Requirements', note = '• Bastok Rank 3, The Four Musketeers done, more rank points than that mission needed.' }, { title = 'Step 1', note = '• Accept from a gate guard: Rashid, Cleades, Argus or Malduc.' }, { title = 'Step 2', note = '• Optionally ask Davyad in Bastok Mines.' }, { title = 'Step 3', note = '• Obtain Hare Meat (Wadi Hares in Dangruf Wadi, Bog Bunnies in Pashhow Marshlands, or the AH).' }, { title = 'Step 4', note = '• Trade it to the ??? in Gusgen Mines (via Konschtat Highlands) to spawn Blind Moby (lv 25-26).' }, { title = 'Step 5', note = '• Kill it for Glocolite (Rare/Ex; won\'t spawn if you already hold one) and trade that to any gate guard.' }, { title = 'Notes', note = '• Next: Jeuno.' }, { title = 'Reward', note = '• 400 rank points' } } },
    { name = 'Bastok M3-3: Jeuno', group = 'Bastok Missions', desc = 'Get posted to the Bastokan Embassy in Jeuno with a recommendation from Sir Lucius.', steps = { { title = 'Requirements', note = '• Bastok Rank 3, The Four Musketeers done, enough rank points. Grants Rank 4.' }, { title = 'Step 1', note = '• Accept from a gate guard: Rashid, Cleades, Argus or Malduc.' }, { title = 'Step 2', note = '• Get the Letter to the Ambassador from Lucius, Metalworks.' }, { title = 'Step 3', note = '• Speak with Goggehn outside the Bastokan Embassy, Ru\'Lude Gardens.' }, { title = 'Step 4', note = '• Obtain a Delkfutt Key from Porphyrion (NM Gigas, lv 36, Upper Delkfutt\'s Tower).' }, { title = 'Step 5', note = '• Trade it to the Cermet Door in Lower Delkfutt\'s Tower (from Qufim Island); it becomes a key item. If you already hold it as a key item, just examine the door.' }, { title = 'Step 6', note = '• Examine the Bastokan Embassy door in Ru\'Lude Gardens.' }, { title = 'Notes', note = '• Next: Magicite.' }, { title = 'Reward', note = '• Rank 4, 5000 gil' } } },
    { name = 'Bastok M4-1: Magicite', group = 'Bastok Missions', desc = 'Recover the magicite from Davoi, Beadeaux and Castle Oztroja for the Jeuno archduke.', steps = { { title = 'Requirements', note = '• Bastok Rank 4, Jeuno done, enough rank points (crystals to Rabid Wolf, I.M. or another conquest guard). Starts at the embassy, not a gate guard; if the door does nothing you lack points.' }, { title = 'Step 1', note = '• Accept by examining the Bastokan Embassy door, Ru\'Lude Gardens.' }, { title = 'Step 2', note = '• Examine the Audience Chamber door (cutscene).' }, { title = 'Step 3', note = '• Deliver the letter to Aldo, Lower Jeuno.' }, { title = 'Step 4', note = '• Speak with Paya-Sabya (Upper Jeuno), then Muckvix (Lower Jeuno).' }, { title = 'Step 5', note = '• Crest of Davoi: talk to Baudin (Upper Jeuno) and trade him Coeurl Meat.' }, { title = 'Step 6', note = '• Start Mysteries of Beadeaux I and II with Sattal-Mansal (Lower Jeuno); trade him a Quadav Charm, then a Qdv. Augury Shell (both from Beadeaux).' }, { title = 'Step 7', note = '• Davoi: use the Crest of Davoi on the Wall of Dark Arts, enter Monastic Cavern, examine the Magicite.' }, { title = 'Step 8', note = '• Beadeaux > Qulun Dome: the door at (60, -7) opens with the bell, rosary and necklace; examine the Magicite.' }, { title = 'Step 9', note = '• Castle Oztroja: light the torch stands at (-100, -109) with the Yagudo Torch, go to the Altar Room, examine the Magicite.' }, { title = 'Step 10', note = '• Re-examine the Audience Chamber door for a cutscene and Airship Pass (20,000 gil instead if owned).' }, { title = 'Step 11', note = '• Speak with Goggehn outside the embassy.' }, { title = 'Notes', note = '• Magicite can be done in any order.\n• Grants Rank 5 and the message needed for Darkness Rising.' }, { title = 'Reward', note = '• 10000 gil\n• Key item: key item 70' } } },
    { name = 'Bastok M5-1: Darkness Rising', group = 'Bastok Missions', desc = 'Travel to Fei\'Yin beyond Beaucedine Glacier; Naji gives the briefing.', steps = { { title = 'Requirements', note = '• Bastok Rank 5, Magicite done; given by Naji, no extra rank points.' }, { title = 'Step 1', note = '• Accept from Naji, Metalworks. If you refused, select it from a gate guard and talk to Naji again.' }, { title = 'Step 2', note = '• Reach Fei\'Yin through Beaucedine Glacier and watch the arrival cutscene (required).' }, { title = 'Step 3', note = '• Continue to Qu\'Bia Arena and enter the Burning Circle.' }, { title = 'Step 4', note = '• Kill Archlich Taber\'quoan; adds Ancient Sorcerers/Warriors (Warriors respawn) but the fight ends when he dies.' }, { title = 'Step 5', note = '• Report to Naji.' }, { title = 'Notes', note = '• BCNM: 6 players, 15 min, cap 75, trusts OK, no XP loss.' }, { title = 'Reward', note = '• 600 rank points' } } },
    { name = 'Bastok M5-2: Xarcabard, Land of Truths', group = 'Bastok Missions', desc = 'Go to Castle Zvahl in Xarcabard after a briefing from the President.', steps = { { title = 'Requirements', note = '• Bastok Rank 5, Darkness Rising done, enough rank points. Grants Rank 6.' }, { title = 'Step 1', note = '• Accept from a gate guard: Cleades, Rashid, Argus or Malduc.' }, { title = 'Step 2', note = '• Speak with Karst in the President\'s Office, Metalworks.' }, { title = 'Step 3', note = '• Go Beaucedine Glacier > Xarcabard > Castle Zvahl Baileys > Castle Zvahl Keep > Throne Room.' }, { title = 'Step 4', note = '• Examine the Throne Room door for a cutscene, then again to enter; defeat the Shadow Lord (two phases, stay after the first).' }, { title = 'Step 5', note = '• After the cutscene you return to the Baileys entrance; examine the President\'s Office door in Metalworks.' }, { title = 'Notes', note = '• BCNM: 6 players, 30 min, cap 75, trusts OK, no XP loss.\n• Unlocks Rise of the Zilart: The New Frontier.' }, { title = 'Reward', note = '• Rank 6, 20000 gil' } } },
    { name = 'Bastok M6-1: Return of the Talekeeper', group = 'Bastok Missions', desc = 'Investigate rumours of a new Galka Talekeeper, starting with Medicine Eagle in Bastok Mines.', steps = { { title = 'Requirements', note = '• Bastok Rank 6, Xarcabard, Land of Truths done, enough rank points.' }, { title = 'Step 1', note = '• Accept from a gate guard: Cleades, Rashid, Argus or Malduc.' }, { title = 'Step 2', note = '• Speak with Medicine Eagle (Bastok Mines), then Drake Fang (Zeruhn Mines).' }, { title = 'Step 3', note = '• Examine the ??? in Western Altepa Desert to spawn the Eastern and Western Sphinx (auto-claimed; have party ready).' }, { title = 'Step 4', note = '• Kill both and examine the ??? again before zoning.' }, { title = 'Step 5', note = '• Speak with Tall Mountain, Bastok Mines.' }, { title = 'Reward', note = '• 650 rank points' } } },
    { name = 'Bastok M6-2: The Pirates\' Cove', group = 'Bastok Missions', desc = 'Carry Bastok\'s message to Norg; Naji briefs you.', steps = { { title = 'Requirements', note = '• Bastok Rank 6, Return of the Talekeeper done, enough rank points. Grants Rank 7.' }, { title = 'Step 1', note = '• Accept from a gate guard: Cleades, Rashid, Argus or Malduc.' }, { title = 'Step 2', note = '• Speak with Naji (Metalworks), then Gilgamesh in Norg (via Sea Serpent Grotto).' }, { title = 'Step 3', note = '• Obtain Adaman Ore and trade it to the ??? in Ifrit\'s Cauldron (off Yhoator or Yuhtunga Jungle); a Salamander and a Magma spawn.' }, { title = 'Step 4', note = '• Kill the Magma for a Frag Rock; it hits hard and may self-destruct at low HP. Unengaged mobs despawn after a few minutes and the ore is consumed.' }, { title = 'Step 5', note = '• Give the Frag Rock to Gilgamesh, then report to Naji.' }, { title = 'Reward', note = '• Rank 7, 40000 gil' } } },
    { name = 'Bastok M7-1: The Final Image', group = 'Bastok Missions', desc = 'Investigate the Zilart ruins of Ro\'Maeve for Cid.', steps = { { title = 'Requirements', note = '• Bastok Rank 7, The Pirates\' Cove done, enough rank points.' }, { title = 'Step 1', note = '• Accept from a gate guard: Cleades, Rashid, Argus or Malduc.' }, { title = 'Step 2', note = '• Speak with Cid, Metalworks.' }, { title = 'Step 3', note = '• Reach Ro\'Maeve via The Sanctuary of Zi\'Tah and examine the ??? to spawn two Mokkurkalfi (not auto-claimed).' }, { title = 'Step 4', note = '• Kill both and examine the ??? again before zoning.' }, { title = 'Step 5', note = '• Report to Cid.' }, { title = '??? locations', note = '• Moves every 6 Vana\'diel hours among D-10, E-9, E-10, E-11, G-9, I-8 (near J-8), K-10, K-11, L-7, L-10.' }, { title = 'Reward', note = '• 700 rank points' } } },
    { name = 'Bastok M7-2: On My Way', group = 'Bastok Missions', desc = 'Search for the missing Galka elder Werei after the President\'s briefing.', steps = { { title = 'Requirements', note = '• Bastok Rank 7, The Final Image done, enough rank points. Grants Rank 8.' }, { title = 'Step 1', note = '• Accept from a gate guard: Cleades, Rashid, Argus or Malduc.' }, { title = 'Step 2', note = '• Speak with Karst (President\'s Office, Metalworks), then Hilda (Port Bastok).' }, { title = 'Step 3', note = '• Go through Palborough Mines to Waughroon Shrine and enter the Burning Circle.' }, { title = 'Step 4', note = '• Kill Ku\'Jhu Graniteskin, Sa\'Nha Soulsaver, Da\'Shu Knightslayer and Go\'Bha Slaughterer.' }, { title = 'Step 5', note = '• Report to Karst.' }, { title = 'Step 6', note = '• Give the Letter from Werei to Gumbah (Bastok Mines): talk twice. Required before the next mission is offered.' }, { title = 'Notes', note = '• BCNM: 6 players, 30 min, cap 75, trusts OK, no XP loss.\n• Optional extra scene: Cornelia\'s Room door, Metalworks.' }, { title = 'Reward', note = '• Rank 8, 60000 gil' } } },
    { name = 'Bastok M8-1: The Chains That Bind Us', group = 'Bastok Missions', desc = 'Investigate Zepwell Island starting in the Quicksand Caves; Iron Eater briefs you.', steps = { { title = 'Requirements', note = '• Bastok Rank 8, On My Way done and letter given to Gumbah, enough rank points.' }, { title = 'Step 1', note = '• Accept from a gate guard: Cleades, Rashid, Argus or Malduc.' }, { title = 'Step 2', note = '• Agree to go when talking to Iron Eater, Metalworks.' }, { title = 'Step 3', note = '• In the Quicksand Caves (from East or West Altepa Desert), examine the ??? to spawn Centurio IV-VII, Triarius IV-XIV and Princeps IV-XLV (auto-claimed; full party).' }, { title = 'Step 4', note = '• Kill all three, examine the ??? again, then examine the second ???.' }, { title = 'Step 5', note = '• Report to Iron Eater.' }, { title = 'Reward', note = '• 1133 rank points' } } },
    { name = 'Bastok M8-2: Enter the Talekeeper', group = 'Bastok Missions', desc = 'Investigate Kuftal Tunnel, starting with Drake Fang in Zeruhn Mines.', steps = { { title = 'Requirements', note = '• Bastok Rank 8, The Chains That Bind Us done, enough rank points. Grants Rank 9.' }, { title = 'Step 1', note = '• Accept from a gate guard: Cleades, Rashid, Argus or Malduc.' }, { title = 'Step 2', note = '• Speak with Drake Fang, Zeruhn Mines.' }, { title = 'Step 3', note = '• In Kuftal Tunnel (from Western Altepa Desert or Cape Teriggan), examine ??? (top) at (-29, -184).' }, { title = 'Step 4', note = '• Examine ??? (below) at (-28, -186) to spawn Dervo\'s Ghost, Gizerl\'s Ghost and Gordov\'s Ghost (not auto-claimed).' }, { title = 'Step 5', note = '• Kill all three and re-examine ??? (below).' }, { title = 'Step 6', note = '• Return to Drake Fang; a final cutscene in Bastok Mines completes it.' }, { title = 'Reward', note = '• Rank 9, 80000 gil' } } },
    { name = 'Bastok M9-1: The Salt of the Earth', group = 'Bastok Missions', desc = 'Investigate the Vollbow region for senator Alois.', steps = { { title = 'Requirements', note = '• Bastok Rank 9, Enter the Talekeeper done, enough rank points.' }, { title = 'Step 1', note = '• Accept from a gate guard: Cleades, Rashid, Argus or Malduc.' }, { title = 'Step 2', note = '• Speak with Alois (Metalworks), then Dancing Wolf in Rabao (via Western Altepa Desert).' }, { title = 'Step 3', note = '• Examine the ??? in Gustav Tunnel (from Valkurm Dunes or Cape Teriggan) to spawn a Gigaplasm.' }, { title = 'Step 4', note = '• Kill it and all splits: 2 Macroplasms, 4 Microplasms, 8 Nanoplasms (15 total); idle plasms despawn and you must restart at the ???. Then examine the ??? for the salt.' }, { title = 'Step 5', note = '• Speak with Dancing Wolf again, then report to Alois.' }, { title = 'Notes', note = '• Optional: talk to Franziska (Metalworks) twice for two scenes.' }, { title = 'Reward', note = '• 1500 rank points' } } },
    { name = 'Bastok M9-2: Where Two Paths Converge', group = 'Bastok Missions', desc = 'Zeid has attacked an adventurer in Xarcabard; confront him in Castle Zvahl.', steps = { { title = 'Requirements', note = '• Bastok Rank 9, The Salt of the Earth done, enough rank points. Grants Rank 10.' }, { title = 'Step 1', note = '• Accept from a gate guard: Cleades, Rashid, Argus or Malduc.' }, { title = 'Step 2', note = '• Speak with Iron Eater outside the President\'s Office, Metalworks.' }, { title = 'Step 3', note = '• Go Beaucedine Glacier > Xarcabard > Castle Zvahl Baileys > Castle Zvahl Keep > Throne Room.' }, { title = 'Step 4', note = '• Enter via the Throne Room door and defeat Zeid (two phases; stay after the first).' }, { title = 'Step 5', note = '• Report to Iron Eater.' }, { title = 'Notes', note = '• BCNM: 6 players, 30 min, cap 75, no XP loss, no trusts.\n• Bastokan Flag awarded; if inventory is full, collect later from Iron Eater.' }, { title = 'Reward', note = '• Rank 10, 100000 gil, Bastokan Flag\n• Title: Hero Among Heroes' } } },
    { name = 'Windurst M1-1: The Horutoto Ruins Experiment', group = 'Windurst Missions', desc = 'First Windurst mission: assist the Orastery Minister\'s experiment in the east tower of the Horutoto Ruins.', steps = { { title = 'Requirements', note = '• Windurst Rank 1, no active mission; one-time only.' }, { title = 'Step 1', note = '• Accept from a gate guard: Rakoh Buuma (Windurst Woods), Mokyokyo (Windurst Waters), Zokima-Rokima (Windurst Walls) or Janshura-Rashura (Port Windurst). Each gives a different title.' }, { title = 'Step 2', note = '• Speak with Hakkuru-Rinkuru at the Orastery, Port Windurst.' }, { title = 'Step 3', note = '• Enter Inner Horutoto Ruins from East Sarutabaruta at (399, 100).' }, { title = 'Step 4', note = '• Examine the Gate: Magical Gizmo (cutscene; this randomizes the broken gizmo).' }, { title = 'Step 5', note = '• Check the six Ancient Magical Gizmos for the Cracked Mana Orb: (465, 100), (407, 60), (465, 20), (296, 20), (353, 60), (296, 100).' }, { title = 'Step 6', note = '• Bring the orb to Hakkuru-Rinkuru.' }, { title = 'Notes', note = '• Next: The Heart of the Matter.' }, { title = 'Reward', note = '• 250 rank points' } } },
    { name = 'Windurst M1-2: The Heart of the Matter', group = 'Windurst Missions', desc = 'Charge the Manustery\'s Cardian Mana Orbs in the southeastern Horutoto tower.', steps = { { title = 'Requirements', note = '• The Horutoto Ruins Experiment done, no active mission.' }, { title = 'Step 1', note = '• Accept from a gate guard: Rakoh Buuma, Mokyokyo, Zokima-Rokima or Janshura-Rashura.' }, { title = 'Step 2', note = '• Get six Dark Mana Orbs from Apururu, Manustery, Windurst Woods.' }, { title = 'Step 3', note = '• Get the Southeastern Star Charm from Pore-Ohre by the Marguerite Tower, East Sarutabaruta.' }, { title = 'Step 4', note = '• Enter Outer Horutoto Ruins at (260, -479); put an orb in each gizmo: (542, -618), (500, -573), (458, -618), (458, -702), (500, -747), (542, -702).' }, { title = 'Step 5', note = '• Examine the Gate: Magical Gizmo on the east wall (charm consumed).' }, { title = 'Step 6', note = '• Collect a Glowing Mana Orb from each gizmo, any order.' }, { title = 'Step 7', note = '• Report to Apururu; the cutscene on exiting to East Sarutabaruta is normal.' }, { title = 'Notes', note = '• Next: The Price of Peace.' }, { title = 'Reward', note = '• 250 rank points' } } },
    { name = 'Windurst M1-3: The Price of Peace', group = 'Windurst Missions', desc = 'Deliver the Rhinostery\'s food and drink offerings to the Yagudo altar keepers in Giddeus.', steps = { { title = 'Requirements', note = '• The Heart of the Matter done, no active mission. Grants Rank 2.' }, { title = 'Step 1', note = '• Accept from a gate guard: Rakoh Buuma, Mokyokyo, Zokima-Rokima or Janshura-Rashura.' }, { title = 'Step 2', note = '• Get a Food Offering and Drink Offering from Leepe-Hoppe, Rhinostery roof, Windurst Waters.' }, { title = 'Step 3', note = '• In Giddeus (from West Sarutabaruta) give one each to Laa Mozi and Ghoo Pakya.' }, { title = 'Step 4', note = '• Walk the Rhinostery roof near (27, -202) to trigger a cutscene.' }, { title = 'Step 5', note = '• Report to any gate guard.' }, { title = 'Notes', note = '• From Rank 2 the next mission needs rank points (see Lost for Words).\n• Next: Lost for Words.' }, { title = 'Reward', note = '• Rank 2, 1000 gil' } } },
    { name = 'Windurst M2-1: Lost for Words', group = 'Windurst Missions', desc = 'Help the Optistery recover a forbidden Book of the Gods from the Cat Burglar.', steps = { { title = 'Requirements', note = '• Windurst Rank 2, The Price of Peace done, enough rank points.' }, { title = 'Step 1', note = '• Accept from a gate guard: Rakoh Buuma, Mokyokyo, Zokima-Rokima or Janshura-Rashura.' }, { title = 'Step 2', note = '• Speak with Tosuka-Porika, Optistery, Windurst Waters.' }, { title = 'Step 3', note = '• Agree to listen to Nanaa Mihgo (Windurst Woods) for the Lapis Monocle; ask again if you decline.' }, { title = 'Step 4', note = '• In Maze of Shakhrami (from Tahrongi Canyon), search Fossil Rocks for Lapis Coral; target is random per player: (40, 212), (-85, -28), (128, -128), (134, -67), (-11, 160), (17, 185), (49, 152), (9, -9).' }, { title = 'Step 5', note = '• Give the coral to Nanaa Mihgo for the Hideout Key.' }, { title = 'Step 6', note = '• Examine the Mahogany Door in Inner Horutoto Ruins, then the House of the Hero door in Windurst Walls.' }, { title = 'Step 7', note = '• Report to Tosuka-Porika.' }, { title = 'Rank points', note = '• Trade crystals to Harara, W.W. (107, -49, Windurst Woods), Puroiko-Maiko, W.W. (-31, 227, Windurst Waters) or Milma-Hapilma, W.W. (-227, 209, Port Windurst); light/dark crystals are worth slightly more.' }, { title = 'Notes', note = '• Next: A Testing Time (optional) or The Three Kingdoms.' }, { title = 'Reward', note = '• 300 rank points' } } },
    { name = 'Windurst M2-2: A Testing Time', group = 'Windurst Missions', desc = 'Optional, repeatable: hunt 30 monsters in a set time for the Aurastery\'s skills test.', steps = { { title = 'Requirements', note = '• Windurst Rank 2, Lost for Words done, Rank 2 bar about one-third full. Not needed for The Three Kingdoms.' }, { title = 'Step 1', note = '• Accept from a gate guard: Rakoh Buuma, Mokyokyo, Zokima-Rokima or Janshura-Rashura.' }, { title = 'Step 2', note = '• Accept the test from Moreno-Toeno, Aurastery, Windurst Waters, to receive the Creature Counter Magic Doll; note the game time.' }, { title = 'Step 3', note = '• Kill 30+ monsters in Tahrongi Canyon within one Vana\'diel day; only kills after receiving the doll count.' }, { title = 'Step 4', note = '• Report during the final game hour of that day (e.g. doll at 8:00, return 7:00-8:00 next day; about 2.5 real minutes).' }, { title = 'Notes', note = '• Early: told hours remaining. Late or under 30: fail; re-accept from a gate guard and talk to Moreno-Toeno.\n• Repeats: Buburimu Peninsula, two Vana\'diel days, 30 kills, report in the last hour of day two.\n• Next: The Three Kingdoms.' }, { title = 'Reward', note = '• 300 rank points' } } },
    { name = 'Windurst M2-3: The Three Kingdoms', group = 'Windurst Missions', desc = 'Rank 2 to Rank 3 mission: Heavens Tower sends you to report on and help San d\'Oria and Bastok via Windurst\'s consulates. Sailing Mhaura to Selbina is the suggested route.', steps = { { title = 'Requirements', note = '• Windurst citizen, Rank 2, Lost for Words done, rank bar ~4/5 full.\n• The two cities can be done in either order.' }, { title = 'Walkthrough', note = '• Accept from a gate guard (Rakoh Buuma, Mokyokyo, Zokima-Rokima or Janshura-Rashura).\n• See Kupipi in Heavens Tower for the Letter to the Consuls.\n• San d\'Oria first: Heruze-Moruze, then Kasaroro in Northern San d\'Oria; continue in The Three Kingdoms (San d\'Oria).\n• Bastok first: Patt-Pott in the Metalworks; continue in The Three Kingdoms (Bastok).\n• Then hand the letter to the other consul (Patt-Pott or Kasaroro) for Part 2, which yields the Kindred Report.\n• Give the report to Kupipi to finish.' }, { title = 'Tips', note = '• Kupipi gives Cipher: Semih if you lack that trust.\n• Part 2 ends in a level-25-cap battlefield, max 6 players.\n• Crystals to a W.W. conquest overseer still add rank points.\n• Next: To Each His Own Right.' }, { title = 'Reward', note = '• Rank 3, 3,000 gil, Adventurer\'s Certificate (key item 35), title Certified Adventurer.' } } },
    { name = 'Windurst M2-3: The Three Kingdoms (San d\'Oria)', group = 'Windurst Missions', desc = 'San d\'Oria leg when visited first: kill the Orc warchief at the top camp of Ghelsba Outpost.', steps = { { title = 'Walkthrough', note = '• Starts after Kasaroro (Northern San d\'Oria) reads your letter.\n• Speak with Halver in Chateau d\'Oraguille.\n• Kill Warchief Vatgit in Ghelsba Outpost.\n• Report to Kasaroro.' }, { title = 'Tips', note = '• Kills before talking to Halver don\'t count.\n• Vatgit: level 16 Orc NM, aggressive, links with Orcs. Ghelsba Outpost is off West Ronfaure.\n• Halver gives Cipher: Halver if you lack it.\n• Next: Patt-Pott in the Metalworks for The Three Kingdoms (Bastok), Part 2.' } } },
    { name = 'Windurst M2-3 (Part 1): The Three Kingdoms (Bastok)', group = 'Windurst Missions', desc = 'Bastok leg when visited first: study Bastok\'s mining and bring Mythril Sand from Palborough Mines; Pius gives the orders.', steps = { { title = 'Walkthrough', note = '• Starts after Patt-Pott (Metalworks) reads your letter.\n• Talk to Pius, then Grohm for 5 Pickaxes.\n• In Palborough Mines trade a Pickaxe to a Mythril Seam for Mine Gravel.\n• Trade gravel to the Refiner Lid and pull the adjacent Refiner Lever.\n• Pull the second Refiner Lever one floor down to get Mythril Sand.\n• Trade the sand to Patt-Pott.' }, { title = 'Tips', note = '• Free bag space first; Grohm holds pickaxes if you\'re full.\n• Pickaxes break often; any Mythril Seam works.\n• Palborough Mines is off North Gustaberg.\n• Next: Kasaroro (Northern San d\'Oria) for The Three Kingdoms (San d\'Oria), Part 2.' } } },
    { name = 'Windurst M2-3 (Part 2): The Three Kingdoms (San d\'Oria)', group = 'Windurst Missions', desc = 'Second leg if Bastok was done first: investigate Yughott Grotto inside Ghelsba Outpost, ending at Horlais Peak.', steps = { { title = 'Walkthrough', note = '• Give your letter to Kasaroro (Northern San d\'Oria).\n• Talk to Halver in Chateau d\'Oraguille.\n• Travel Ghelsba Outpost > Yughott Grotto > Horlais Peak; enter the Burning Circle.\n• Kill Dread Dragon and Spotter for the Kindred Crest.\n• Kasaroro exchanges the crest for the Kindred Report.' }, { title = 'Battlefield', note = '• Level cap 25, 6 players, 15 min, Trusts allowed.\n• Both enemies must die; no EXP loss on KO.' }, { title = 'Tips', note = '• Halver gives Cipher: Halver if you lack it.\n• Next: Kindred Report to Kupipi in Heavens Tower.' } } },
    { name = 'Windurst M2-3 (Part 2): The Three Kingdoms (Bastok)', group = 'Windurst Missions', desc = 'Second leg if San d\'Oria was done first: investigate the Quadav-held depths of Palborough Mines; Pius gives orders.', steps = { { title = 'Walkthrough', note = '• Give your letter to Patt-Pott (Metalworks).\n• Talk to Pius, then Grohm.\n• Travel Palborough Mines > Waughroon Shrine; enter the Burning Circle.\n• Kill Dark Dragon and Seeker for the Kindred Crest.\n• Patt-Pott exchanges the crest for the Kindred Report.' }, { title = 'Battlefield', note = '• Level cap 25, 6 players, 15 min, Trusts allowed.\n• Both enemies must die; no EXP loss on KO.' }, { title = 'Tips', note = '• Palborough Mines is off North Gustaberg.\n• Next: Kindred Report to Kupipi in Heavens Tower.' } } },
    { name = 'Windurst M3-1: To Each His Own Right', group = 'Windurst Missions', desc = 'Sibyl Guard captain Semih Lafihna orders you to trail Orastery Minister Ajido-Marujido and learn his intent; ask at the Orastery if lost.', steps = { { title = 'Requirements', note = '• Windurst Rank 3, The Three Kingdoms done, rank bar ~1/5.' }, { title = 'Walkthrough', note = '• Accept from a Windurst gate guard.\n• Kupipi (Heavens Tower) gives the Starway Stairway Bauble.\n• Open the Starway Stairway door and talk to Rhy Epocan.\n• Talk to Hakkuru-Rinkuru at the Orastery (Port Windurst).\n• Castle Oztroja: stand between the Handles (20, -14) and pull the trap-door one; cutscene.\n• Report to Rhy Epocan.' }, { title = 'Tips', note = '• The trap-door and brass-door handles swap each Vana\'diel day; if the brass door opens, use the other.\n• You must stand exactly between them.\n• Castle Oztroja is off Meriphataud Mountains.\n• Next: Written in the Stars.' }, { title = 'Reward', note = '• 450 rank points.' } } },
    { name = 'Windurst M3-2: Written in the Stars', group = 'Windurst Missions', desc = 'Zubaba sends you under the central Horutoto Ruins tower to assist the Heavens Tower post guarding the Castle Zvahl seal talisman.', steps = { { title = 'Requirements', note = '• Windurst Rank 3, To Each His Own Right done, rank bar ~1/2.\n• Repeatable; not required for A New Journey.' }, { title = 'Walkthrough', note = '• Accept from a Windurst gate guard.\n• Zubaba (Heavens Tower) gives the Charm of Light.\n• Examine the Gate of Light in Inner Horutoto Ruins; cutscene.\n• Report to Zubaba.' }, { title = 'Tips', note = '• Repeats (or first run after A New Journey): accept, talk to Zubaba, trade 3 Rusty Daggers (dropped by Wendigos in Inner Horutoto Ruins).\n• First clear gives slightly more rank points.\n• Next: A New Journey.' }, { title = 'Reward', note = '• 400 rank points.' } } },
    { name = 'Windurst M3-3: A New Journey', group = 'Windurst Missions', desc = 'The Star Sibyl assigns you to the Windurst Embassy in Jeuno. Completing it grants Rank 4.', steps = { { title = 'Requirements', note = '• Windurst Rank 3, To Each His Own Right done, rank bar ~7/8.' }, { title = 'Walkthrough', note = '• Accept from a gate guard; get the Star Crested Summons.\n• Examine the Vestal Chamber door in Heavens Tower for the Letter to the Ambassador.\n• Talk to Pakh Jatalfih, Windurstian Embassy, Ru\'Lude Gardens.\n• Obtain a Delkfutt Key from Porphyrion (Gigas NM, Upper Delkfutt\'s Tower).\n• Trade it to the Cermet Door in Lower Delkfutt\'s Tower (becomes a key item).\n• Talk to Pakh Jatalfih again, then examine the Embassy door (32, -21).' }, { title = 'Tips', note = '• Already holding the Delkfutt Key key item: just examine the Cermet Door.\n• You keep the key item.\n• Next: Magicite.' }, { title = 'Reward', note = '• Rank 4, 5,000 gil.' } } },
    { name = 'Windurst M4-1: Magicite', group = 'Windurst Missions', desc = 'Seize magicite from Davoi, Beadeaux and Castle Oztroja to stop the Shadow Lord\'s return. Grants Rank 5.', steps = { { title = 'Requirements', note = '• Windurst Rank 4, A New Journey done, rank bar ~1/2. Accepted at the Jeuno embassy, not from gate guards.' }, { title = 'Walkthrough', note = '• Ru\'Lude Gardens: examine the Windurstian Embassy door (32, -21) to accept.\n• Examine the Audience Chamber door; cutscene.\n• Deliver the letter to Aldo in Lower Jeuno.\n• Davoi: trade Coeurl Meat to Baudin (Upper Jeuno) for Crest of Davoi.\n• Beadeaux: talk to Sattal-Mansal (Lower Jeuno), trade Quadav Charm (Mysteries of Beadeaux I), then Qdv. Augury Shell (Mysteries of Beadeaux II).\n• Oztroja: talk to Paya-Sabya (Upper Jeuno), then Muckvix (Lower Jeuno).\n• Davoi: Wall of Dark Arts > Monastic Cavern, examine Magicite.\n• Beadeaux > Qulun Dome: open the Door (60, -7) with bell, rosary, necklace; examine Magicite.\n• Castle Oztroja: use Yagudo Torch on Torch Stand (-97, -109), go to Altar Room, examine Magicite.\n• Examine Audience Chamber door: Airship Pass (or 20,000 gil if owned).\n• Talk to Pakh Jatalfih to finish.' }, { title = 'Tips', note = '• Rank points: crystals to W.W. overseers Harara (Windurst Woods 107, -49), Puroiko-Maiko (Windurst Waters -31, 227), Milma-Hapilma (Port Windurst -227, 209); light/dark crystals worth more.\n• Aldo\'s scene unlocks Baudin, Sattal-Mansal and Paya-Sabya.\n• Quadav Charm / Augury Shell drop from De\'Vyu Headhunter and Go\'Bhu Gascon in Beadeaux.\n• Magicite in any order; party advised for Beadeaux and Oztroja.\n• Keep the Airship Pass for Kazham later.\n• Next: The Final Seal.' }, { title = 'Reward', note = '• Rank 5, 10,000 gil, Airship Pass (key item 71).' } } },
    { name = 'Windurst M5-1: The Final Seal', group = 'Windurst Missions', desc = 'The Star Sibyl sends you to Fei\'Yin on Beaucedine Glacier to check the final seal.', steps = { { title = 'Requirements', note = '• Windurst Rank 5, Magicite done. No rank points needed; starts at Heavens Tower, not gate guards.' }, { title = 'Walkthrough', note = '• Examine the Vestal Chamber door to accept.\n• Enter Fei\'Yin via Beaucedine Glacier; cutscene.\n• Continue to Qu\'Bia Arena; kill Archlich Taber\'quoan in the Burning Circle.\n• Examine the Vestal Chamber door to finish.' }, { title = 'Tips', note = '• 6 players, level cap 50, 15 min.\n• Only the Archlich must die; Ancient Sorcerers assist and Ancient Warriors respawn while he lives, so focus him.\n• Next: The Shadow Awaits.' }, { title = 'Reward', note = '• 600 rank points.' } } },
    { name = 'Windurst M5-2: The Shadow Awaits', group = 'Windurst Missions', desc = 'Fate leads you to Castle Zvahl beyond Xarcabard to face the Shadow Lord. Grants Rank 6.', steps = { { title = 'Requirements', note = '• Windurst Rank 5, The Final Seal done, rank bar ~1/2.' }, { title = 'Walkthrough', note = '• Accept from a gate guard.\n• Examine the Vestal Chamber door; cutscene.\n• Travel Xarcabard > Castle Zvahl Baileys > Castle Zvahl Keep > Throne Room; examine the door (-116, 0).\n• Examine again to fight and defeat the Shadow Lord.\n• Examine the Vestal Chamber door to finish.' }, { title = 'Tips', note = '• 6 players, 30 min, cap 75.\n• Two phases split by a cutscene.\n• Rank points: crystals to W.W. overseers Harara, Puroiko-Maiko or Milma-Hapilma.\n• Victory unlocks Rise of the Zilart (The New Frontier).\n• Next: Full Moon Fountain.' }, { title = 'Reward', note = '• Rank 6, 20,000 gil.' } } },
    { name = 'Windurst M6-1: Full Moon Fountain', group = 'Windurst Missions', desc = 'For the Orastery, activate the magical gizmo in the lab under the southwest Horutoto tower (West Sarutabaruta).', steps = { { title = 'Requirements', note = '• Windurst Rank 6, The Shadow Awaits done, rank bar ~1/3.' }, { title = 'Walkthrough', note = '• Accept from a gate guard.\n• Talk to Hakkuru-Rinkuru at the Orastery (Port Windurst).\n• Outer Horutoto Ruins (from West Sarutabaruta): examine Gate: Magical Gizmo; kill Jack of Batons, Coins, Cups and Swords.\n• Examine the gizmo again; cutscene.\n• Go through Toraimarai Canal to the Full Moon Fountain; arrival cutscene ends it.' }, { title = 'Tips', note = '• Jacks are level 62 (BLM, RDM, WHM, PLD) and spawn together; bring a party.\n• They\'re claimed to the examiner.\n• Rank points: crystals to W.W. overseers.\n• Next: Saintly Invitation.' }, { title = 'Reward', note = '• 650 rank points.' } } },
    { name = 'Windurst M6-2: Saintly Invitation', group = 'Windurst Missions', desc = 'Answer the Yagudo Holy One\'s challenge and win at Balga\'s Dais in Giddeus. Grants Rank 7.', steps = { { title = 'Requirements', note = '• Windurst Rank 6, Full Moon Fountain done, rank bar ~4/5.' }, { title = 'Walkthrough', note = '• Accept from a gate guard.\n• Examine the Vestal Chamber door; cutscene.\n• Win the Burning Circle fight at Balga\'s Dais.\n• Talk to Kaa Toru the Just in Castle Oztroja for an Ashura Necklace.\n• Examine the Vestal Chamber door to finish.' }, { title = 'Tips', note = '• 6 players, 30 min, cap 75.\n• Defeat Buu Xolo the Bloodfaced, Nuu Kofu the Gentle, Juu Zeni the Poisonmist, Chaa Paqa the Profound.\n• Need a free slot for the necklace.\n• Rank points: crystals to W.W. overseers.\n• Next: The Sixth Ministry.' }, { title = 'Reward', note = '• Rank 7, 40,000 gil.' } } },
    { name = 'Windurst M7-1: The Sixth Ministry', group = 'Windurst Missions', desc = 'For the Optistery, find ex-minister Karaha-Baruha\'s lab in Toraimarai Canal and investigate the Book of the Gods.', steps = { { title = 'Requirements', note = '• Windurst Rank 7, Saintly Invitation done, rank bar just under 1/3.' }, { title = 'Walkthrough', note = '• Accept from a gate guard.\n• Talk to Tosuka-Porika, Optistery, Windurst Waters.\n• Toraimarai Canal: kill all four Hinge Oils, then examine the Marble Door while they\'re dead.\n• Examine the Tome of Magic inside; cutscene.\n• Report to Tosuka-Porika.' }, { title = 'Tips', note = '• Hinge Oils: level 65 slimes, ~15 min respawn.\n• Only the map-marked tome of the five works.\n• Canal Transporter returns you to Heavens Tower.\n• Keep the Blank Book of the Gods for the next mission.\n• Next: Awakening of the Gods.' }, { title = 'Reward', note = '• Key item 251 (Blank Book of the Gods), 700 rank points.' } } },
    { name = 'Windurst M7-2: Awakening of the Gods', group = 'Windurst Missions', desc = 'Retrieve Rhinostery minister Rukususu from Elshimo, where she is researching Iru-Kuiru. Grants Rank 8.', steps = { { title = 'Requirements', note = '• Windurst Rank 7, The Sixth Ministry done, holding the Blank Book of the Gods, rank bar ~3/4.' }, { title = 'Walkthrough', note = '• Accept from a gate guard.\n• Talk to Leepe-Hoppe (Rhinostery roof, Windurst Waters), then Kerutoto.\n• Talk to Romaa Mihgo in Kazham.\n• Kill Bonze Marberry (Tonberry NM, Temple of Uggalepih) for a Cursed Key.\n• Trade the key to the Granite Door; cutscene.\n• Report to Leepe-Hoppe.' }, { title = 'Tips', note = '• Kazham airship leaves Port Jeuno; requires the Airship Pass.\n• Vanono\'s Kazham scene is optional.\n• Temple entrance is in Yhoator Jungle; the Granite Door accepts the key from one side only.\n• Keep the Book of the Gods for The Jester Who\'d Be King.\n• Rank points: crystals to W.W. overseers.\n• Next: Vain.' }, { title = 'Reward', note = '• Rank 8, 60,000 gil.' } } },
    { name = 'Windurst M8-1: Vain', group = 'Windurst Missions', desc = 'For the Aurastery, track down its former minister who abandoned his post years ago.', steps = { { title = 'Requirements', note = '• Windurst Rank 8, Awakening of the Gods done, rank bar just over 1/4.' }, { title = 'Walkthrough', note = '• Accept from a gate guard.\n• Talk to Moreno-Toeno, Aurastery, Windurst Waters.\n• Reach Ro\'Maeve via The Sanctuary of Zi\'Tah; examine the Qu\'Hau Spring.\n• Talk to Sedal-Godjal in Davoi (wants a Curse Wand).\n• Kill Dirtyhanded Gochakzuk (Orc NM, Davoi) for the Curse Wand and trade it to Sedal-Godjal.\n• Report to Moreno-Toeno.' }, { title = 'Tips', note = '• Holding the Star Seeker, zoning into most outdoor areas shows a direction hint.\n• Ro\'Maeve Moongates: open with a Moongate Pass from a ??? in Ro\'Maeve, or freely 00:00-03:00 on a full moon.\n• Gochakzuk is level 71.\n• Rank points: crystals to W.W. overseers.\n• Next: The Jester Who\'d Be King.' }, { title = 'Reward', note = '• 750 rank points.' } } },
    { name = 'Windurst M8-2: The Jester Who\'d Be King', group = 'Windurst Missions', desc = 'For the Manustery\'s Dark Dungeon jailbreak, gather the rings of all five ministers. Grants Rank 9.', steps = { { title = 'Requirements', note = '• Windurst Rank 8, Vain done, holding the Book of the Gods, rank bar ~3/4.' }, { title = 'Walkthrough', note = '• Accept from a gate guard.\n• Talk to Apururu, Manustery, Windurst Woods.\n• Talk to Tosuka-Porika (Optistery).\n• Talk to Sedal-Godjal in Davoi.\n• Examine the Cermet Door in Fei\'Yin.\n• Report to Apururu, then Kupipi.\n• Outer Horutoto Ruins: examine Cracked Wall, kill Queen of Coins and Queen of Swords, examine again.\n• Talk to Apururu, then Shantotto (Windurst Walls), then Apururu.\n• Examine the Gate of Darkness in Inner Horutoto Ruins.\n• Report to Apururu.' }, { title = 'Tips', note = '• Optistery, Aurastery, Rhinostery rings: any order.\n• Queens: level 72 RDM and PLD; full party.\n• Shantotto has an extra post-mission scene.\n• Rank points: crystals to W.W. overseers.\n• Next: Doll of the Dead.' }, { title = 'Reward', note = '• Rank 9, 80,000 gil.' } } },
    { name = 'Windurst M9-1: Doll of the Dead', group = 'Windurst Missions', desc = 'With the Bearer of Darkness menacing Heavens Tower, the Manustery sends you to a prisoner in the Boyahda Tree to learn about the doll of the dead.', steps = { { title = 'Requirements', note = '• Windurst Rank 9, The Jester Who\'d Be King done, rank bar just over 1/3.' }, { title = 'Walkthrough', note = '• Accept from a gate guard.\n• Talk to Apururu (Manustery).\n• Enter Heavens Tower (cutscene), examine the Vestal Chamber door.\n• Talk to Apururu again.\n• Get Goobbue Humus from Old Goobbues (Boyahda Tree) or Goobbue Gardeners (Sanctuary of Zi\'Tah).\n• Trade it to the Mandragora Warden in The Boyahda Tree.\n• Give the letter to Apururu.\n• Go through Toraimarai Canal to the Full Moon Fountain to finish.' }, { title = 'Tips', note = '• Yoran-Oran (Windurst Walls) gives an optional humus hint.\n• Warden accepts only after the second Apururu talk.\n• Gardeners are level 40-43, easier than Old Goobbues.\n• Rank points: crystals to W.W. overseers.\n• Next: Moon Reading.' }, { title = 'Reward', note = '• Title Guiding Star, 800 rank points.' } } },
    { name = 'Windurst M9-2: Moon Reading', group = 'Windurst Missions', desc = 'Final Windurst mission: collect three ancient verses to draw the Bearer of Darkness to the Full Moon Fountain. Grants Rank 10.', steps = { { title = 'Requirements', note = '• Windurst Rank 9, Doll of the Dead done, rank bar nearly full.' }, { title = 'Walkthrough', note = '• Accept from a gate guard.\n• Examine the Vestal Chamber door.\n• Ro\'Maeve: examine the Qu\'Hau Spring.\n• Temple of Uggalepih: examine the ???.\n• Enter the Chamber of Oracles from Quicksand Caves.\n• With all verses, examine the Vestal Chamber door.\n• Toraimarai Canal > Full Moon Fountain: enter the Moon Spiral and win.\n• Examine the Vestal Chamber door twice; final scene in Windurst Walls.' }, { title = 'Tips', note = '• Verses in any order.\n• Fight: 6 players, 30 min, cap 75. Phase 1: Ace of Cups, Batons, Swords, Coins. Phase 2: Tatzlwurm and Yali with an NPC ally; kill both.\n• Keep a slot free for the flag.\n• Ro\'Maeve Moongates: Moongate Pass from a ??? there, or open 00:00-03:00 on full moon.\n• Rank points: crystals to W.W. overseers.' }, { title = 'Reward', note = '• Rank 10, 100,000 gil, Windurstian Flag, title Vestal Chamberlain.' } } },
    { name = 'Zilart M1: The New Frontier', group = 'Rise of the Zilart Missions', desc = 'Opening Rise of the Zilart mission, begun in Norg, a hidden Elshimo Lowlands port.', steps = { { title = 'Requirements', note = '• Granted on winning your nation\'s 5-2 fight (The Shadow Lord, Xarcabard, Land of Truths or The Shadow Awaits); active once 5-2 is done and you\'re rank 6.' }, { title = 'Walkthrough', note = '• Reach Norg via Sea Serpent Grotto, entered from Yuhtunga Jungle.\n• On arrival choose to watch the story; you get the Map of Norg and complete it.' }, { title = 'Tips', note = '• Choosing later spawns a Tales\' Beginning in Norg to examine.\n• Next: Welcome t\'Norg.' }, { title = 'Reward', note = '• Key item 417 (Map of Norg).' } } },
    { name = 'Zilart M2: Welcome t\'Norg', group = 'Rise of the Zilart Missions', desc = 'Lion wants you to meet someone in the room at the end of Norg\'s second-floor hallway. No combat.', steps = { { title = 'Walkthrough', note = '• Follows The New Frontier.\n• In Norg, examine the Oaken Door at the end of the upstairs hall; cutscene completes it.' }, { title = 'Tips', note = '• Many later missions begin or end at this door.' } } },
    { name = 'Zilart M3: Kazham\'s Chieftainess', group = 'Rise of the Zilart Missions', desc = 'Meet Kazham\'s chieftainess Jakoh Wahcondalo before heading to the Temple of Uggalepih. No combat.', steps = { { title = 'Walkthrough', note = '• Follows Welcome t\'Norg.\n• Go to Kazham (edge of Yuhtunga Jungle).\n• Talk to Jakoh Wahcondalo for the Sacrificial Chamber Key.' }, { title = 'Tips', note = '• Gilgamesh behind the Oaken Door in Norg comments on most missions; optional.' }, { title = 'Reward', note = '• Key item 238 (Sacrificial Chamber Key).' } } },
    { name = 'Zilart M4: The Temple of Uggalepih', group = 'Rise of the Zilart Missions', desc = 'Gilgamesh sends you to the Temple of Uggalepih to find an old hermit, ending in the Sacrificial Chamber.', steps = { { title = 'Walkthrough', note = '• Follows Kazham\'s Chieftainess.\n• Through the Temple of Uggalepih (from Yhoator Jungle) reach To the Sacrificial Chamber (-230, 67); the Den of Rancor also connects.\n• Examine the Mahogany Door and enter.\n• Kill Grav\'iton, Molybiton and Tungsiton.\n• Post-fight cutscenes complete it.' }, { title = 'Tips', note = '• 6 players, 30 min, cap 75; tonberries are level 63-65.\n• Adds join, but only the three tonberries must die.\n• Gilgamesh (Norg) and Jakoh Wahcondalo (Kazham) dialogue is optional.' }, { title = 'Reward', note = '• Dark Fragment (key item 246), title Bearer of the Wisewoman\'s Hope.' } } },
    { name = 'Zilart M5: Headstone Pilgrimage', group = 'Rise of the Zilart Missions', desc = 'Gather the seven elemental fragments from Cermet Headstones across Vana\'diel; four are guarded by level 65-68 NMs.', steps = { { title = 'Headstones', note = '• After The Temple of Uggalepih; you already hold the Dark Fragment; any order.\n• Water: La Theine Plateau (-173, -508).\n• Earth: Western Altepa Desert (-112, -220).\n• Ice: Cloister of Frost via Fei\'Yin (568, 608).\n• Fire: Yuhtunga Jungle (494, 303), kill Tipha and Carthi, examine again.\n• Wind: Cape Teriggan (-110, 454), kill Axesarion the Wanderer, examine again.\n• Lightning: Behemoth\'s Dominion (-75, -90), kill Ancient Weapon and Legendary Weapon, examine again.\n• Light: The Sanctuary of Zi\'Tah (232, 280), kill the Doomed Pilgrims, examine again.' }, { title = 'Tips', note = '• Be adjacent to the headstone when accepting.\n• Shortly after a guardian kill, anyone on the mission can take that fragment without fighting.\n• A \'something better to do\' prompt means its guardians are in another group\'s fight; wait.\n• Fire, Wind and Light fragments start Wrath of the Opo-opos, Wandering Souls and Soul Searching.' }, { title = 'Reward', note = '• Title: Bearer of the Eight Prayers' } } },
    { name = 'Zilart M6: Through the Quicksand Caves', group = 'Rise of the Zilart Missions', desc = 'Reach the Chamber of Oracles through the Quicksand Caves and beat three Antica (level 68-70).', steps = { { title = 'Steps', note = '• Enter Quicksand Caves from Western or Eastern Altepa Desert; go to To the Chamber of Oracles (-980, -278).\n• Examine the Shimmering Circle near the entrance.\n• Defeat Centurio V-III, Triarius V-VIII and Princeps V-XI to finish.' }, { title = 'Tips', note = '• 6 players, 30 min, level cap 75.\n• Second entrance To the pedestals (-900, -241) is used next mission.\n• Gilgamesh in Norg has optional dialogue.' } } },
    { name = 'Zilart M7: The Chamber of Oracles', group = 'Rise of the Zilart Missions', desc = 'Place all eight fragments on the elemental pedestals in the Chamber of Oracles; no combat.', steps = { { title = 'Steps', note = '• Enter via To the pedestals (-900, -241).\n• Examine the eight Pedestals (200, 45) in any order: Fire, Ice, Wind, Earth, Lightning, Water, Light, Darkness.\n• After the eighth, a cutscene grants the Prismatic Fragment and title Lightweaver.' }, { title = 'Tips', note = '• Examine any pedestal to replay an interrupted cutscene.\n• The eight fragments are consumed.' }, { title = 'Reward', note = '• Key item: key item 247\n• Title: Lightweaver' } } },
    { name = 'Zilart M8: Return to Delkfutt\'s Tower', group = 'Rise of the Zilart Missions', desc = 'Climb Delkfutt\'s Tower to the Stellar Fulcrum and defeat Kamlanaut (level 75).', steps = { { title = 'Steps', note = '• Go to Delkfutt\'s Tower on Qufim Island (possible cutscene in Lower Delkfutt\'s Tower).\n• On floor 12 of Upper Delkfutt\'s Tower, use Porter to the Stellar Fulcrum (-367, -46).\n• Watch the cutscene, examine the Qe\'Lov Gate and enter.\n• Defeat Kamlanaut to finish.' }, { title = 'Tips', note = '• 6 players, 30 min, level cap 75; win also gives title Destroyer of Antiquity.\n• Gilgamesh (Norg) and Aldo (Lower Jeuno) are optional.' } } },
    { name = 'Zilart M9: Ro\'Maeve', group = 'Rise of the Zilart Missions', desc = 'Return to Norg after the tower; no combat.', steps = { { title = 'Steps', note = '• Examine the Oaken Door in Norg to finish.\n• Optional extra cutscene from Aldo in Lower Jeuno.' } } },
    { name = 'Zilart M10: The Temple of Desolation', group = 'Rise of the Zilart Missions', desc = 'Cross Ro\'Maeve via the Sanctuary of Zi\'Tah into the Hall of the Gods; no mission battle.', steps = { { title = 'Steps', note = '• Go through the Sanctuary of Zi\'Tah into Ro\'Maeve.\n• Continue to the Hall of the Gods on Ro\'Maeve\'s far side.\n• Examine the Cermet Grate to finish.' }, { title = 'Tips', note = '• Ro\'Maeve\'s path opens alone only on full-moon nights, 18:00-6:00 Vana\'diel time; otherwise use the Moongate Pass key item from a roaming ??? in Ro\'Maeve.\n• Gilgamesh and Kamui in Norg give optional advice.' }, { title = 'Reward', note = '• Title: Sealer of the Portal of the Gods' } } },
    { name = 'Zilart M11: The Hall of the Gods', group = 'Rise of the Zilart Missions', desc = 'Report the blocked Cermet Grate in Norg; no combat.', steps = { { title = 'Steps', note = '• Examine the Oaken Door in Norg to finish.\n• Re-examining the Cermet Grate does nothing more yet.' } } },
    { name = 'Zilart M12: The Mithra and the Crystal', group = 'Rise of the Zilart Missions', desc = 'Find Maryoh Comyujah and get the Cerulean Crystal; one fight vs Ancient Vessel (level 72).', steps = { { title = 'Steps', note = '• Talk to Maryoh Comyujah in Rabao and agree to help (talk again if you refused).\n• In the Quicksand Caves, examine the ??? and defeat Ancient Vessel.\n• Examine the ??? again for a Scrap of Papyrus.\n• Give it to Maryoh Comyujah for the Cerulean Crystal.\n• Go to the Hall of the Gods; examine the Cermet Grate, followed by the Shimmering Circle, to finish.' }, { title = 'Tips', note = '• Stand adjacent to the ???.\n• Party/alliance members in zone who accepted share the kill; each examines the ??? before zoning.\n• \'Faint traces of magic\' means a recent kill; wait and retry.\n• Gilgamesh (Norg) and Aldo (Lower Jeuno) are optional.' } } },
    { name = 'Zilart M13: The Gate of the Gods', group = 'Rise of the Zilart Missions', desc = 'Go past the Cermet Grate up to Ru\'Aun Gardens; no combat.', steps = { { title = 'Steps', note = '• In the Hall of the Gods, pass the Cermet Grate and examine the Shimmering Circle to go up.\n• Continue to Ru\'Aun Gardens; the arrival cutscene finishes it.\n• The upper Shimmering Circle takes you back down.' } } },
    { name = 'Zilart M14: Ark Angels', group = 'Rise of the Zilart Missions', desc = 'Beat five level 75 Ark Angels in the Shrine of Ru\'Avitau for five shards.', steps = { { title = 'Start', note = '• Enter the Shrine of Ru\'Avitau via the Ru\'Avitau Gate in Ru\'Aun Gardens; examine Start of the trial (-40, -148).' }, { title = 'Battles', note = '• Ark Angel HM (-605, 484): Shard of Apathy.\n• Ark Angel TT (-265, 375): Shard of Cowardice.\n• Ark Angel MR (14, 488): Shard of Envy.\n• Ark Angel EV (236, 361): Shard of Arrogance.\n• Ark Angel GK (556, 521): Shard of Rage.\n• The fifth shard finishes the mission.' }, { title = 'Tips', note = '• Any order; 6 players, 30 min, level cap 75 each.\n• Each circle has its own passage from Ru\'Aun Gardens.\n• MR may add a tiger and mandragora, GK a wyvern; only the Ark Angel must die.\n• Holding a shard bars re-entry to that fight.\n• Quest Divine Might (18 players, all five) grants every shard if done on this mission.' } } },
    { name = 'Zilart M15: The Sealed Shrine', group = 'Rise of the Zilart Missions', desc = 'Discuss the sealed door in Norg, then return to the Shrine of Ru\'Avitau; no combat.', steps = { { title = 'Steps', note = '• Examine the Oaken Door in Norg.\n• Enter the Shrine of Ru\'Avitau via the Ru\'Avitau Gate in Ru\'Aun Gardens; arrival cutscene finishes it.\n• Optional: Aldo (Lower Jeuno), Gilgamesh (Norg).' } } },
    { name = 'Zilart M16: The Celestial Nexus', group = 'Rise of the Zilart Missions', desc = 'Final battle vs Eald\'narche (level 78) in the Celestial Nexus.', steps = { { title = 'Steps', note = '• Go through the Shrine of Ru\'Avitau to To the Celestial Nexus (0, 60).\n• Examine the Celestial Gate and enter.\n• Defeat Eald\'narche and his Exoplates, then defeat him again in round two; you end in the Hall of the Gods.' }, { title = 'Tips', note = '• 6 players, level cap 75, 30 min covering both rounds.\n• Gilgamesh in Norg is optional.' }, { title = 'Reward', note = '• Title: Burier of the Illusion' } } },
    { name = 'Zilart M17: Awakening', group = 'Rise of the Zilart Missions', desc = 'Epilogue that stays open until Chains of Promathia and three Jeuno quests are done.', steps = { { title = 'Steps', note = '• Enter Norg for a cutscene.\n• Examine the Neptune\'s Spire door in Lower Jeuno.\n• Finish Chains of Promathia through Dawn.\n• Complete Storms of Fate, Shadows of the Departed, then Apocalypse Nigh.\n• Choosing the Apocalypse Nigh reward from Gilgamesh in Norg finishes Awakening.' }, { title = 'Tips', note = '• Shadows of the Departed needs both early cutscenes seen.\n• Free inventory space before claiming the reward.' } } },
    { name = 'Aht Urhgan Mission 1: Land of Sacred Serpents', group = 'Treasures of Aht Urhgan Missions', desc = 'Opening Treasures of Aht Urhgan mission; travel east to Aht Urhgan.', steps = { { title = 'Details', note = '• Needs key item: Boarding Permit.\n• Reward: key item 775.' } } },
    { name = 'Aht Urhgan Mission 2: Immortal Sentries', group = 'Treasures of Aht Urhgan Missions', desc = 'Bring a package to an Immortal at a staging point to earn a mercenary contract.', steps = { { title = 'Details', note = '• Needs key item: Supplies Package.\n• NPCs: Daswil (Bhaflau Thickets), Meyaada (Arrapago Reef), Nahshib and Nareema (Caedarva Mire), Waudeen (Mount Zhayolm), Naja Salaheem (Aht Urhgan Whitegate).\n• Reward: key item 780; title Private Second Class.' } } },
    { name = 'Aht Urhgan Mission 3: President Salaheem', group = 'Treasures of Aht Urhgan Missions', desc = 'You start work at Salaheem\'s Sentinels.', steps = { { title = 'Details', note = '• NPC: Naja Salaheem (Aht Urhgan Whitegate).' } } },
    { name = 'Aht Urhgan Mission 4: Knight of Gold', group = 'Treasures of Aht Urhgan Missions', desc = 'Return Raillefal to Salaheem\'s Sentinels.', steps = { { title = 'Details', note = '• Trade: 1000 gil, Imp. Brz. Piece.\n• Locations: Cacaroon, Walahra Temple, Teahouse (all Aht Urhgan Whitegate).\n• Reward: key item 785.' } } },
    { name = 'Aht Urhgan Mission 5: Confessions of Royalty', group = 'Treasures of Aht Urhgan Missions', desc = 'Take Raillefal\'s letter to Halver.', steps = { { title = 'Details', note = '• Needs key item: Raillefals Letter.\n• NPC: Halver (Chateau d\'Oraguille).' } } },
    { name = 'Aht Urhgan Mission 6: Easterly Winds', group = 'Treasures of Aht Urhgan Missions', desc = 'Speak at the summit in Jeuno about the Empire.', steps = { { title = 'Details', note = '• NPC: Halver (Chateau d\'Oraguille).' } } },
    { name = 'Aht Urhgan Mission 7: Westerly Winds', group = 'Treasures of Aht Urhgan Missions', desc = 'Act as an allied agent inside the Empire; report to Raillefal.', steps = { { title = 'Details', note = '• Key item received: Raillefals Note.\n• NPC: Naja Salaheem (Aht Urhgan Whitegate).\n• Reward: Imp. Slv. Piece.' } } },
    { name = 'Aht Urhgan Mission 8: A Mercenary Life', group = 'Treasures of Aht Urhgan Missions', desc = 'Naja wants more missions done.', steps = {  } },
    { name = 'Aht Urhgan Mission 9: Undersea Scouting', group = 'Treasures of Aht Urhgan Missions', desc = 'Patrol the Alzadaal Undersea Ruins, entered from Bhaflau Thickets.', steps = { { title = 'Details', note = '• NPC: Naja Salaheem (Aht Urhgan Whitegate).\n• Reward: key item 812.' } } },
    { name = 'Aht Urhgan Mission 10: Astral Waves', group = 'Treasures of Aht Urhgan Missions', desc = 'Report to Salaheem\'s Sentinels with Ghatsad\'s astral wave detector.', steps = { { title = 'Details', note = '• NPC: Naja Salaheem (Aht Urhgan Whitegate).' } } },
    { name = 'Aht Urhgan Mission 11: Imperial Schemes', group = 'Treasures of Aht Urhgan Missions', desc = 'Naja takes the A.A.R.I. reward as fines.', steps = { { title = 'Details', note = '• NPC: Naja Salaheem (Aht Urhgan Whitegate).' } } },
    { name = 'Aht Urhgan Mission 12: Royal Puppeteer', group = 'Treasures of Aht Urhgan Missions', desc = 'Investigate the Ashu Talif ghost ship in the Arrapago Islands for the court puppetmaster.', steps = { { title = 'Details', note = '• Trade: Jody\'s Acid.\n• NPCs: Naja Salaheem (Aht Urhgan Whitegate), Pyopyoroon (Nashmau).\n• Reward: key item 813.' } } },
    { name = 'Aht Urhgan Mission 13: Lost Kingdom', group = 'Treasures of Aht Urhgan Missions', desc = 'Follow Pyopyoroon\'s hint west to find a ghost.', steps = { { title = 'Details', note = '• Needs key item: Vial of Spectral Scent.\n• Fight: Jazaraat.\n• NPCs: Pyopyoroon (Nashmau), Jazaraat\'s Headstone (Caedarva Mire).\n• Reward: key item 786.' } } },
    { name = 'Aht Urhgan Mission 14: The Dolphin Crest', group = 'Treasures of Aht Urhgan Missions', desc = 'Report the Azouph Isle ghost and crest coin to Naja.', steps = { { title = 'Details', note = '• NPC: Naja Salaheem (Aht Urhgan Whitegate).' } } },
    { name = 'Aht Urhgan Mission 15: The Black Coffin', group = 'Treasures of Aht Urhgan Missions', desc = 'Investigate a presence west of Dvucca Isle.', steps = { { title = 'Details', note = '• NPC: Naja Salaheem (Aht Urhgan Whitegate).' } } },
    { name = 'Aht Urhgan Mission 16: Ghosts of the Past', group = 'Treasures of Aht Urhgan Missions', desc = 'Report the Ashu Talif findings to Naja.', steps = { { title = 'Details', note = '• NPC: Naja Salaheem (Aht Urhgan Whitegate).' } } },
    { name = 'Aht Urhgan Mission 17: Guests of the Empire', group = 'Treasures of Aht Urhgan Missions', desc = 'Get proper attire through Naja and attend the Grand Vizier\'s palace invitation.', steps = { { title = 'Details', note = '• NPCs: Naja Salaheem, Imperial Whitegate (Aht Urhgan Whitegate).\n• Reward: Imp. Mtl. Piece; title Ovjang\'s Errand Runner.' } } },
    { name = 'Aht Urhgan Mission 18: Passing Glory', group = 'Treasures of Aht Urhgan Missions', desc = 'Naja holds the Empress\'s reward until you earn it.', steps = { { title = 'Details', note = '• NPC: Naja Salaheem (Aht Urhgan Whitegate).' } } },
    { name = 'Aht Urhgan Mission 19: Sweets for the Soul', group = 'Treasures of Aht Urhgan Missions', desc = 'Ambassador Karababa of Windurst visits and heads to the Shararat Teahouse.', steps = { { title = 'Details', note = '• Reward: title Karababa\'s Tour Guide.' } } },
    { name = 'Aht Urhgan Mission 20: Teahouse Tumult', group = 'Treasures of Aht Urhgan Missions', desc = 'Guide Lady Karababa to the Olduum ruins in the Aydeewa Subterrane.', steps = {  } },
    { name = 'Aht Urhgan Mission 21: Finders Keepers', group = 'Treasures of Aht Urhgan Missions', desc = 'Karababa takes the Olduum artifact to Salaheem\'s Sentinels.', steps = { { title = 'Details', note = '• NPC: Naja Salaheem (Aht Urhgan Whitegate).' } } },
    { name = 'Aht Urhgan Mission 22: Shield of Diplomacy', group = 'Treasures of Aht Urhgan Missions', desc = 'Guard Karababa in the Navukgo Execution Chamber.', steps = { { title = 'Details', note = '• Battlefield: Shield of Diplomacy.\n• NPC: Decorative Bronze Gate (Navukgo Execution Chamber).\n• Reward: title Karababa\'s Bodyguard.' } } },
    { name = 'Aht Urhgan Mission 23: Social Graces', group = 'Treasures of Aht Urhgan Missions', desc = 'Return to Salaheem\'s Sentinels after protecting Karababa.', steps = {  } },
    { name = 'Aht Urhgan Mission 24: Foiled Ambition', group = 'Treasures of Aht Urhgan Missions', desc = 'Caught between Karababa and Naja.', steps = { { title = 'Details', note = '• Reward: 5 × Imp. Gold Piece; title Karababa\'s Secret Agent.' } } },
    { name = 'Aht Urhgan Mission 25: Playing the Part', group = 'Treasures of Aht Urhgan Missions', desc = 'Keep building palace standing and look into the Astral Candescence.', steps = { { title = 'Details', note = '• NPC: Naja Salaheem (Aht Urhgan Whitegate).' } } },
    { name = 'Aht Urhgan Mission 26: Seal of the Serpent', group = 'Treasures of Aht Urhgan Missions', desc = 'Answer the Grand Vizier\'s summons; weapons must be removed before entering.', steps = { { title = 'Details', note = '• NPC: Imperial Whitegate (Aht Urhgan Whitegate).' } } },
    { name = 'Aht Urhgan Mission 27: Misplaced Nobility', group = 'Treasures of Aht Urhgan Missions', desc = 'Search for Aphmau, starting with the Immortal Rishfee in the Aydeewa Subterrane.', steps = {  } },
    { name = 'Aht Urhgan Mission 28: Bastion of Knowledge', group = 'Treasures of Aht Urhgan Missions', desc = 'Look for Aphmau at Walahra Temple in the capital.', steps = { { title = 'Details', note = '• Reward: title Aphmau\'s Mercenary.' } } },
    { name = 'Aht Urhgan Mission 29: Puppet in Peril', group = 'Treasures of Aht Urhgan Missions', desc = 'Escort Aphmau to Mamook to recover Ovjang.', steps = { { title = 'Details', note = '• Battlefield: Puppet in Peril.\n• NPC: Ornamental Door (Jade Sepulcher).' } } },
    { name = 'Aht Urhgan Mission 30: Prevalence of Pirates', group = 'Treasures of Aht Urhgan Missions', desc = 'Pursue Luzaf, who has taken Aphmau and her puppets.', steps = { { title = 'Details', note = '• Reward: key item 860.' } } },
    { name = 'Aht Urhgan Mission 31: Shades of Vengeance', group = 'Treasures of Aht Urhgan Missions', desc = 'Join Amnaf\'s search for Aphmau, beginning in Periqia.', steps = { { title = 'Details', note = '• Key item received: Periqia Assault Area Entry Permit.\n• NPC: Nahshib (Caedarva Mire).\n• Reward: title Nashmeira\'s Mercenary.' } } },
    { name = 'Aht Urhgan Mission 32: In the Blood', group = 'Treasures of Aht Urhgan Missions', desc = 'Report mission completion to Naja in Al Zahbi.', steps = { { title = 'Details', note = '• NPC: Naja Salaheem (Aht Urhgan Whitegate).\n• Reward: Imp. Gold Piece.' } } },
    { name = 'Aht Urhgan Mission 33: Sentinels\' Honor', group = 'Treasures of Aht Urhgan Missions', desc = 'Naja pursues the bounty on Duzaf the Blackbelly.', steps = { { title = 'Details', note = '• NPC: Naja Salaheem (Aht Urhgan Whitegate).' } } },
    { name = 'Aht Urhgan Mission 34: Testing the Waters', group = 'Treasures of Aht Urhgan Missions', desc = 'Revisit the Black Coffin to check whether the target is Luzaf.', steps = { { title = 'Details', note = '• Needs key item: Ephramadian Gold Coin.\n• Reward: key item 877; title Treasure Trove Tender.' } } },
    { name = 'Aht Urhgan Mission 35: Legacy of the Lost', group = 'Treasures of Aht Urhgan Missions', desc = 'Locate the hidden Ephramad treasury in Talacca Cove and guard it.', steps = { { title = 'Details', note = '• Battlefield: Legacy of the Lost.\n• Reward: title Gessho\'s Mercy.' } } },
    { name = 'Aht Urhgan Mission 36: Gaze of the Saboteur', group = 'Treasures of Aht Urhgan Missions', desc = 'Protect Nashmeira from Flit at the Hazhalm Testing Grounds.', steps = { { title = 'Details', note = '• Needs key item: Percipient Eye.\n• NPC: Entry Gate (Hazhalm Testing Grounds).\n• Reward: key item 893; title Emissary of the Empress.' } } },
    { name = 'Aht Urhgan Mission 37: Path of Blood', group = 'Treasures of Aht Urhgan Missions', desc = 'Deliver Nashmeira\'s message to Naja.', steps = {  } },
    { name = 'Aht Urhgan Mission 38: Stirrings of War', group = 'Treasures of Aht Urhgan Missions', desc = 'Learn of an upcoming allied military council.', steps = { { title = 'Details', note = '• Reward: key item 897.' } } },
    { name = 'Aht Urhgan Mission 39: Allied Rumblings', group = 'Treasures of Aht Urhgan Missions', desc = 'Report on the Empire at the Allied Military Council in the Grand Duke Palace.', steps = {  } },
    { name = 'Aht Urhgan Mission 40: Unraveling Reason', group = 'Treasures of Aht Urhgan Missions', desc = 'Join the Wajaom Infiltration Operation by airship.', steps = { { title = 'Details', note = '• NPC: Pherimociel (Ru\'Lude Gardens).\n• Reward: title Endymion Paratrooper.' } } },
    { name = 'Aht Urhgan Mission 41: Light of Judgment', group = 'Treasures of Aht Urhgan Missions', desc = 'After the Endymion is downed, meet Rodin-Comidin in Aht Urhgan Whitegate.', steps = { { title = 'Details', note = '• NPC: Rodin-Comidin (Aht Urhgan Whitegate).\n• Reward: key item 898.' } } },
    { name = 'Aht Urhgan Mission 42: Path of Darkness', group = 'Treasures of Aht Urhgan Missions', desc = 'Use Rodin-Comidin\'s map to cross Nyzul Isle and rescue Luzaf.', steps = { { title = 'Details', note = '• Key item received: Nyzul Isle Route.\n• NPCs: Rodin-Comidin, Door (Aht Urhgan Whitegate).\n• Reward: title Naja\'s Comrade-In-Arms.' } } },
    { name = 'Aht Urhgan Mission 43: Fangs of the Lion', group = 'Treasures of Aht Urhgan Missions', desc = 'Regroup with Naja after the failed rescue.', steps = { { title = 'Details', note = '• Reward: key item 899; title Nashmeira\'s Loyalist.' } } },
    { name = 'Aht Urhgan Mission 44: Nashmeira\'s Plea', group = 'Treasures of Aht Urhgan Missions', desc = 'Escort Nashmeira to Nyzul Isle to confront Razfahd.', steps = { { title = 'Details', note = '• Key item received: Mythril Mirror.\n• NPC: Naja Salaheem (Aht Urhgan Whitegate).\n• Reward: title Preventer of Ragnarok.' } } },
    { name = 'Aht Urhgan Mission 45: Ragnarok', group = 'Treasures of Aht Urhgan Missions', desc = 'Report to Naja in Al Zahbi after Ragnarok is stopped.', steps = {  } },
    { name = 'Aht Urhgan Mission 46: Imperial Coronation', group = 'Treasures of Aht Urhgan Missions', desc = 'Dress properly and accompany Naja to the coronation at the palace.', steps = {  } },
    { name = 'Aht Urhgan Mission 47: The Empress Crowned', group = 'Treasures of Aht Urhgan Missions', desc = 'Crown Empress Nashmeira II.', steps = { { title = 'Details', note = '• Reward: Glory Crown; title Eternal Mercenary.' } } },
    { name = 'Aht Urhgan Mission 48 (Last): Eternal Mercenary', group = 'Treasures of Aht Urhgan Missions', desc = 'Final mission; the Glory Crown is returned but repayments to Naja continue.', steps = {  } },
    { name = 'Promathia 1-1: The Rites of Life', group = 'Chains of Promathia Missions', desc = 'Opening Chains of Promathia mission; no level, rank or prior mission needed, only access to Qufim Island.', steps = { { title = 'Steps', note = '• Enter Lower Delkfutt\'s Tower from Qufim Island for the opening cutscene.\n• Enter Upper Jeuno (any route) for a cutscene.\n• Talk to Monberaux in the Upper Jeuno infirmary; receive the Mysterious Amulet.' }, { title = 'Tips', note = '• If the mission didn\'t start, examine Tales\' Beginning near the entrance.\n• CoP missions have their own log alongside nation missions.\n• Next: Below the Arks in Ru\'Lude Gardens.' }, { title = 'Reward', note = '• Key item: key item 579' } } },
    { name = 'Promathia 1-2: Below the Arks', group = 'Chains of Promathia Missions', desc = 'Hear the news in Ru\'Lude Gardens, then clear one Promyvion (level cap 30).', steps = { { title = 'Steps', note = '• Talk to Pherimociel in Ru\'Lude Gardens.\n• Touch a Shattered Telepoint: La Theine Plateau (Holla), Konschtat Highlands (Dem) or Tahrongi Canyon (Mea).\n• In the Hall of Transference, examine that section\'s Large Apparatus.\n• Descend the floors to the Spire.\n• Examine the Web of Recollections for Ancient Flames Beckon; beat Wreaker (Holla), Progenerator (Dem) or Delver (Mea) for that Promyvion\'s Light key item.' }, { title = 'Tips', note = '• Killing Memory Receptacles may open a memory stream to the next floor for 3 min; not every one does. They summon Strays.\n• Fight: 6 players, level cap 30, 30 min; Trusts allowed; previous clearers may join.\n• Bosses can\'t be slept; TP gain spikes under about 1/3 HP. In Dem only Progenerator must die.\n• Leaving resets to floor 1. To switch Promyvion, touch another telepoint, seal off the first\'s memories, then touch again.\n• This clear counts toward The Mothercrystals.' } } },
    { name = 'Promathia 1-3: The Mothercrystals', group = 'Chains of Promathia Missions', desc = 'Clear the remaining two Promyvions (level cap 30, 6 players per Spire).', steps = { { title = 'Steps', note = '• Holla: La Theine Plateau telepoint, beat Wreaker in the Spire of Holla.\n• Dem: Konschtat Highlands telepoint, beat Progenerator in the Spire of Dem.\n• Mea: Tahrongi Canyon telepoint, beat Delver in the Spire of Mea.\n• The third Spire win sends you to Lufaise Meadows and completes the mission.' }, { title = 'Tips', note = '• The one from Below the Arks already counts; others in any order.\n• Second telepoint goes straight in; the last routes through the Hall of Transference first.\n• Spire wins return you to the telepoint except the last; prepare before it (An Invitation West starts in Lufaise Meadows).' }, { title = 'Reward', note = '• Title: Ancient Flame Follower' } } },
    { name = 'Promathia 2-1: An Invitation West', group = 'Chains of Promathia Missions', desc = 'Wake in Lufaise Meadows and reach the Tavnazian Safehold.', steps = { { title = 'Steps', note = '• Watch the Lufaise Meadows arrival cutscene.\n• Enter the Tavnazian Safehold via either entrance (To Tavnazian Safehold, -601, -100) to finish.' }, { title = 'Tips', note = '• The Mysterious Amulet is removed in the cutscene; it returns later.\n• Set a home point in the Safehold.' }, { title = 'Reward', note = '• Title: Dead Body' } } },
    { name = 'Promathia 2-2: The Lost City', group = 'Chains of Promathia Missions', desc = 'Learn about the Tavnazian Safehold from its people.', steps = { { title = 'Steps', note = '• Talk to Despachiaire in the Tavnazian Safehold.\n• Examine the Sewer Entrance to finish; it then leads to the Phomiuna Aqueducts.' } } },
    { name = 'Promathia 2-3: Distant Beliefs', group = 'Chains of Promathia Missions', desc = 'Kill the Minotaur in the Phomiuna Aqueducts (level cap 40; bring a full party).', steps = { { title = 'Steps', note = '• Enter the Phomiuna Aqueducts via the Sewer Entrance.\n• Defeat the Minotaur.\n• Climb down the Wooden Ladder past the Iron Gate.\n• Examine the Ornate Gate.\n• Talk to Justinius in the Safehold to finish.' }, { title = 'Tips', note = '• Minotaur detects Sneak and Invisible, hits hard, and can draw the party in.\n• Iron Gates open from one side; otherwise use a Bronze Key (Fomor drop) or, as thief, Thief\'s Tools, Skeleton Key or Living Key (consumed).\n• Stand adjacent to ladders.' } } },
    { name = 'Promathia 2-4: An Eternal Melody', group = 'Chains of Promathia Missions', desc = 'Recover your amulet in the Safehold and visit the Misareaux Coast.', steps = { { title = 'Steps', note = '• Examine the Walnut Door in the Safehold; get the Mysterious Amulet back.\n• Examine the Dilapidated Gate in the Misareaux Coast.\n• Back in the Safehold, go to Cutscene spot (0, 22) to finish.' }, { title = 'Tips', note = '• Justinius and Parelbriaux have optional dialogue between steps 1 and 2.' } } },
    { name = 'Promathia 2-5: Ancient Vows', group = 'Chains of Promathia Missions', desc = 'Go through Riverne - Site #A01 to Monarch Linn and beat three Mammet-19 Epsilons (level cap 40).', steps = { { title = 'Steps', note = '• Examine the Dilapidated Gate in the Misareaux Coast.\n• Use the Spatial Displacement and pick Riverne - Site #A01.\n• Cross Riverne to To Monarch Linn (-504, -382).\n• Touch the Spatial Displacement in Monarch Linn and defeat all three Mammet-19 Epsilons; you go to South Gustaberg.' }, { title = 'Tips', note = '• Ancient Vows: 6 players, level cap 40, 30 min, Trusts allowed.\n• Mammets can\'t be slept; every 30-60 s they swap between hands, sword, polearm and staff, casting with the staff.\n• Some Unstable Displacements need a Giant Scale (drake drop) traded to them.\n• Enter Monarch Linn from Site #A01, not #B01.' } } },
    { name = 'Promathia 3-1: The Call of the Wyrmking', group = 'Chains of Promathia Missions', desc = 'Follow Prishe to Bastok to find Cid; no fights.', steps = { { title = 'Steps', note = '• Arrive in South Gustaberg after Ancient Vows for a cutscene.\n• In Port Bastok, go to Cutscene spot (-104, -10) near the home point.\n• Talk to Cid in the Metalworks to finish.' }, { title = 'Tips', note = '• A missed South Gustaberg scene replays on next entry; the Port Bastok scene waits for it.' } } },
    { name = 'Promathia 3-2: A Vessel Without a Captain', group = 'Chains of Promathia Missions', desc = 'Visit Neptune\'s Spire and the Grand Duke\'s palace in Jeuno; no fights.', steps = { { title = 'Steps', note = '• Examine the Neptune\'s Spire door in Lower Jeuno.\n• In Ru\'Lude Gardens, go to Palace entrance (0, 40) to finish.' }, { title = 'Tips', note = '• Harnek (near the door) and Cid (Metalworks) have optional dialogue.' } } },
    { name = 'Promathia 3-3: The Road Forks', group = 'Chains of Promathia Missions', desc = 'Track down people in San d\'Oria and Windurst who remember the old Multinational Expedition, to help locate the fourth mothercrystal.', steps = { { title = 'Overview', note = '• Comes after A Vessel Without a Captain.\n• Two halves, either order; each has one fight versus a roughly level 50 monster.' }, { title = 'San d\'Oria', note = '• Zone into Northern San d\'Oria for a cutscene.\n• Speak with Arnau, then Chasalvige.\n• Carpenters\' Landing: speak with Guilloud, beat Overgrown Ivy, speak with Guilloud again.\n• Finish by speaking with Hinaree (Southern San d\'Oria).' }, { title = 'Windurst', note = '• Zone into Windurst Waters for a cutscene; speak with Ohbiru-Dohbiru.\n• Speak with Yoran-Oran (Windurst Walls), then Kyume-Romeh and Honoi-Gomoi (Windurst Waters).\n• Hand the mirror to Yoran-Oran.\n• Attohwa Chasm: stand on the Loose Sand, examine it, beat Lioumere.\n• Examine the sand again for a Mimeo Jewel; carry it directly to the Cradle of Rebirth.\n• Speak with Yoran-Oran, Yujuju (Port Windurst), Tosuka-Porika (Windurst Waters), then Yoran-Oran.' }, { title = 'Report back', note = '• Once both halves are finished, speak with Cid in the Metalworks.' }, { title = 'Tips', note = '• Re-talk to Guilloud before leaving Carpenters\' Landing.\n• Loose Sand only responds if you are on top of it.\n• Mimeo Jewel vanishes after 30 minutes or on leaving Attohwa Chasm; re-examine the sand for another.' } } },
    { name = 'Promathia 3-4: Tending Aged Wounds', group = 'Chains of Promathia Missions', desc = 'Bastok organised the expedition, but the next lead is in Jeuno. No combat.', steps = { { title = 'Steps', note = '• Comes after The Road Forks.\n• Zone into Lower Jeuno for a cutscene.\n• Examine the Neptune\'s Spire door; the scene finishes the mission.\n• Optional: Cid in the Metalworks gives a reminder scene.' } } },
    { name = 'Promathia 3-5: Darkness Named', group = 'Chains of Promathia Missions', desc = 'Prishe is ill at Doctor Monberaux\'s clinic; the trail runs through Pso\'Xja to a fight with Diabolos.', steps = { { title = 'Steps', note = '• Comes after Tending Aged Wounds.\n• Speak with Monberaux (Upper Jeuno); you lend Prishe the Mysterious Amulet.\n• Speak with Ghebi Damomohe (Lower Jeuno) and trade one Carmine, Cyan or Gray Chip for the Pso\'Xja Pass plus 500 gil.\n• In Pso\'Xja, use the pass on the Stone Gate and continue to the Shrouded Maw.\n• Enter the Memento Circle; beat Diabolos in Darkness Named.\n• Return to Monberaux.' }, { title = 'Tips', note = '• Darkness Named: 6 players, level 40 cap, 30 min, Trusts OK.\n• Diabolos\' Nightmare drops floor tiles; Diremites lurk in the pit.\n• Carmine Chips: Snow/Frost Lizards in Pso\'Xja; Gray Chips: its Diremites.\n• Aldo, Sattal-Mansal and Harnek have optional dialogue beforehand.' } } },
    { name = 'Promathia 4-1: Sheltering Doubt', group = 'Chains of Promathia Missions', desc = 'Follow Prishe back to Tavnazia. No combat.', steps = { { title = 'Steps', note = '• Comes after Darkness Named.\n• Zone into Tavnazian Safehold for a cutscene; speak with Despachiaire.\n• Misareaux Coast: examine the southeastern Dilapidated Gate (not the northwest Ancient Vows gate) to finish.\n• Justinius has optional lines.' } } },
    { name = 'Promathia 4-2: The Savage', group = 'Chains of Promathia Missions', desc = 'Chase Ulmia, with Tenzen and Justinius helping, through Riverne to a fight with Ouryu.', steps = { { title = 'Steps', note = '• Comes after Sheltering Doubt; Riverne - Site #B01 and the fight are level 50 capped.\n• Misareaux Coast: examine the northwestern Dilapidated Gate and continue into Riverne - Site #B01.\n• Cross to the Spatial Displacement to Monarch Linn (around -537, 500).\n• Enter The Savage via the Monarch Linn displacement and beat Ouryu.\n• Speak with Justinius (Tavnazian Safehold) to finish.' }, { title = 'Tips', note = '• The Savage: 6 players, level 50 cap, 30 min, Trusts OK.\n• Must reach Monarch Linn from Site #B01, not #A01.\n• Some small Unstable Displacements need a Giant Scale (dropped by Pyrodrakes/Ignidrakes).\n• Site #B01 home point is beside the Monarch Linn displacement.' }, { title = 'Reward', note = '• Title: Nag\'molada\'s Underling' } } },
    { name = 'Promathia 4-3: The Secrets of Worship', group = 'Chains of Promathia Missions', desc = 'Retrieve your amulet from Prishe by way of the Sacrarium (level 50 cap).', steps = { { title = 'Steps', note = '• Comes after The Savage.\n• Tavnazian Safehold: examine the Walnut Door.\n• Misareaux Coast: examine the Iron Gate to enter the Sacrarium.\n• Examine the Wooden Gate from its east side.\n• Search the ??? drawers at the Sacrarium\'s north and south ends until Old Professor Mariselle appears; defeat it.\n• Search a drawer again for the Reliquiarium Key.\n• Examine the Wooden Gate from the east again to finish.' }, { title = 'Tips', note = '• The professor teleports and summons Mariselle\'s Pupils.\n• Grab the key before leaving the zone.\n• The professor\'s drawer moves each time; check every one.\n• Iron Gate re-admits you to the Sacrarium while the mission is active.\n• Justinius and Parelbriaux have optional lines.' } } },
    { name = 'Promathia 4-4: Slanderous Utterings', group = 'Chains of Promathia Missions', desc = 'Elder Despachiaire summons Prishe, who still holds your amulet. No combat.', steps = { { title = 'Steps', note = '• Comes after The Secrets of Worship.\n• Enter Despachiaire\'s quarters in Tavnazian Safehold for a cutscene.\n• Exit toward Sealion\'s Den (around 0, -42).\n• Examine the Iron Gate in Sealion\'s Den to finish.' }, { title = 'Reward', note = '• Title: The Lost One' } } },
    { name = 'Promathia 5-1: The Enduring Tumult of War', group = 'Chains of Promathia Missions', desc = 'The airship lands in Port Bastok; head to Pso\'Xja to meet Nag\'molada.', steps = { { title = 'Steps', note = '• Comes after Slanderous Utterings. One uncapped fight.\n• Arrive in Port Bastok for a cutscene, then speak with Cid in the Metalworks.\n• Beaucedine Glacier: enter Pso\'Xja by the F-7 Iron Grate (around -340, 159) for a cutscene.\n• Examine the Stone Door; defeat Nunyunuwi (golem, about level 57).\n• Pass through, examine the next Stone Door and proceed.\n• Promyvion - Vahzl: receive the Light of Vahzl; mission done.' }, { title = 'Tips', note = '• Only the F-7 grate triggers the scene.\n• Promyvion - Vahzl is level 50 capped and Desires of Emptiness begins immediately.\n• Despachiaire, Chasalvige and Anoki have optional scenes.' } } },
    { name = 'Promathia 5-2: Desires of Emptiness', group = 'Chains of Promathia Missions', desc = 'Find your companions inside Promyvion - Vahzl, then fight at the Spire of Vahzl (level 50 cap throughout).', steps = { { title = 'Steps', note = '• Comes after The Enduring Tumult of War.\n• At three Memory Fluxes, examine, beat the spawn (Propagator, Solicitor, Ponderer), then examine again; any order.\n• Enter the Spire of Vahzl for a cutscene.\n• Touch the Web of Recollections; beat Agonizer, Procreator and Cumulator.\n• Cutscene in Beaucedine Glacier, then speak with Cid in the Metalworks.' }, { title = 'Tips', note = '• Fight: 6 players, level 50 cap, 30 min, Trusts OK.\n• Spire refuses entry until all three flux scenes are seen.\n• Flux mobs are about level 57; bring a full party.\n• Change floors by killing a Memory Receptacle and entering its stream.\n• Upper Pso\'Xja Stone Door re-enters and can drop you near finished fluxes.\n• Procreator may spawn Offspring.' } } },
    { name = 'Promathia 5-3: Three Paths', group = 'Chains of Promathia Missions', desc = 'After Desires of Emptiness, help Louverance, Tenzen and Ulmia each chase a lead; the paths can be done in any order or together, and each ends with a report to Cid in the Metalworks.', steps = { { title = 'Louverance', note = '• Speak with Despachiaire (Tavnazian Safehold), then Perih Vashai (Windurst Woods).\n• Examine the Warmachine in Bibiki Bay; zone into Oldton Movalpolos.\n• Mine Shaft #2716 (via Newton Movalpolos): touch the Shaft Entrance and win Century of Hardship; report to Cid.\n• Obtain a Gold Key from Newton Movalpolos Goblins/Moblins; trade it to the Shaft Entrance; report to Cid.' }, { title = 'Tenzen', note = '• Examine the ??? in La Theine Plateau.\n• In Beaucedine Glacier, enter Pso\'Xja by the J-8 Iron Grate (around 241, -20) and examine the Avatar Gate.\n• Speak with Monberaux (Upper Jeuno), then Pherimociel (Ru\'Lude Gardens).\n• Batallia Downs: examine the ??? twice.\n• Lower Delkfutt\'s Tower: examine the Cermet Door, beat Disaster Idol, examine again.\n• Enter Pso\'Xja by the H-10 Iron Grate (around 60, -359), examine the Avatar Gate, report to Cid.' }, { title = 'Ulmia', note = '• Speak with Hinaree (Southern San d\'Oria), zone into Port San d\'Oria, then speak with Chasalvige (Northern San d\'Oria).\n• Speak with Kerutoto (Windurst Waters), then Yoran-Oran (Windurst Walls).\n• Boneyard Gully (reached from Attohwa Chasm): touch the Dark Miasma, win Head Wind.\n• Bearclaw Pinnacle (reached from Uleguerand Range): touch the Wind Pillar, win Flames for the Dead; report to Cid.' }, { title = 'Tips', note = '• Century of Hardship: level 60 cap; four Moblins plus Bugbby.\n• Head Wind: level 50 cap; Shikaree X, Y, Z.\n• Flames for the Dead: level 60 cap; Snoll Tzar; no Trusts (other two allow them).\n• All: 6 players, 30 min.\n• Re-examine the Cermet Door before leaving the tower.\n• H-10 scene needs entry by that grate.' }, { title = 'Reward', note = '• Final Cid report completes the mission. Title: Treader of an Icy Past' } } },
    { name = 'Promathia 6-1: For Whom the Verse Is Sung', group = 'Chains of Promathia Missions', desc = 'Prishe was seen in Jeuno; ask at the Grand Duke\'s palace. No combat.', steps = { { title = 'Steps', note = '• Comes after Three Paths.\n• Speak with Pherimociel at the Ru\'Lude Gardens palace.\n• Upper Jeuno: examine the Marble Bridge door.\n• Re-enter Ru\'Lude Gardens for the finishing scene.\n• A Place to Return begins upon approaching the palace.' } } },
    { name = 'Promathia 6-2: A Place to Return', group = 'Chains of Promathia Missions', desc = 'Ulmia seeks Cardinal Mildaurion; the trail leads to three Warders on Misareaux Coast.', steps = { { title = 'Steps', note = '• Comes after For Whom the Verse Is Sung. Warders are level 62-63.\n• Ru\'Lude Gardens: approach the palace entrance (around 0, 50).\n• Misareaux Coast: examine the Dilapidated Gate to spawn Warder Aglaia, Warder Euphrosyne and Warder Thalia; defeat all.\n• Examine the gate again to finish.' }, { title = 'Tips', note = '• Party/alliance members in the zone share credit per kill.\n• Kills persist if you leave.\n• Re-examining the gate respawns all three if credit was missed.\n• Not the Ancient Vows gate; use the map point.' } } },
    { name = 'Promathia 6-3: More Questions Than Answers', group = 'Chains of Promathia Missions', desc = 'Esha\'ntarl prepares the Jeuno Armada while Prishe and Ulmia solve an old mystery. No combat.', steps = { { title = 'Steps', note = '• Comes after A Place to Return.\n• Speak with Pherimociel at the Ru\'Lude Gardens palace.\n• Examine the palace door to the Audience Chamber.\n• Speak with Mathilde in Selbina to finish (Pherimociel and Auchefort only give reminders).' } } },
    { name = 'Promathia 6-4: One to Be Feared', group = 'Chains of Promathia Missions', desc = 'Cid flies you above the sea of clouds for a three-round battle (level 60 cap).', steps = { { title = 'Steps', note = '• Comes after More Questions Than Answers.\n• Speak with Cid in the Metalworks.\n• Enter Sealion\'s Den (via Tavnazian Safehold) for a cutscene.\n• Examine the Iron Gate, then examine again to enter One to Be Feared.\n• Rounds: five Mammet-22 Zeta, then Omega, then Ultima; between rounds you are healed and must examine the Airship Door.\n• Afterward: cutscene, then you land in Lufaise Meadows.' }, { title = 'Tips', note = '• 6 players, level 60 cap, 45 min total, Trusts OK, no EXP loss on death.\n• Win grants 1,500 EXP.\n• Keep one inventory slot free for the next mission\'s item.' } } },
    { name = 'Promathia 7-1: Chains and Bonds', group = 'Chains of Promathia Missions', desc = 'Look for your companions around Tavnazian Safehold after escaping Bahamut. No combat.', steps = { { title = 'Steps', note = '• Starts on landing in Lufaise Meadows; you receive a Dcl.Grd. Ring.\n• Zone into Tavnazian Safehold for a cutscene.\n• In any order: examine the Walnut Door, examine the Sewer Entrance, enter Sealion\'s Den. Third one completes it.' }, { title = 'Tips', note = '• No space for the ring? Free a slot and examine the ??? near your Lufaise Meadows landing spot.' } } },
    { name = 'Promathia 7-2: Flames in the Darkness', group = 'Chains of Promathia Missions', desc = 'Locate Tenzen, then return to Jeuno to meet Esha\'ntarl. No combat.', steps = { { title = 'Steps', note = '• Comes after Chains and Bonds.\n• Misareaux Coast: examine the Dilapidated Gate (the Ancient Vows one).\n• Speak with Sueleen at the Iron Gate in Sealion\'s Den.\n• Ru\'Lude Gardens: approach the palace entrance (around 0, 50).\n• Upper Jeuno: examine the Marble Bridge door to finish.' }, { title = 'Reward', note = '• Title: Esha\'ntarl\'s Comrade in Arms' } } },
    { name = 'Promathia 7-3: Fire in the Eyes of Men', group = 'Chains of Promathia Missions', desc = 'Find the route through Movalpolos toward the fifth mothercrystal, then report to Cid.', steps = { { title = 'Steps', note = '• Comes after Flames in the Darkness. No mission fight.\n• Newton Movalpolos: go into Mine Shaft #2716 and examine the Shaft Entrance.\n• Speak with Cid in the Metalworks.\n• After the next Vana\'diel day begins (game midnight, at most an hour), speak with Cid again to finish.' }, { title = 'Reward', note = '• Title: Prishe\'s Buddy' } } },
    { name = 'Promathia 7-4: Calm Before the Storm', group = 'Chains of Promathia Missions', desc = 'Cid\'s airship propulsion unit is damaged; recall companions from three zones, each ending in a fight versus level 65-70 foes.', steps = { { title = 'Errands (any order)', note = '• Misareaux Coast: examine the Storage Compartment, beat Boggelmann, examine again for the Vessel of Light.\n• Carpenters\' Landing: examine the ???, beat Cryptonberry Executor plus three Cryptonberry Assassins, examine again.\n• Bibiki Bay: examine the ???, beat Dalham, examine again.' }, { title = 'Finish', note = '• Speak with Cid in the Metalworks for Letters from Ulmia and Prishe.\n• Speak with Sueleen in Sealion\'s Den to complete.' }, { title = 'Tips', note = '• Re-examine each object before leaving the zone or the kill is lost.\n• Party/alliance in the zone share credit; each person examines afterward.\n• Kill the Executor first; if an Assassin dies earlier it uses Mijin Gakure and Assassins may use two-hour abilities.' } } },
    { name = 'Promathia 7-5: The Warrior\'s Path', group = 'Chains of Promathia Missions', desc = 'Board the repaired airship at Sealion\'s Den and face Tenzen on the way to the fifth mothercrystal (level 75 cap).', steps = { { title = 'Steps', note = '• Comes after Calm Before the Storm.\n• Examine the Iron Gate in Sealion\'s Den, then again to enter The Warrior\'s Path.\n• Opponents: Tenzen with Makki-Chebukki, Kukki-Chebukki and Cherukiki.\n• Reduce Tenzen to 15% HP to win.\n• Cutscenes in Sealion\'s Den and on arrival in Al\'Taieu finish it.' }, { title = 'Tips', note = '• 6 players, level 75 cap, 30 min, Trusts OK, no EXP loss on death.\n• Tarutaru need not be defeated.\n• At 5 minutes or about 25% HP, Tenzen starts a weapon-skill chain that ends in a loss; hold burst damage to get him under 15% first.\n• Afterward Sueleen can warp you to Al\'Taieu.' }, { title = 'Reward', note = '• Title: Seeker of the Light' } } },
    { name = 'Promathia 8-1: Garden of Antiquity', group = 'Chains of Promathia Missions', desc = 'In Al\'Taieu, clear three Rubious Crystals and follow Nag\'molada toward the palace.', steps = { { title = 'Steps', note = '• Comes after The Warrior\'s Path. Each crystal spawns three Ru\'aern (level 70-71).\n• Examine the Crystalline Field.\n• At each Rubious Crystal (one at around -684, -222, one at 684, -222, plus the first): examine, defeat three Ru\'aern, examine again.\n• Examine the Crystalline Field again; it can send you into the Grand Palace of Hu\'Xzoi.\n• Examine the Gate of the Gods for a Tavnazian Ring.\n• Examine the nearby Particle Gate to finish.' }, { title = 'Tips', note = '• Crystals in any order.\n• Form party/alliance before examining; re-examine before leaving the zone.\n• Need a free slot for the ring; otherwise re-examine the gate later.\n• Sueleen warps to Al\'Taieu; the Crystalline Field keeps offering palace entry.' } } },
    { name = 'Promathia 8-2: A Fate Decided', group = 'Chains of Promathia Missions', desc = 'Pursue Nag\'molada into the depths of the palace with Prishe.', steps = { { title = 'Steps', note = '• Comes after Garden of Antiquity. Ix\'ghrah is level 76-77.\n• Travel through the Grand Palace of Hu\'Xzoi to the Cermet Portal and examine it.\n• Defeat Ix\'ghrah.\n• Examine the portal again to finish.' }, { title = 'Tips', note = '• Party/alliance in the zone share credit; it is saved for later.\n• Gate of the Gods is inactive during this mission.' } } },
    { name = 'Promathia 8-3: When Angels Fall', group = 'Chains of Promathia Missions', desc = 'Pass the Gate of the Gods in the Grand Palace of Hu\'Xzoi, find your race\'s tower, and defeat the Ix\'zdei (level 75 cap).', steps = { { title = 'Steps', note = '• Comes after A Fate Decided.\n• In the Grand Palace of Hu\'Xzoi, examine the Gate of the Gods to reach The Garden of Ru\'Hmet.\n• Particle Gate at -420, -280 gives Brand of Dawn; at -420, -560 gives Brand of Twilight (both needed for the teleporter between them).\n• Examine any Ebon Panel for a cutscene.\n• Stand right next to your race\'s Ebon Panel and accept: Hume 422, -100; Elvaan 740, -342; Tarutaru 258, -700; Mithra 100, -338; Galka 578, -700. Gives a key item and title Warrior of the Crystal.\n• Examine the Particle Gate, then again to enter When Angels Fall; defeat four Ix\'zdei.\n• Examine the Luminous Convergence, then return to Al\'Taieu to finish.' }, { title = 'Tips', note = '• 6 players, level 75 cap, 30 min, Trusts OK, no EXP loss on death; 1,000 EXP for the win.\n• All four Ix\'zdei link.\n• Move closer if the panel asks.' } } },
    { name = 'Promathia 8-4: Dawn', group = 'Chains of Promathia Missions', desc = 'Final Chains of Promathia battle in the Empyreal Paradox, followed by epilogue visits across Vana\'diel.', steps = { { title = 'Battle', note = '• Comes after When Angels Fall; level 75 cap.\n• Via the Gate of the Gods, go to The Garden of Ru\'Hmet and use the teleporter near the Cermet Portal (around -419, 379) to the Empyreal Paradox.\n• Examine the Transcendental Radiance, then again to enter Dawn.\n• With Prishe and Selh\'teus, defeat Promathia and then its second form.\n• You receive the Tear of Altana and land in Al\'Taieu.' }, { title = 'Epilogue', note = '• Wait until 00:00 JST, then do these five in any order:\n• Hinaree (Southern San d\'Oria), enter Uleguerand Range, return and pass the spot near her (around -275, 97).\n• Chipmy-Popmy (Port Windurst), then the ??? in Bibiki Bay for a random colored drop.\n• Enter Mhaura.\n• Enter Oldton Movalpolos.\n• Cid in the Metalworks.\n• Then: Ru\'Lude Gardens palace entrance (around 0, 50).\n• Upper Jeuno Marble Bridge door, twice; pick Rajas Ring, Sattva Ring or Tamas Ring.\n• Tavnazian Safehold Walnut Door.\n• Lufaise Meadows spot around 199, 337 gives the title Banisher of Emptiness.\n• Dawn stays active through Storms of Fate, Shadows of the Departed and Apocalypse Nigh; it ends when Gilgamesh in Norg gives the Apocalypse Nigh reward.' }, { title = 'Tips', note = '• Dawn: 6 players, level 75 cap, 30 min, Trusts OK, no EXP loss on death; 2,000 EXP for the win.\n• Losing Selh\'teus means defeat; a full party wipe ends it instantly.\n• No room for the colored drop? Re-examine the Bibiki Bay ??? later.\n• Discarding your ring blocks a replacement for 27 days.' } } },
}

return S
